__d(function(e,r,s,i,a,t,u){a.exports={pallier:[{auteur:"Voltaire",initiales:"V",oeuvre:"Dictionnaire philosophique, article \xab Esprit \xbb, section IV",epoque:"XVIIIe",texte:"Les actrices ne peuvent plus gu\xe8re les [pallier] par une fiert\xe9 \xe9tudi\xe9e et des \xe9clats de voix s\xe9ducteurs.",glose:"Voltaire parle des d\xe9fauts du r\xf4le de Corn\xe9lie dans une trag\xe9die : les actrices ne peuvent plus les cacher.",source:"https://fr.wikisource.org/wiki/Dictionnaire_philosophique/Garnier_(1878)/Esprit"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Discours sur la transformation du syst\xe8me de sant\xe9, 18 septembre 2018",epoque:"2018",texte:"[\u2026] aujourd'hui l'h\xf4pital est au bout de ce qu'il peut faire pour [pallier] notre d\xe9sorganisation collective et c'est particuli\xe8rement vrai pour ses services d'urgences.",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2018/09/18/discours-sur-la-transformation-du-systeme-de-sante-prendre-soin-de-chacun-du-president-de-la-republique-emmanuel-macron"}],"\xe9ph\xe9m\xe8re":[{auteur:"Alfred de Musset",initiales:"AM",oeuvre:"Souvenir, 1841",epoque:"XIXe",texte:"Ils prirent \xe0 t\xe9moin de leur joie [\xe9ph\xe9m\xe8re] / Un ciel toujours voil\xe9 qui change \xe0 tout moment,",glose:"Deux amoureux \xe9changent leurs premiers serments au pied d'un arbre.",source:"https://fr.wikisource.org/wiki/Souvenir_(Musset,_1841)"},{auteur:"Jacques Chirac",initiales:"JC",oeuvre:"Discours sur les acad\xe9mies de l'Institut de France, 10 octobre 1995",epoque:"1995",texte:"Eclipse [\xe9ph\xe9m\xe8re] puisque Louis-Philippe les r\xe9tablit en 1832.",glose:"Bonaparte avait supprim\xe9 l'Acad\xe9mie des sciences morales et politiques en 1803.",source:"https://www.elysee.fr/jacques-chirac/1995/10/10/discours-de-m-jacques-chirac-president-de-la-republique-sur-lhistoire-et-le-rayonnement-culturel-des-academies-de-linstitut-de-france-paris-le-10-octobre-1995"}],idoine:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Correspondance, lettre \xe0 sa ni\xe8ce Caroline, 27 janvier 1879",epoque:"XIXe",texte:"Quand je me serai fait faire une planche [idoine] pour \xe9crire dans mon lit, [\u2026]",glose:"Flaubert \xe9crit \xe0 sa ni\xe8ce. Une planche idoine, c'est une planche adapt\xe9e.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_8-9/1794"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Point presse depuis Saint-Gervais, 13 f\xe9vrier 2020",epoque:"2020",texte:"[\u2026] nous allons dans les prochaines semaines, l\xe0 aussi, d\xe9p\xeacher une \xe9quipe sp\xe9cifique pour proposer des solutions et un accompagnement [idoine].",glose:"Il parle des entreprises de d\xe9colletage de la vall\xe9e, touch\xe9es par la baisse des commandes automobiles.",source:"https://www.elysee.fr/emmanuel-macron/2020/02/13/point-presse-du-president-emmanuel-macron-depuis-saint-gervais"}],pragmatique:[{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Discours de Tr\xe8bes, octobre 2018",epoque:"2018",texte:"[\u2026] je sais que dans de telles circonstances, il nous faut agir vite et de mani\xe8re [pragmatique].",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2018/10/23/transcription-du-discours-du-president-de-la-republique-a-trebes"},{auteur:"Jacques Chirac",initiales:"JC",oeuvre:"Discours sur l'organisation du syst\xe8me international, 4 novembre 1999",epoque:"1999",texte:"Cette r\xe9forme [pragmatique] des institutions, pr\xe9alable \xe0 tout \xe9largissement, sera l'une des t\xe2ches prioritaires de la pr\xe9sidence fran\xe7aise de l'Union europ\xe9enne, dans quelques mois.",glose:null,source:"https://www.elysee.fr/jacques-chirac/1999/11/04/discours-de-m-jacques-chirac-president-de-la-republique-sur-les-orientations-proposees-par-la-france-pour-organiser-le-systeme-international-dans-un-monde-multipolaire-renover-les-institutions-internationales-et-integrer-une-solidarite-et-une-ethique"}],"inh\xe9rent":[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"Charles Baudelaire (notice biographique)",epoque:"XIXe",texte:"Sa maladie n'eut d'autre cause que les fatigues, les ennuis, les chagrins et les embarras de toute sorte, [inh\xe9rents] \xe0 la vie litt\xe9raire [\u2026]",glose:"Gautier parle de la maladie de son ami, le po\xe8te Baudelaire.",source:"https://fr.wikisource.org/wiki/Charles_Baudelaire_(Gautier)"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Discours aux Rencontres de l'Union des entreprises de proximit\xe9, 16 septembre 2021",epoque:"2021",texte:"En effet, alors que la crise a davantage expos\xe9 les travailleurs ind\xe9pendants aux risques [inh\xe9rents] \xe0 leurs activit\xe9s, [\u2026]",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2021/09/16/discours-du-president-emmanuel-macron-aux-rencontres-de-lunion-des-entreprises-de-proximite"}],"pr\xe9pond\xe9rant":[{auteur:"Jules Verne",initiales:"JV",oeuvre:"L\u2019\xcele \xe0 h\xe9lice, deuxi\xe8me partie, chapitre II",epoque:"XIXe",texte:"Cependant, si l\u2019influence de cette triplice anglaise, am\xe9ricaine et allemande est [pr\xe9pond\xe9rante] en cet archipel, la France est repr\xe9sent\xe9e par des missionnaires catholiques [\u2026]",glose:"L'archipel dont il parle, ce sont les \xeeles Samoa. Une triplice est une alliance de trois pays.",source:"https://fr.wikisource.org/wiki/L%E2%80%99%C3%8Ele_%C3%A0_h%C3%A9lice/Deuxi%C3%A8me_Partie/Chapitre_II"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Adresse aux Fran\xe7ais, 28 octobre 2020",epoque:"2020",texte:"L\u2019\xe2ge est le facteur [pr\xe9pond\xe9rant].",glose:"Il parle des risques face au Covid-19.",source:"https://www.elysee.fr/emmanuel-macron/2020/10/28/adresse-aux-francais-28-octobre"}]}},249,[]);
__d(function(e,s,r,i,a,t,n){a.exports={corroborer:[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 12 octobre 1853",epoque:"XIXe",texte:"Je fais cette observation et je [corrobore] toutes celles qui pr\xe9c\xe8dent, c\u2019est-\xe0-dire la n\xe9cessit\xe9 de beaucoup d\u2019intelligence dans l\u2019imagination [\u2026]",glose:"Le peintre confirme ses remarques pr\xe9c\xe9dentes sur le r\xf4le de l'imagination.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/12_octobre_1853"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Interview \xe0 Al Jazeera, 31 octobre 2020",epoque:"2020",texte:"J'ai vu trop de gens ces derniers jours dire des choses inacceptables sur la France, [corroborer] tous les mensonges qui \xe9taient dits sur nous [\u2026]",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2020/10/31/interview-du-president-emmanuel-macron-a-al-jazeera"}],exhaustif:[{auteur:"Alfred Binet",initiales:"AB",oeuvre:"Les Id\xe9es modernes sur les enfants, 1909, chapitre V",epoque:"XXe",texte:"Notre \xe9num\xe9ration de ces cas ne sera pas [exhaustive], mais nous en dirons assez pour mettre nos lecteurs en face de la complexit\xe9 r\xe9elle des choses [\u2026]",glose:"Le psychologue annonce qu'il ne citera pas tous les cas d'enfants en difficult\xe9 \xe0 l'\xe9cole.",source:"https://fr.wikisource.org/wiki/Les_Id%C3%A9es_modernes_sur_les_enfants/Texte_entier"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"65e anniversaire de la Constitution, 4 octobre 2023",epoque:"2023",texte:"Et quelles sont, sans \xeatre [exhaustif] ici, les principales attentes auxquelles il nous faut r\xe9pondre aujourd'hui ?",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2023/10/04/65-anniversaire-de-la-constitution-de-la-v-republique"}],sempiternel:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Par les champs et par les gr\xe8ves, 1847",epoque:"XIXe",texte:"[\u2026] toute cette racaille de noblesse postiche qui vit [\u2026] sur la [sempiternelle] po\xe9sie des tourelles, des damoiselles, du palefroi [\u2026]",glose:"Flaubert se moque d'une fausse noblesse qui vit toujours des m\xeames clich\xe9s du Moyen \xc2ge. Postiche : faux.",source:"https://fr.wikisource.org/wiki/Par_les_champs_et_par_les_gr%C3%A8ves/Bretagne"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"25e anniversaire de la loi Taubira, 21 mai 2026",epoque:"2026",texte:"Il y a cette [sempiternelle] question qui revient, dans notre pays : quelle est l'identit\xe9 fran\xe7aise ?",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2026/05/21/ceremonie-du-25e-anniversaire-de-la-loi-taubira"}],"vell\xe9it\xe9":[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Les Mis\xe9rables, tome 3, livre 6",epoque:"XIXe",texte:"Il y avait de l\u2019attaque dans cette marche et certainement une [vell\xe9it\xe9] de conqu\xeate.",glose:"Marius marche vers le banc o\xf9 est assise la jeune fille qu'il aime.",source:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_3/Livre_6/04"},{auteur:"Erwan Balanant",initiales:"EB",oeuvre:"Assembl\xe9e nationale, 24 janvier 2024",epoque:"2024",texte:"Elle rendra autrement plus difficile les [vell\xe9it\xe9s] de certains de la remettre en cause par la loi.",glose:"\xab Elle \xbb d\xe9signe l'inscription de l'IVG dans la Constitution.",source:"https://www.assemblee-nationale.fr/dyn/16/comptes-rendus/seance/session-ordinaire-de-2023-2024/premiere-seance-du-mercredi-24-janvier-2024"}],tergiverser:[{auteur:"Choderlos de Laclos",initiales:"CL",oeuvre:"Les Liaisons dangereuses, 1782, lettre 153",epoque:"XVIIIe",texte:"Je sens \xe0 merveille que ce choix vous g\xeane ; qu\u2019il vous conviendrait mieux de [tergiverser] [\u2026]",glose:"Valmont somme Mme de Merteuil de choisir : il sera son amant ou son ennemi.",source:"https://fr.wikisource.org/wiki/Les_Liaisons_dangereuses/Lettre_153"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"V\u0153ux aux arm\xe9es, 20 janvier 2025",epoque:"2025",texte:"Je le dis ici sans [tergiverser].",glose:"Il parle du soutien de la France \xe0 l'Ukraine.",source:"https://www.elysee.fr/emmanuel-macron/2025/01/20/deplacement-a-cesson-sevigne-a-loccasion-des-voeux-aux-armees"}],lapidaire:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 Thieriot, 10 ao\xfbt 1763",epoque:"XVIIIe",texte:"Quand vous voudrez du style [lapidaire], commencez par retrancher les verbes auxiliaires et les articles.",glose:"On lui a demand\xe9 d'\xe9crire une inscription \xe0 graver, qui doit \xeatre tr\xe8s br\xe8ve.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1763/Lettre_5365"},{auteur:"Olivier Dussopt",initiales:"OD",oeuvre:"Assembl\xe9e nationale, 8 f\xe9vrier 2023",epoque:"2023",texte:"Monsieur Bazin, je vous ferai une r\xe9ponse [lapidaire] : cela ne change rien.",glose:"Le ministre r\xe9pond en une phrase \xe0 la question d'un d\xe9put\xe9.",source:"https://www.assemblee-nationale.fr/dyn/16/comptes-rendus/seance/session-ordinaire-de-2022-2023/deuxieme-seance-du-mercredi-08-fevrier-2023"}]}},250,[]);
__d(function(e,i,r,s,t,n,u){t.exports={dichotomie:[{auteur:"Henri Bergson",initiales:"HB",oeuvre:"Les Deux Sources de la morale et de la religion, 1932, chapitre IV",epoque:"XXe",texte:"Mais simplification et complication de la vie r\xe9sultent bien d\u2019une \xab [dichotomie] \xbb, sont bien susceptibles de se d\xe9velopper en \xab double fr\xe9n\xe9sie \xbb [\u2026]",glose:"Bergson parle des deux fa\xe7ons oppos\xe9es de vivre, simple ou compliqu\xe9e, n\xe9es d'une m\xeame tendance qui se s\xe9pare en deux.",source:"https://fr.wikisource.org/wiki/Les_Deux_Sources_de_la_morale_et_de_la_religion/Chapitre_IV"},{auteur:"Alb\xe9ric de Montgolfier",initiales:"AM",oeuvre:"S\xe9nat, d\xe9bat sur le budget 2014, 21 novembre 2013",epoque:"2013",texte:"Il existe une impressionnante [dichotomie] entre la r\xe9alit\xe9 et votre discours d\u2019affichage selon lequel tout va mieux [\u2026]",glose:"Un s\xe9nateur reproche au gouvernement de dire que tout va bien alors que les entreprises sont en difficult\xe9.",source:"https://www.senat.fr/seances/s201311/s20131121/s20131121_mono.html"}],paradigme:[{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Discours sur la transformation du syst\xe8me de sant\xe9, 18 septembre 2018",epoque:"2018",texte:"Aujourd\u2019hui, c\u2019est \xe0 nouveau \xe0 un changement de [paradigme] que nous devons \u0153uvrer.",glose:"Le Pr\xe9sident veut changer en profondeur la fa\xe7on dont fonctionne le syst\xe8me de sant\xe9.",source:"https://www.elysee.fr/emmanuel-macron/2018/09/18/discours-sur-la-transformation-du-systeme-de-sante-prendre-soin-de-chacun-du-president-de-la-republique-emmanuel-macron"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"D\xe9placement au Br\xe9sil (COP30), 6 novembre 2025",epoque:"2025",texte:"L'Accord de Paris fut aussi un changement de [paradigme], investir dans le climat pour stimuler la croissance et le d\xe9veloppement.",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2025/11/06/deplacement-au-bresil"}],fortuit:[{auteur:"Marcel Proust",initiales:"MP",oeuvre:"Pr\xe9face de La Bible d\u2019Amiens, 1904, chapitre IV",epoque:"XXe",texte:"[\u2026] le seul mode de v\xe9rification qui existe pour nos id\xe9es, je veux dire la rencontre [fortuite] avec un grand esprit.",glose:"Proust explique qu'on sait qu'une id\xe9e est juste quand on tombe par hasard sur un grand auteur qui pense la m\xeame chose.",source:"https://fr.wikisource.org/wiki/La_Bible_d%E2%80%99Amiens/Pr%C3%A9face_du_traducteur/Chapitre_IV"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Remise de l'ordre national du M\xe9rite \xe0 Ali Akbar, 28 janvier 2026",epoque:"2026",texte:"C'est une rencontre [fortuite], en pleine rue, qui vous souffle l'id\xe9e de devenir vendeur de journaux \xe0 la cri\xe9e.",glose:"Le Pr\xe9sident raconte comment Ali Akbar est devenu le c\xe9l\xe8bre vendeur de journaux de Saint-Germain-des-Pr\xe9s.",source:"https://www.elysee.fr/emmanuel-macron/2026/01/28/ceremonie-de-remise-des-insignes-de-chevalier-de-lordre-national-du-merite-a-monsieur-ali-akbar"}],"p\xe9remptoire":[{auteur:"Villiers de l\u2019Isle-Adam",initiales:"VI",oeuvre:"Contes cruels, \xab Deux Augures \xbb, 1883",epoque:"XIXe",texte:"Je tiens \xe0 devenir ministre ! r\xe9pond, d\u2019un ton [p\xe9remptoire], le directeur.",glose:"Un directeur de journal annonce son ambition \xe0 un \xe9crivain, d'un ton qui n'admet aucune r\xe9plique.",source:"https://fr.wikisource.org/wiki/Contes_cruels/Deux_Augures"},{auteur:"Bruno Le Maire",initiales:"BL",oeuvre:"Assembl\xe9e nationale, 4 mai 2023",epoque:"2023",texte:"Mais je connais le go\xfbt de certains, ici, pour l\u2019illusion, pour les d\xe9clarations [p\xe9remptoires] et pour le refus de regarder la r\xe9alit\xe9.",glose:"Le ministre de l'\xc9conomie r\xe9pond \xe0 un d\xe9put\xe9 qui critique la dette publique.",source:"https://www.assemblee-nationale.fr/dyn/16/comptes-rendus/seance/session-ordinaire-de-2022-2023/troisieme-seance-du-jeudi-04-mai-2023"}],ostensible:[{auteur:"Honor\xe9 de Balzac",initiales:"HB",oeuvre:"Modeste Mignon, 1844",epoque:"XIXe",texte:"La visite du Grand-\xc9cuyer avait pour raison [ostensible] une affaire colossale [\u2026]",glose:"L'affaire est la raison affich\xe9e de sa visite, pas forc\xe9ment la vraie.",source:"https://fr.wikisource.org/wiki/Modeste_Mignon"},{auteur:"Jacques Chirac",initiales:"JC",oeuvre:"Discours sur la la\xefcit\xe9, 17 d\xe9cembre 2003",epoque:"2003",texte:"En revanche les signes [ostensibles], c'est-\xe0-dire ceux dont le port conduit \xe0 se faire remarquer et reconna\xeetre imm\xe9diatement \xe0 travers son appartenance religieuse, ne sauraient \xeatre admis.",glose:"Le Pr\xe9sident annonce la loi qui interdit \xe0 l'\xe9cole publique les signes religieux tr\xe8s visibles.",source:"https://www.elysee.fr/jacques-chirac/2003/12/17/discours-de-m-jacques-chirac-president-de-la-republique-sur-le-respect-du-principe-de-laicite-dans-la-republique-paris-le-17-decembre-2003"}],subrepticement:[{auteur:"Maurice Barr\xe8s",initiales:"MB",oeuvre:"Les D\xe9racin\xe9s, 1897, chapitre V",epoque:"XIXe",texte:"Il quitta [subrepticement] encore la rue Cujas, et se transporta rue de l\u2019\xc9cole-de-M\xe9decine.",glose:"Un \xe9tudiant pauvre quitte son logement en cachette, sans pr\xe9venir.",source:"https://fr.wikisource.org/wiki/Les_D%C3%A9racin%C3%A9s/V"},{auteur:"Philippe S\xe9guin",initiales:"PS",oeuvre:"Discours sur le trait\xe9 de Maastricht, Assembl\xe9e nationale, 5 mai 1992",epoque:"1992",texte:"Et l'id\xe9e fait [subrepticement] chemin : d\xe9j\xe0 les r\xe9gions traitent directement avec Bruxelles, pour qu\xe9mander des subsides [\u2026]",glose:"Le d\xe9put\xe9 s'inqui\xe8te d'une id\xe9e qui progresse discr\xe8tement : que l'Europe passe par-dessus l'\xc9tat.",source:"https://www.senat.fr/connaitre-le-senat/evenements-et-manifestations-culturelles/les-revisions-de-la-constitution/discours-prononce-par-m-philippe-seguin-le-5-mai1992-a-lassemblee-nationale.html"}]}},251,[]);
__d(function(e,a,i,r,s,o,u){s.exports={vicissitudes:[{auteur:"Alexis de Tocqueville",initiales:"AT",oeuvre:"De la d\xe9mocratie en Am\xe9rique, tome 4, 1840",epoque:"XIXe",texte:"[\u2026] je me souviens d\u2019avoir lu un roman chinois o\xf9 le h\xe9ros, apr\xe8s beaucoup de [vicissitudes], touche enfin le c\u0153ur de sa ma\xeetresse en passant un bon examen.",glose:"Tocqueville parle de la Chine, o\xf9 il fallait r\xe9ussir un concours \xe0 chaque \xe9tape de sa carri\xe8re.",source:"https://fr.wikisource.org/wiki/De_la_d%C3%A9mocratie_en_Am%C3%A9rique/%C3%89dition_1848/Tome_4/Troisi%C3%A8me_partie/Chapitre_19"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"100e Congr\xe8s des maires de France, 23 novembre 2017",epoque:"2017",texte:"On s\u2019habitue \xe0 toujours reprocher \xe0 l\u2019\xc9tat les [vicissitudes] qui nous tombent dessus et c\u2019est difficile de revenir sur des habitudes.",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2017/11/23/discours-du-president-de-la-republique-emmanuel-macron-au-100-congres-des-maires-de-france"}],"obsol\xe8te":[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"Le Capitaine Fracasse, 1863, chapitre III",epoque:"XIXe",texte:"\xc0 c\xf4t\xe9 d\u2019elle les Parques sont des poupines ; elle est si confite en v\xe9tust\xe9, si [obsol\xe8te] et moisie, qu\u2019aucune fontaine de Jouvence ne la pourrait rajeunir.",glose:"Un com\xe9dien se moque d\u2019une tr\xe8s vieille femme. Les Parques sont les d\xe9esses du destin, imagin\xe9es comme des vieilles.",source:"https://fr.wikisource.org/wiki/Le_Capitaine_Fracasse/Chapitre_III"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Discours devant le Congr\xe8s \xe0 Versailles, 9 juillet 2018",epoque:"2018",texte:"Vous avez lev\xe9 les blocages du march\xe9 du travail cr\xe9\xe9s par un Code devenu [obsol\xe8te] et inadapt\xe9.",glose:"Le \xab Code \xbb est le Code du travail.",source:"https://www.elysee.fr/emmanuel-macron/2018/07/12/discours-du-president-de-la-republique-devant-le-parlement-reuni-en-congres-a-versailles"}],"\xe9mulation":[{auteur:"Jean-Jacques Rousseau",initiales:"JR",oeuvre:"\xc9mile, ou De l\u2019\xe9ducation, 1762, livre II",epoque:"XVIIIe",texte:"Il est bien \xe9trange que, depuis qu\u2019on se m\xeale d\u2019\xe9lever des enfants, on n\u2019ait imagin\xe9 d\u2019autre instrument pour les conduire que l\u2019[\xe9mulation], la jalousie, l\u2019envie, la vanit\xe9 [\u2026]",glose:"Rousseau reproche aux \xe9ducateurs de motiver les enfants en les mettant en rivalit\xe9.",source:"https://fr.wikisource.org/wiki/%C3%89mile,_ou_De_l%E2%80%99%C3%A9ducation/%C3%89dition_1852/Livre_II"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"60e anniversaire du trait\xe9 de l\u2019\xc9lys\xe9e, Sorbonne, 22 janvier 2023",epoque:"2023",texte:"Ils ont altern\xe9 pendant tant de si\xe8cles entre l'[\xe9mulation], la fascination, la comp\xe9tition.",glose:"\xab Ils \xbb, ce sont la France et l\u2019Allemagne.",source:"https://www.elysee.fr/emmanuel-macron/2023/01/22/celebration-du-60eme-anniversaire-du-traite-de-lelysee-a-la-sorbonne"}],"al\xe9atoire":[{auteur:"Honor\xe9 de Balzac",initiales:"HB",oeuvre:"Z. Marcas, 1840",epoque:"XIXe",texte:"Ne voyez-vous pas dans la construction du Z une allure contrari\xe9e ? ne figure-t-elle pas le zigzag [al\xe9atoire] et fantasque d\u2019une vie tourment\xe9e ?",glose:"Le narrateur imagine que la lettre Z du nom du personnage annonce sa vie chaotique.",source:"https://fr.wikisource.org/wiki/Z._Marcas"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Hommage national \xe0 Samuel Paty, 21 octobre 2020",epoque:"2020",texte:"Vendredi soir, j\u2019ai d\u2019abord cru \xe0 la folie [al\xe9atoire], \xe0 l\u2019arbitraire absurde : une victime de plus du terrorisme gratuit.",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2020/10/21/ceremonie-dhommage-national-a-samuel-paty-a-la-sorbonne"}],probant:[{auteur:"Honor\xe9 de Balzac",initiales:"HB",oeuvre:"La Fille aux yeux d\u2019or, 1835",epoque:"XIXe",texte:"Que penserions-nous d\u2019une femme qui ne se laisserait pas s\xe9duire par une lettre d\u2019amour accompagn\xe9e de circonstances si [probantes] ?",glose:null,source:"https://fr.wikisource.org/wiki/La_Fille_aux_yeux_d%E2%80%99or"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"\xc9tats g\xe9n\xe9raux de l\u2019alimentation, 11 octobre 2017",epoque:"2017",texte:"Nous devons avoir des r\xe9sultats [probants] avec de v\xe9ritables organisations de producteurs commerciales pour le lait [\u2026]",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2017/10/11/discours-du-president-de-la-republique-aux-etats-generaux-de-l-alimentation"}],"galvaud\xe9":[{auteur:"Paul Verlaine",initiales:"PV",oeuvre:"\u0152uvres posthumes, \xab Notes sur la po\xe9sie contemporaine \xbb",epoque:"XIXe",texte:"[\u2026] \xe0 une \xe9poque o\xf9 le mot \xab divin \xbb, \xe9nerv\xe9, [galvaud\xe9], devenu banal de nos jours, avait toute sa force glorificatrice !",glose:"Au temps de Victor Hugo, le mot \xab divin \xbb avait encore toute sa force. \xab \xc9nerv\xe9 \xbb veut dire ici affaibli.",source:"https://fr.wikisource.org/wiki/%C5%92uvres_posthumes_(Verlaine)/Notes_sur_la_po%C3%A9sie_contemporaine"},{auteur:"Fran\xe7ois Hollande",initiales:"FH",oeuvre:"Discours sur la gauche au pouvoir, 3 mai 2016",epoque:"2016",texte:"L'\xe9nergie qu'il faut y mettre c'est le compromis, je n'ose pas dire la synth\xe8se, le mot est [galvaud\xe9], \xe0 tort.",glose:null,source:"https://www.elysee.fr/francois-hollande/2016/05/03/declaration-de-m-francois-hollande-president-de-la-republique-sur-la-gauche-au-pouvoir-et-sur-la-politique-gouvernementale-a-paris-le-3-mai-2016"}]}},252,[]);
__d(function(e,r,s,t,n,i,a){n.exports={"s\xe9rendipit\xe9":[{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"D\xe9placement en R\xe9publique d\xe9mocratique du Congo, mars 2023",epoque:"2023",texte:"La [s\xe9rendipit\xe9], c'est le mariage, en effet, du hasard et de la t\xe9nacit\xe9.",glose:"Le pr\xe9sident remercie le directeur d'un grand institut de recherche congolais.",source:"https://www.elysee.fr/emmanuel-macron/2023/03/05/deplacement-en-republique-democratique-du-congo"},{auteur:"Jo\xeblle Forest",initiales:"JF",oeuvre:"\xab Comment trouver ce qu'on ne cherche pas \xbb, Herodote.net, 7 mai 2022",epoque:"2022",texte:"L\u2019histoire de la d\xe9couverte du proc\xe9d\xe9 de vulcanisation rel\xe8ve elle aussi de la [s\xe9rendipit\xe9].",glose:"La vulcanisation est le proc\xe9d\xe9 qui rend le caoutchouc solide et \xe9lastique.",source:"https://www.herodote.net/Comment_trouver_ce_qu_on_ne_cherche_pas-synthese-2449-40.php"}],"r\xe9silience":[{auteur:"Boris Cyrulnik",initiales:"BC",oeuvre:"Entretien publi\xe9 par Public S\xe9nat, 19 juin 2022",epoque:"2022",texte:"Nous ne sommes pas tous \xe9gaux devant la [r\xe9silience]",glose:"Boris Cyrulnik est le psychiatre qui a fait conna\xeetre en France l'id\xe9e de r\xe9silience.",source:"https://www.publicsenat.fr/actualites/societe/boris-cyrulnik-nous-ne-sommes-pas-tous-egaux-devant-la-resilience-213653"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"V\u0153ux aux Fran\xe7ais, 31 d\xe9cembre 2020",epoque:"2020",texte:"Notre Nation a travers\xe9 cette ann\xe9e avec une telle unit\xe9 et une telle [r\xe9silience] : rien ne peut lui r\xe9sister.",glose:"Le bilan de 2020, l'ann\xe9e de l'\xe9pid\xe9mie de Covid-19.",source:"https://www.elysee.fr/emmanuel-macron/2020/12/31/voeux-2021-aux-francais"}],acerbe:[{auteur:"Honor\xe9 de Balzac",initiales:"HB",oeuvre:"Illusions perdues, \xab Un grand homme de province \xe0 Paris \xbb",epoque:"XIXe",texte:"Les plaisanteries [acerbes] commenc\xe8rent au moment o\xf9 les friandises du dessert et les vins circul\xe8rent.",glose:null,source:"https://fr.wikisource.org/wiki/Illusions_perdues/Un_grand_homme_de_province_%C3%A0_Paris"},{auteur:"Christophe Naegelen",initiales:"CN",oeuvre:"Assembl\xe9e nationale, 14 octobre 2025",epoque:"2025",texte:"[\u2026] les propos [acerbes] et accusatoires tenus hier \xe0 Charm el-Cheikh ne facilitent pas le travail que vous menez pour restaurer la confiance dans cet h\xe9micycle.",glose:"Un d\xe9put\xe9 s'adresse au Premier ministre. L'h\xe9micycle est la salle o\xf9 si\xe8gent les d\xe9put\xe9s.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/seance-du-mardi-14-octobre-2025"}],"intrins\xe8que":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 George Sand, octobre 1871",epoque:"XIXe",texte:"La valeur [intrins\xe8que] d\u2019un livre n\u2019est rien dans l\u2019\xe9cole Sainte-Beuve, Taine.",glose:"Sainte-Beuve et Taine sont deux grands critiques litt\xe9raires de l'\xe9poque.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_6/1216"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"R\xe9ception pour l'avenir de la recherche, 7 d\xe9cembre 2023",epoque:"2023",texte:"[\u2026] en soi la science, la recherche de la v\xe9rit\xe9, la volont\xe9 de b\xe2tir un progr\xe8s collectif de la connaissance [\u2026] est une valeur [intrins\xe8que] [\u2026].",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2023/12/07/reception-pour-lavenir-de-la-recherche-francaise"}],"r\xe9current":[{auteur:"Philippe Tabarot",initiales:"PT",oeuvre:"Assembl\xe9e nationale, 3 juin 2025",epoque:"2025",texte:"L\u2019autoroute A31, vous l\u2019avez dit, conna\xeet des saturations [r\xe9currentes] qui p\xe9nalisent les travailleurs frontaliers et les habitants de votre territoire.",glose:"Des saturations, ce sont des bouchons sur la route.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/premiere-seance-du-mardi-03-juin-2025"},{auteur:"Patrick Mignola",initiales:"PM",oeuvre:"Assembl\xe9e nationale, 8 avril 2025",epoque:"2025",texte:"Se pose aussi la question [r\xe9currente] du vote par correspondance sur laquelle d\u2019autres pays sont bien plus avanc\xe9s que le n\xf4tre [\u2026].",glose:null,source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/premiere-seance-du-mardi-08-avril-2025"}],procrastiner:[{auteur:"Marcel Proust",initiales:"MP",oeuvre:"La Prisonni\xe8re, 1923",epoque:"XXe",texte:"[\u2026] cette habitude, vieille de tant d\u2019ann\xe9es, de l\u2019ajournement perp\xe9tuel, de ce que M. de Charlus fl\xe9trissait sous le nom de [procrastination] [\u2026]",glose:"Fl\xe9trir, ici, c'est condamner durement. M. de Charlus est un personnage du roman.",source:"https://fr.wikisource.org/wiki/La_Prisonni%C3%A8re/Chapitre_1"},{auteur:"Maxime Laisney",initiales:"ML",oeuvre:"Assembl\xe9e nationale, 18 juin 2025",epoque:"2025",texte:"[\u2026] vous resterez vraiment dans l\u2019histoire comme le minist\xe8re de la [procrastination] !",glose:"Un d\xe9put\xe9 reproche au gouvernement de toujours remettre \xe0 plus tard les mesures pour le climat.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/deuxieme-seance-du-mercredi-18-juin-2025"}]}},253,[]);
__d(function(e,r,s,i,n,t,a){n.exports={gageure:[{auteur:"Ren\xe9 Doumic",initiales:"RD",oeuvre:"Revue dramatique, Revue des Deux Mondes, 1901",epoque:"XXe",texte:"Voil\xe0 une pi\xe8ce int\xe9ressante o\xf9 l\u2019on ne s\u2019int\xe9resse \xe0 personne. Et cela tient de la [gageure] !",glose:"Le critique trouve presque impossible qu'une pi\xe8ce passionne sans aucun personnage attachant.",source:"https://fr.wikisource.org/wiki/Revue_dramatique_-_14_novembre_1901"},{auteur:"Danielle Simonnet",initiales:"DS",oeuvre:"Assembl\xe9e nationale, 24 juin 2026",epoque:"2026",texte:"[\u2026] d\xe9crocher un rendez-vous en pr\xe9fecture rel\xe8ve de la [gageure] en ce moment.",glose:"La d\xe9put\xe9e explique qu'obtenir un rendez-vous pour renouveler un titre de s\xe9jour est devenu presque impossible.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-mercredi-24-juin-2026"}],dilemme:[{auteur:"Eug\xe8ne Beyens",initiales:"EB",oeuvre:"Impression de Berlin, Revue des Deux Mondes, 1919",epoque:"XXe",texte:"Nous sommes devant un [dilemme] inqui\xe9tant : ou aider dans une juste mesure \xe0 la solvabilit\xe9 de notre d\xe9bitrice, [\u2026] ou chercher \xe0 nous d\xe9barrasser de cette rivalit\xe9 [\u2026]",glose:"Le diplomate h\xe9site entre aider l'Allemagne \xe0 payer ses dettes ou l'affaiblir comme concurrente.",source:"https://fr.wikisource.org/wiki/Impression_de_Berlin"},{auteur:"Fr\xe9d\xe9ric Maillot",initiales:"FM",oeuvre:"Assembl\xe9e nationale, 11 juin 2026",epoque:"2026",texte:"Manger, boire et payer ses factures ou bien garder sa maison, tel est le [dilemme] que pose l\u2019obtention de l\u2019Aspa [\u2026]",glose:"Le d\xe9put\xe9 parle d'une aide aux retrait\xe9s pauvres, qui peut \xeatre r\xe9cup\xe9r\xe9e plus tard sur leur maison.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-jeudi-11-juin-2026"}],caduc:[{auteur:"Edgar Quinet",initiales:"EQ",oeuvre:"Merlin l\u2019enchanteur, 1860, livre X",epoque:"XIXe",texte:"Sottes id\xe9es, [caduques], us\xe9es jusqu\u2019\xe0 la corde, qui ne rapportent plus ce qu\u2019elles co\xfbtent.",glose:"On reproche \xe0 Merlin de d\xe9fendre des id\xe9es d\xe9pass\xe9es par son \xe9poque.",source:"https://fr.wikisource.org/wiki/Merlin_l%E2%80%99enchanteur/Livre_X"},{auteur:"Florence Joubert",initiales:"FJ",oeuvre:"Assembl\xe9e nationale, 17 f\xe9vrier 2026",epoque:"2026",texte:"[\u2026] des pertes financi\xe8res pour d\xe9dommager les annonceurs, dont les campagnes deviennent [caduques] du fait de la distribution trop tardive.",glose:"La d\xe9put\xe9e parle des journaux livr\xe9s trop tard par la poste : les publicit\xe9s qu'ils contiennent ne servent plus \xe0 rien.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-mardi-17-fevrier-2026"}],"r\xe9mun\xe9rer":[{auteur:"Jules Verne",initiales:"JV",oeuvre:"Le Volcan d\u2019or, partie I, chapitre 6",epoque:"XXe",texte:"Apr\xe8s avoir livr\xe9 ses tr\xe9sors m\xe9talliques, la terre suffisait encore \xe0 [r\xe9mun\xe9rer] le travail.",glose:"Une fois l'or \xe9puis\xe9, la terre restait assez fertile pour faire vivre ceux qui la travaillaient.",source:"https://fr.wikisource.org/wiki/Le_Volcan_d%E2%80%99or/Partie_I/Chapitre_6"},{auteur:"S\xe9bastien Lecornu",initiales:"SL",oeuvre:"Assembl\xe9e nationale, 24 octobre 2025",epoque:"2025",texte:"Valoriser le travail, c\u2019est mieux [r\xe9mun\xe9rer] celles et ceux qui s\u2019engagent, all\xe9ger les charges qui p\xe8sent sur les actifs [\u2026]",glose:"Le Premier ministre pr\xe9sente le budget 2026.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-vendredi-24-octobre-2025"}],conjoncture:[{auteur:"Charles de Mazade",initiales:"CM",oeuvre:"Chronique de la quinzaine, Revue des Deux Mondes, 14 mars 1891",epoque:"XIXe",texte:"Dans la [conjoncture] actuelle, la Banque de France avance 60 millions, le syndicat garantit le recouvrement de cette somme jusqu\u2019\xe0 concurrence de 15 millions.",glose:"Il s'agit de sauver une banque en difficult\xe9.",source:"https://fr.wikisource.org/wiki/Chronique_de_la_quinzaine_-_14_mars_1891"},{auteur:"Am\xe9lie de Montchalin",initiales:"AM",oeuvre:"Assembl\xe9e nationale, 3 d\xe9cembre 2025",epoque:"2025",texte:"Dans la [conjoncture] qui est la n\xf4tre, je le r\xe9p\xe8te, il nous semble int\xe9ressant d\u2019ouvrir \xe0 toutes les entreprises cette d\xe9duction forfaitaire [\u2026]",glose:"La ministre veut all\xe9ger le co\xfbt des heures suppl\xe9mentaires alors que la croissance est fragile.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-mercredi-03-decembre-2025"}],"\xe9minent":[{auteur:"Camille Lebrun",initiales:"CL",oeuvre:"Le Mineur de Wielicszka (recueil), 1867, \xab Une Sc\xe8ne d\u2019Int\xe9rieur \xbb",epoque:"XIXe",texte:"Benjamin Franklin fut \xe0 la fois un savant [\xe9minent], un fin diplomate et un habile l\xe9gislateur.",glose:null,source:"https://fr.wikisource.org/wiki/Le_Mineur_de_Wielicszka_(recueil)/Une_Sc%C3%A8ne_d%E2%80%99Int%C3%A9rieur"},{auteur:"Jacques Chirac",initiales:"JC",oeuvre:"Discours au CERN, Gen\xe8ve, 19 octobre 2004",epoque:"2004",texte:"L'effort que la France s'appr\xeate \xe0 consentir, tout au long des prochaines ann\xe9es, marque la reconnaissance par la collectivit\xe9 nationale du r\xf4le des chercheurs et de leur place [\xe9minente] dans la soci\xe9t\xe9.",glose:null,source:"https://www.elysee.fr/jacques-chirac/2004/10/19/declaration-de-m-jacques-chirac-president-de-la-republique-sur-le-role-et-limportance-du-cern-et-sur-les-politiques-en-faveur-de-la-recherche-au-niveau-francais-et-europeen-a-geneve-le-19-octobre-2004"}]}},254,[]);
__d(function(e,s,t,i,r,a,o){r.exports={acception:[{auteur:"Prosper M\xe9rim\xe9e",initiales:"PM",oeuvre:"La Double M\xe9prise, 1833, chapitre I",epoque:"XIXe",texte:"[\u2026] il avait de la gaiet\xe9, et \xe9tait dans toute l\u2019[acception] du mot ce qu\u2019on appelle un bon enfant.",glose:"Le narrateur d\xe9crit Chaverny, le futur mari de Julie, au moment de leur mariage.",source:"https://fr.wikisource.org/wiki/La_Double_M%C3%A9prise/I"},{auteur:"Fran\xe7oise Gatel",initiales:"FG",oeuvre:"S\xe9nat, s\xe9ance du 22 octobre 2025",epoque:"2025",texte:"L\u2019article 5 introduit le mot \xab statut \xbb dans le code g\xe9n\xe9ral des collectivit\xe9s territoriales. Nous l\u2019avons fait ! Ce terme admet certes des [acceptions] diff\xe9rentes.",glose:"La ministre parle du texte sur le statut de l'\xe9lu local.",source:"https://www.senat.fr/seances/s202510/s20251022/s20251022_mono.html"}],apanage:[{auteur:"Judith Gautier",initiales:"JG",oeuvre:"Le Japon, 1912, \xab Des diff\xe9rents types \xbb",epoque:"XXe",texte:"[\u2026] les gaies physionomies chinoises appartiennent \xe0 des hommes insouciants, rieurs et de bonne humeur, tandis que le masque japonais est l\u2019[apanage] de gens silencieux, port\xe9s \xe0 la m\xe9lancolie [\u2026]",glose:"L'autrice compare deux types de visages qu'elle observe au Japon.",source:"https://fr.wikisource.org/wiki/Le_Japon_(Gautier)/Des_diff%C3%A9rents_types"},{auteur:"S\xe9bastien Martin",initiales:"SM",oeuvre:"Assembl\xe9e nationale, 27 novembre 2025",epoque:"2025",texte:"La nationalisation n\u2019est pas un tabou. Elle n\u2019a jamais \xe9t\xe9 non plus l\u2019[apanage] d\u2019un seul parti politique [\u2026]",glose:"Le ministre d\xe9l\xe9gu\xe9 \xe0 l'industrie r\xe9pond aux d\xe9put\xe9s qui veulent nationaliser ArcelorMittal.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/deuxieme-seance-du-jeudi-27-novembre-2025"}],"panac\xe9e":[{auteur:"Michel Chevalier",initiales:"MC",oeuvre:"L\u2019\xc9conomie politique et le Socialisme, 1849",epoque:"XIXe",texte:"Ainsi, chaque \xe9cole, chaque fraction d\u2019\xe9cole, se pr\xe9sente avec sa [panac\xe9e] sociale, qui contient le secret de rendre le peuple heureux infailliblement [\u2026]",glose:"L'\xe9conomiste se moque des doctrines qui promettent de r\xe9gler tous les probl\xe8mes de la soci\xe9t\xe9.",source:"https://fr.wikisource.org/wiki/L%E2%80%99%C3%89conomie_politique_et_le_Socialisme"},{auteur:"Patrick Kanner",initiales:"PK",oeuvre:"S\xe9nat, s\xe9ance du 25 f\xe9vrier 2026",epoque:"2026",texte:"J\u2019y insiste, la nationalisation n\u2019est pas la [panac\xe9e] ; elle est un levier [\u2026]",glose:"Le s\xe9nateur d\xe9fend la nationalisation d'ArcelorMittal France, sans en attendre qu'elle r\xe8gle tout.",source:"https://www.senat.fr/seances/s202602/s20260225/s20260225_mono.html"}],"pl\xe9thore":[{auteur:"Paul Lafargue",initiales:"PL",oeuvre:"Le Droit \xe0 la paresse, 1883",epoque:"XIXe",texte:"Alors, parce qu\u2019il y a [pl\xe9thore] de marchandises et p\xe9nurie d\u2019acheteurs, les ateliers se ferment [\u2026]",glose:"L'auteur d\xe9crit les crises de surproduction qui touchent les ouvriers.",source:"https://fr.wikisource.org/wiki/Le_Droit_%C3%A0_la_paresse"},{auteur:"Jean-Pierre Sueur",initiales:"JS",oeuvre:"S\xe9nat, s\xe9ance du 19 d\xe9cembre 2013",epoque:"2013",texte:"Par ailleurs, la suppression du Haut conseil des territoires me semble positive. Il existe d\xe9j\xe0 [pl\xe9thore] de conseils et de structures.",glose:"Le pr\xe9sident de la commission des lois commente la r\xe9forme des collectivit\xe9s territoriales.",source:"https://www.senat.fr/seances/s201312/s20131219/s20131219_mono.html"}],"\xe9tayer":[{auteur:"Joris-Karl Huysmans",initiales:"JH",oeuvre:"En route, 1895, partie I, chapitre 9",epoque:"XIXe",texte:"[\u2026] je n\u2019ai pas de raisons pour juger que ces arguments sont plus d\xe9biles que les motifs purement physiques qui servent \xe0 [\xe9tayer] mon autre th\xe8se.",glose:"Le h\xe9ros p\xe8se ses raisons de croire et ses raisons de douter.",source:"https://fr.wikisource.org/wiki/En_route/I/09."},{auteur:"Mathieu Darnaud",initiales:"MD",oeuvre:"S\xe9nat, s\xe9ance du 9 juillet 2025",epoque:"2025",texte:"Mais c\u2019est tout simplement parce que, m\xeame avec un argument massue [\u2026] il faut [\xe9tayer] son argumentaire\u2026",glose:"Le s\xe9nateur critique la r\xe9forme du mode de scrutin \xe0 Paris, Lyon et Marseille.",source:"https://www.senat.fr/seances/s202507/s20250709/s20250709_mono.html"}],"ent\xe9riner":[{auteur:"Eug\xe8ne-Fran\xe7ois Vidocq",initiales:"EV",oeuvre:"M\xe9moires, 1828, \xab Au lecteur \xbb",epoque:"XIXe",texte:"Au mois de juillet dernier, j\u2019allai \xe0 Douai pour faire [ent\xe9riner] des lettres de gr\xe2ces qui m\u2019avaient \xe9t\xe9 accord\xe9es en 1818.",glose:"L'ancien bagnard devenu policier fait valider officiellement sa gr\xe2ce par la justice.",source:"https://fr.wikisource.org/wiki/M%C3%A9moires_(Vidocq)/Au_lecteur"},{auteur:"Jean-Fran\xe7ois Husson",initiales:"JH",oeuvre:"S\xe9nat, s\xe9ance du 3 d\xe9cembre 2025",epoque:"2025",texte:"Le compromis qui a \xe9t\xe9 trouv\xe9 entre les deux assembl\xe9es permet d\u2019[ent\xe9riner] l\u2019int\xe9gralit\xe9 des modifications de cr\xe9dits que nous avons adopt\xe9es au S\xe9nat [\u2026]",glose:"Le rapporteur commente l'accord entre d\xe9put\xe9s et s\xe9nateurs sur le budget de fin d'ann\xe9e 2025.",source:"https://www.senat.fr/seances/s202512/s20251203/s20251203001.html"}]}},255,[]);
__d(function(e,r,s,t,i,o,u){i.exports={exacerber:[{auteur:"Madame Dandurand",initiales:"MD",oeuvre:"Nos travers, 1901, \xab Les \xe9mancip\xe9es \xbb",epoque:"XXe",texte:"L\u2019habitude des louanges, l\u2019adulation ont tellement [exacerb\xe9] sa vanit\xe9 que d\u2019en manquer un seul jour ferait son malheur.",glose:"L'autrice d\xe9crit une coquette qui ne peut plus se passer des compliments.",source:"https://fr.wikisource.org/wiki/Nos_travers/Les_%C3%A9mancip%C3%A9es"},{auteur:"Pierre-Antoine Levi",initiales:"PL",oeuvre:"S\xe9nat, 17 janvier 2024",epoque:"2024",texte:"Selon lui, ces espaces r\xe9serv\xe9s aux supporters visiteurs ne font qu\u2019[exacerber] les tensions et contribuent \xe0 l\u2019escalade de la violence.",glose:"Le s\xe9nateur rapporte l'avis d'un pr\xe9sident de club de football sur les tribunes r\xe9serv\xe9es aux supporters adverses.",source:"https://www.senat.fr/seances/s202401/s20240117/s20240117_mono.html"}],"pr\xf4ner":[{auteur:"Romain Rolland",initiales:"RR",oeuvre:"La Foire sur la place, 1908, premi\xe8re partie",epoque:"XXe",texte:"Pour la musique nouvelle, la doctrine qu\u2019on [pr\xf4nait] \xe9tait un \xe9clectisme tr\xe8s aristocratique [\u2026]",glose:"Le romancier d\xe9crit les id\xe9es musicales \xe0 la mode \xe0 Paris.",source:"https://fr.wikisource.org/wiki/La_Foire_sur_la_place/I/12"},{auteur:"Olga Givernet",initiales:"OG",oeuvre:"S\xe9nat, 16 octobre 2024",epoque:"2024",texte:"Nous [pr\xf4nons] un d\xe9veloppement des EnR proportionn\xe9 par pays en fonction du degr\xe9 de d\xe9carbonation de chacun.",glose:"EnR veut dire \xe9nergies renouvelables. La ministre parle des objectifs europ\xe9ens.",source:"https://www.senat.fr/seances/s202410/s20241016/s20241016_mono.html"}],fustiger:[{auteur:"Eug\xe8ne Rambert",initiales:"ER",oeuvre:"\xc9tudes litt\xe9raires, 1890, \xab Le scepticisme de la critique litt\xe9raire \xbb",epoque:"XIXe",texte:"Ce joyeux rieur a \xe9t\xe9 le plus satirique des po\xe8tes, et il a [fustig\xe9] les Ath\xe9niens comme Moli\xe8re les Fran\xe7ais.",glose:"Le critique parle d'Aristophane, auteur comique de la Gr\xe8ce antique.",source:"https://fr.wikisource.org/wiki/%C3%89tudes_litt%C3%A9raires,_t1,_1890/Le_scepticisme_de_la_critique_litt%C3%A9raire"},{auteur:"Thomas Dossus",initiales:"TD",oeuvre:"S\xe9nat, 13 mars 2024",epoque:"2024",texte:"On [fustige] souvent le Gouvernement pour son manque de respect du Parlement, mais, mes chers coll\xe8gues, commen\xe7ons d\xe9j\xe0 par nous respecter nous-m\xeames.",glose:"Le s\xe9nateur regrette le peu de temps laiss\xe9 pour lire un rapport de 725 pages.",source:"https://www.senat.fr/seances/s202403/s20240313/s20240313_mono.html"}],"\xe9dulcorer":[{auteur:"Laurent Tailhade",initiales:"LT",oeuvre:"\xc0 travers les grouins, 1899, \xab Pr\xe9cautions oratoires \xbb",epoque:"XIXe",texte:"Ne pourrait-on, en un langage plus civil, dire les m\xeames choses, [\xe9dulcorer] par un sucre de biens\xe9ances l\u2019\xe2pret\xe9 des invectives [\u2026]",glose:"Le pol\xe9miste rapporte le reproche qu'on lui fait d'\xe9crire avec trop de violence.",source:"https://fr.wikisource.org/wiki/%C3%80_travers_les_grouins/Pr%C3%A9cautions_oratoires"},{auteur:"Jean-Marc Ruel",initiales:"JR",oeuvre:"S\xe9nat, 5 mars 2025",epoque:"2025",texte:"Nous h\xe9ritons aujourd\u2019hui, en s\xe9ance, d\u2019une proposition largement [\xe9dulcor\xe9e].",glose:"Le s\xe9nateur regrette qu'une proposition de loi sur l'\xe9conomie des outre-mer ait \xe9t\xe9 adoucie avant le d\xe9bat.",source:"https://www.senat.fr/seances/s202503/s20250305/s20250305_mono.html"}],circonspect:[{auteur:"Fr\xe9d\xe9ric II de Prusse",initiales:"FP",oeuvre:"Lettre \xe0 Voltaire, 1760",epoque:"XVIIIe",texte:"[\u2026] il n\u2019en est pas de m\xeame du public ; il faut \xeatre plus [circonspect] en \xe9crivant pour lui que pour ses amis.",glose:"Le roi explique \xe0 Voltaire qu'on \xe9crit avec plus de prudence pour le public que pour ses proches.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1760/Lettre_4112"},{auteur:"Audrey Linkenheld",initiales:"AL",oeuvre:"S\xe9nat, 3 avril 2024",epoque:"2024",texte:"[\u2026] le groupe Socialiste, \xc9cologiste et R\xe9publicain reste encore et toujours [circonspect] quant \xe0 l\u2019utilit\xe9 de ce texte.",glose:"La s\xe9natrice parle d'une loi sur les troubles de voisinage.",source:"https://www.senat.fr/seances/s202404/s20240403/s20240403_mono.html"}],prolixe:[{auteur:"Jules Verne",initiales:"JV",oeuvre:"L\u2019Agence Thompson and Co., 1907, premi\xe8re partie, chapitre 9",epoque:"XXe",texte:"Mais, si rapidement qu\u2019il e\xfbt expos\xe9 l\u2019affaire, il avait \xe9t\xe9 trop [prolixe] encore au gr\xe9 de l\u2019impatient corr\xe9gidor [\u2026]",glose:"Un magistrat espagnol press\xe9 trouve le r\xe9cit de Robert encore trop long.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Agence_Thompson_and_Co./I/9"},{auteur:"Jean-Louis H\xe9rin",initiales:"JH",oeuvre:"Colloque \xab L'\xe9criture de la loi \xbb, S\xe9nat, actes du 31 juillet 2014",epoque:"2014",texte:"La plus longue ? La plus [prolixe] est la loi Alur, avec 479 pages, 177 articles [\u2026]",glose:"Un haut responsable du S\xe9nat cite, selon lui, la loi la plus longue de la R\xe9publique.",source:"https://www.senat.fr/rap/ecriture_loi/ecriture_loi_mono.html"}]}},256,[]);
__d(function(e,s,i,r,a,t,n){a.exports={laconique:[{auteur:"Jules Verne",initiales:"JV",oeuvre:"Le Tour du monde en quatre-vingts jours, 1872",epoque:"XIXe",texte:"Le ma\xeetre pr\xe9senta son passe-port, en priant [laconiquement] le consul de vouloir bien y apposer son visa.",glose:"Phileas Fogg fait viser son passeport au consulat de Suez, sans un mot de trop.",source:"https://fr.wikisource.org/wiki/Le_Tour_du_monde_en_quatre-vingts_jours/Texte_entier"},{auteur:"Vincent Thi\xe9baut",initiales:"VT",oeuvre:"Assembl\xe9e nationale, 17 novembre 2026",epoque:"2026",texte:"Apr\xe8s une fuite de donn\xe9es, trop d\u2019int\xe9ress\xe9s en sont avertis par un message [laconique] qui ne pr\xe9cise ni quels risques ils courent ni quoi faire.",glose:"Le d\xe9put\xe9 d\xe9fend une loi sur la cybers\xe9curit\xe9.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2026-2027/premiere-seance-du-mardi-17-novembre-2026"}],dithyrambique:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Madame Bovary, 1857",epoque:"XIXe",texte:"Quand il arrivait \xe0 la distribution des r\xe9compenses, il d\xe9peignait la joie des laur\xe9ats en traits [dithyrambiques].",glose:"Le journaliste du coin raconte la f\xeate agricole du village avec un enthousiasme exag\xe9r\xe9.",source:"https://fr.wikisource.org/wiki/Madame_Bovary/Texte_entier"},{auteur:"Jean-Claude Raux",initiales:"JR",oeuvre:"Assembl\xe9e nationale, 15 d\xe9cembre 2025",epoque:"2025",texte:"Ce n\u2019est pas sur les bosses qu\u2019Edgar Grospiron a rebondi, mais sur des adjectifs [dithyrambiques], pour vanter les m\xe9rites de l\u2019organisation des Jeux olympiques et paralympiques d\u2019hiver de 2030 [\u2026]",glose:"Edgar Grospiron, ancien champion de ski de bosses, pr\xe9side l'organisation des Jeux d'hiver de 2030.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/seance-du-lundi-15-decembre-2025"}],inexorable:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Notre-Dame de Paris, 1831",epoque:"XIXe",texte:"Mais toute mauvaise pens\xe9e est [inexorable] et veut devenir un fait [\u2026]",glose:"Le pr\xeatre Frollo avoue qu'il n'a pas pu arr\xeater le mauvais projet qui avait germ\xe9 en lui.",source:"https://fr.wikisource.org/wiki/Notre-Dame_de_Paris/Texte_entier"},{auteur:"Marie-France Lorho",initiales:"ML",oeuvre:"Assembl\xe9e nationale, questions au gouvernement, 6 mai 2025",epoque:"2025",texte:"Madame la ministre de l\u2019agriculture, la d\xe9croissance [inexorable] du nombre d\u2019agriculteurs est, depuis le lendemain de la seconde guerre mondiale, un sujet d\u2019inqui\xe9tude constant.",glose:null,source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/premiere-seance-du-mardi-06-mai-2025"}],paroxysme:[{auteur:"Marcel Proust",initiales:"MP",oeuvre:"Du c\xf4t\xe9 de chez Swann, 1913",epoque:"XXe",texte:"[\u2026] ces bont\xe9s de la veille avaient excit\xe9 ou sa gratitude, ou le d\xe9sir de les voir se renouveler, ou un [paroxysme] d\u2019amour qui avait besoin de se d\xe9penser.",glose:"Apr\xe8s une soir\xe9e o\xf9 Odette a \xe9t\xe9 tendre, Swann lui envoie les plus beaux bijoux.",source:"https://fr.wikisource.org/wiki/Du_c%C3%B4t%C3%A9_de_chez_Swann/Texte_entier"},{auteur:"Manuel Valls",initiales:"MV",oeuvre:"Assembl\xe9e nationale, questions au gouvernement, 24 juin 2025",epoque:"2025",texte:"En Martinique, la prolif\xe9ration des sargasses est \xe0 son [paroxysme].",glose:"Le ministre des outre-mer parle des algues brunes qui envahissent les plages des Antilles.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/premiere-seance-du-mardi-24-juin-2025"}],quintessence:[{auteur:"Arthur Rimbaud",initiales:"AR",oeuvre:"Lettre \xe0 Paul Demeny, 15 mai 1871",epoque:"XIXe",texte:"[\u2026] il cherche lui-m\xeame, il \xe9puise en lui tous les poisons, pour n\u2019en garder que les [quintessences].",glose:"Rimbaud d\xe9crit le po\xe8te, qui vit toutes les exp\xe9riences pour n'en retenir que l'essentiel.",source:"https://fr.wikisource.org/wiki/Lettre_de_Rimbaud_%C3%A0_Paul_Demeny_-_15_mai_1871"},{auteur:"S\xe9bastien Saint-Pasteur",initiales:"SS",oeuvre:"Assembl\xe9e nationale, d\xe9bat sur le handicap, 12 juin 2025",epoque:"2025",texte:"[\u2026] des remerciements appuy\xe9s au mouvement associatif, dont vous \xeates en quelque sorte, aujourd\u2019hui, la [quintessence].",glose:"Le d\xe9put\xe9 remercie les associations invit\xe9es \xe0 d\xe9battre du handicap.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/premiere-seance-du-jeudi-12-juin-2025"}],"pr\xe9rogative":[{auteur:"Stendhal",initiales:"S",oeuvre:"Le Rouge et le Noir, 1830",epoque:"XIXe",texte:"Toujours il se trouvera un roi qui voudra augmenter sa [pr\xe9rogative] [\u2026]",glose:"Un voyageur d\xe9go\xfbt\xe9 de la politique pr\xe9dit que rien ne changera jamais.",source:"https://fr.wikisource.org/wiki/Le_Rouge_et_le_Noir/Texte_entier"},{auteur:"Philippe Tabarot",initiales:"PT",oeuvre:"Assembl\xe9e nationale, 2 juin 2025",epoque:"2025",texte:"Le Parlement doit pouvoir exercer pleinement les [pr\xe9rogatives] que lui conf\xe8re notre Constitution, dans le respect de l\u2019\xc9tat de droit et au service de l\u2019int\xe9r\xeat g\xe9n\xe9ral.",glose:null,source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2024-2025/premiere-seance-du-lundi-02-juin-2025"}]}},257,[]);
__d(function(e,s,i,r,n,t,o){n.exports={"\xe9piph\xe9nom\xe8ne":[{auteur:"Maurice Hauriou",initiales:"MH",oeuvre:"Les \xc9piph\xe9nom\xe8nes de l'\xe9volution du pouvoir, 1895",epoque:"XIXe",texte:"L\u2019\xe9volution du pouvoir est pour les hommes une continuelle source d\u2019\xe9motions. Il y a l\xe0 un [\xe9piph\xe9nom\xe8ne], c\u2019est-\xe0-dire un ph\xe9nom\xe8ne secondaire [\u2026]",glose:"Le juriste explique que les \xe9motions suscit\xe9es par le pouvoir sont un effet accessoire de son \xe9volution.",source:"https://fr.wikisource.org/wiki/Les_%C3%A9piph%C3%A9nom%C3%A8nes_de_l%27%C3%A9volution_du_pouvoir"},{auteur:"Na\xefma Moutchou",initiales:"NM",oeuvre:"Assembl\xe9e nationale, 20 novembre 2018",epoque:"2018",texte:"C\u2019est pourtant notre devoir que d\u2019agir face \xe0 ce qui, loin d\u2019\xeatre un [\xe9piph\xe9nom\xe8ne], constitue un d\xe9fi majeur pour nos d\xe9mocraties [\u2026]",glose:"La d\xe9put\xe9e parle de la d\xe9sinformation, lors du d\xe9bat sur la loi contre les fausses informations.",source:"https://www.assemblee-nationale.fr/dyn/15/comptes-rendus/seance/session-ordinaire-de-2018-2019/premiere-seance-du-mardi-20-novembre-2018"}],perspicace:[{auteur:"Camille Selden",initiales:"CS",oeuvre:"Les Derniers Jours de Henri Heine, 1884, chapitre VI",epoque:"XIXe",texte:"Il subissait l\u2019empire qu\u2019un esprit [perspicace] exerce sur un esprit perspicace.",glose:"L'autrice, amie du po\xe8te Heine \xe0 la fin de sa vie, explique l'attirance entre deux esprits fins.",source:"https://fr.wikisource.org/wiki/Les_Derniers_Jours_de_Henri_Heine/VI"},{auteur:"Pierre-Yves Collombat",initiales:"PC",oeuvre:"S\xe9nat, 11 juillet 2017",epoque:"2017",texte:"Le juge est assez [perspicace] pour d\xe9terminer o\xf9 se dissimulerait un comportement qui m\xe9riterait d\u2019\xeatre sanctionn\xe9.",glose:"Le s\xe9nateur d\xe9fend un amendement sur les d\xe9lits reproch\xe9s aux \xe9lus locaux.",source:"https://www.senat.fr/seances/s201707/s20170711/s20170711_mono.html"}],tributaire:[{auteur:"Collectif",initiales:"LA",oeuvre:"Lausanne \xe0 travers les \xe2ges, 1906, Commerce",epoque:"XXe",texte:"La boucherie lausannoise est [tributaire] de l\u2019\xe9tranger pour une partie de ses produits.",glose:"Une partie de la viande vendue \xe0 Lausanne vient d'Italie et de France.",source:"https://fr.wikisource.org/wiki/Lausanne_%C3%A0_travers_les_%C3%A2ges/Commerce/04"},{auteur:"Patrice Martin",initiales:"PM",oeuvre:"Assembl\xe9e nationale, 17 novembre 2025",epoque:"2025",texte:"L\u2019installation et l\u2019exploitation des parcs \xe9oliens offshore [\u2026]. Elles sont \xe9galement [tributaires] des conditions m\xe9t\xe9orologiques.",glose:"Le d\xe9put\xe9 d\xe9fend un amendement sur la taxe pay\xe9e par les \xe9oliennes en mer.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/deuxieme-seance-du-lundi-17-novembre-2025"}],atermoyer:[{auteur:"Octave Mirbeau",initiales:"OM",oeuvre:"Le Coup de bistouri, 1898",epoque:"XIXe",texte:"Mais on sent, dans la conduite des ministres, des h\xe9sitations, des [atermoiements], des t\xe2tonnements, rien de net ni de brave [\u2026]",glose:"Le journaliste reproche aux ministres de remettre leur d\xe9cision \xe0 plus tard.",source:"https://fr.wikisource.org/wiki/Le_Coup_de_bistouri"},{auteur:"Jean-Fran\xe7ois Husson",initiales:"JH",oeuvre:"S\xe9nat, 27 novembre 2025",epoque:"2025",texte:"[\u2026] nous ferons preuve, pour notre part, d\u2019une loyaut\xe9 exigeante. Ce ne sera pas de trop, si l\u2019on en croit les [atermoiements] auxquels ont donn\xe9 lieu les cibles de d\xe9ficit public.",glose:"Le rapporteur du budget au S\xe9nat rappelle que la cible de d\xe9ficit a chang\xe9 plusieurs fois en quelques mois.",source:"https://www.senat.fr/seances/s202511/s20251127/s20251127_mono.html"}],"se targuer":[{auteur:"Jacques Bainville",initiales:"JB",oeuvre:"Au seuil du si\xe8cle, 1927, \xab St\xe9phanie (de Paul Adam) \xbb",epoque:"XXe",texte:"[\u2026] il [se targue] de ses connaissances latines, grecques, scientifiques, et prend les mines du penseur [\u2026]",glose:"Bainville d\xe9crit un personnage de roman, un \xe9tudiant qui a rat\xe9 plusieurs fois son baccalaur\xe9at.",source:"https://fr.wikisource.org/wiki/Au_Seuil_du_si%C3%A8cle/7"},{auteur:"Fran\xe7ois Bonhomme",initiales:"FB",oeuvre:"S\xe9nat, 15 mai 2025",epoque:"2025",texte:"[\u2026] pr\xe8s de trois quarts de la population a confiance dans les forces de l\u2019ordre [\u2026] Peu de professions peuvent [se targuer] d\u2019un tel niveau de popularit\xe9\u2026",glose:"Le s\xe9nateur parle de la confiance des Fran\xe7ais envers les policiers et les gendarmes.",source:"https://www.senat.fr/seances/s202505/s20250515/s20250515_mono.html"}],opportun:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Louise Colet, 14-15 juin 1853",epoque:"XIXe",texte:"Oui, il faut se brider le c\u0153ur, le tenir en laisse comme un bouledogue enrag\xe9 et ensuite le l\xe2cher tout d\u2019un bond dans le style, au moment [opportun].",glose:"Flaubert explique comment il retient ses \xe9motions pour les mettre dans son \xe9criture.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_3/0400"},{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"D\xe9claration avec Joseph Aoun, pr\xe9sident libanais, 28 mars 2025",epoque:"2025",texte:"[\u2026] nous pourrons accueillir \xe0 Paris, au moment [opportun], une nouvelle conf\xe9rence internationale sur le redressement du Liban.",glose:null,source:"https://www.elysee.fr/emmanuel-macron/2025/03/28/entretiens-avec-joseph-aoun-president-de-la-republique-libanaise-et-reunion-sur-la-mediterranee-orientale"}]}},258,[]);
__d(function(e,r,i,t,s,u,o){s.exports={pugnace:[{auteur:"Paul-Gabriel d\u2019Haussonville",initiales:"PH",oeuvre:"R\xe9ponse au discours de r\xe9ception de Ferdinand Bruneti\xe8re, Acad\xe9mie fran\xe7aise, 1894",epoque:"XIXe",texte:"Ah ! Monsieur, que vous \xeates [pugnace] ! Vous ne pouvez apercevoir une r\xe9putation dont l\u2019empire vous para\xeet usurp\xe9 sans lui d\xe9clarer la guerre [\u2026]",glose:"Il accueille \xe0 l\u2019Acad\xe9mie le critique Bruneti\xe8re, qui part en guerre contre les r\xe9putations qu\u2019il juge usurp\xe9es.",source:"https://fr.wikisource.org/wiki/R%C3%A9ponse_de_monsieur_le_comte_d%E2%80%99Haussonville_au_discours_de_monsieur_Ferdinand_Bruneti%C3%A8re"},{auteur:"Sainte-Beuve",initiales:"SB",oeuvre:"Port-Royal, livre II, chapitre 17",epoque:"XIXe",texte:"Ainsi la nature prudente de M. de Saci n\u2019\xe9tait pas sans quelque m\xe9fiance de la nature [pugnace] d\u2019Arnauld, et il l\u2019aurait voulu temp\xe9rer.",glose:"Deux figures de Port-Royal : le prudent Saci aurait voulu calmer le combatif Arnauld.",source:"https://fr.wikisource.org/wiki/Port-Royal/Livre_2/17"}],insipide:[{auteur:"Anatole France",initiales:"AF",oeuvre:"La R\xe9volte des anges, titre du chapitre VIII",epoque:"XXe",texte:"O\xf9 il est parl\xe9 d\u2019amour ; ce qui plaira, car un conte sans amour est comme du boudin sans moutarde, c\u2019est chose [insipide].",glose:"Le titre d\u2019un chapitre, qui promet au lecteur une histoire d\u2019amour.",source:"https://fr.wikisource.org/wiki/La_R%C3%A9volte_des_anges"}],foisonner:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Correspondance, lettre \xe0 Louise Colet, 15 janvier 1853",epoque:"XIXe",texte:"Quelle immense ironie que tout cela ! Et comme les honneurs [foisonnent] quand l\u2019honneur manque !",glose:"Flaubert s\u2019agace des d\xe9corations distribu\xe9es aux gens de lettres.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_3/0362"}],"\xe9m\xe9rite":[{auteur:"Gabriel Guillemot",initiales:"GG",oeuvre:"Le Boh\xeame, \xab Le Boh\xeame en habit noir \xbb, 1868",epoque:"XIXe",texte:"Ah ! si vous saviez ! il a toutes les qualit\xe9s solides, toutes les gr\xe2ces du pique-assiette [\xe9m\xe9rite]. Il sait manger, il sait boire.",glose:"Portrait d\u2019un mondain sans ressources connues, qui d\xeene toujours chez les autres.",source:"https://fr.wikisource.org/wiki/Le_Boh%C3%AAme_(Guillemot)/04"}],fastidieux:[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre 1385, 1740",epoque:"XVIIIe",texte:"Dites, pour Dieu, tout le bien de moi que vous ne pensez pas ; [\u2026] et sans entrer dans le d\xe9tail [fastidieux] de cette affaire, gagnez-moi le c\u0153ur de cet homme-l\xe0",glose:"Voltaire demande \xe0 un ami de plaider sa cause aupr\xe8s d\u2019un ambassadeur.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1740/Lettre_1385"}],susciter:[{auteur:"Guillaume Apollinaire",initiales:"GA",oeuvre:"Calligrammes, \xab L\u2019Inscription anglaise \xbb, 1918",epoque:"XXe",texte:"Et le soldat n\u2019ose point achever Le jeu de mots bilingue que ne manque point de [susciter] Cette calligraphie sylvestre et vernale",glose:"Des n\u0153uds de couleuvres dessinent dans la for\xeat un nom aim\xe9, en belle \xe9criture anglaise.",source:"https://fr.wikisource.org/wiki/Calligrammes/L%E2%80%99Inscription_anglaise"}],"rass\xe9r\xe9ner":[{auteur:"Hector Berlioz",initiales:"HB",oeuvre:"Lettre \xe0 Auguste Morel, Londres, 24 avril 1848",epoque:"XIXe",texte:"Paris semble un peu se [rass\xe9r\xe9ner]. Dieu veuille que cela dure et que l\u2019Assembl\xe9e soit une v\xe9ritable repr\xe9sentation de la nation.",glose:"Depuis Londres, 2 mois apr\xe8s la r\xe9volution de f\xe9vrier 1848, le compositeur prend des nouvelles de Paris.",source:"https://fr.wikisource.org/wiki/Correspondance_in%C3%A9dite_de_Hector_Berlioz/043"}],imputer:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 M. Berger, Cirey, avril 1738",epoque:"XVIIIe",texte:"Je ne veux ni usurper la gloire des autres, ni me charger de leurs querelles. Je suis assez f\xe2ch\xe9 qu\u2019on m\u2019ait os\xe9 [imputer] l\u2019ennuyeuse et dix fois trop longue R\xe9ponse [\u2026] aux \xc9p\xeetres de Rousseau.",glose:"Voltaire d\xe9ment \xeatre l\u2019auteur de textes \xe9crits contre le po\xe8te Jean-Baptiste Rousseau.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1738/Lettre_849"}],"z\xe9nith":[{auteur:"William Shakespeare",initiales:"WS",oeuvre:"Sonnets, sonnet 7, traduction de Fran\xe7ois-Victor Hugo",epoque:"XVIIe",texte:"Mais, quand du [z\xe9nith] supr\xeame, sur son char alourdi, il va, comme la vieillesse, chancelant au cr\xe9puscule",glose:"Le soleil, arriv\xe9 au plus haut du ciel, redescend comme un vieillard.",source:"https://fr.wikisource.org/wiki/Sonnets_de_Shakespeare_(trad._Hugo)/007"}],"pis-aller":[{auteur:"Jules Laforgue",initiales:"JL",oeuvre:"Derniers vers, \xab Sur une d\xe9funte \xbb",epoque:"XIXe",texte:"Et je ne serais qu\u2019un [pis-aller], Comme l\u2019est mon jour dans le Temps, Comme l\u2019est ma place dans l\u2019Espace",glose:"Le po\xe8te refuse d\u2019\xeatre aim\xe9 faute de mieux : pour elle, ce sera \xab tout ou rien \xbb.",source:"https://fr.wikisource.org/wiki/Po%C3%A9sies_compl%C3%A8tes_de_Jules_Laforgue/Derniers_vers/Sur_une_d%C3%A9funte"}],"maugr\xe9er":[{auteur:"Jean-Aubert Loranger",initiales:"JL",oeuvre:"Le Village, \xab L\u2019Argument d\xe9cisif \xbb, 1925",epoque:"XXe",texte:"Si M\xe9das Br\xe9b\u0153uf, le jour o\xf9 la chose advint, versa ses cinquante piastres d\u2019amende sans [maugr\xe9er], ce n\u2019est pourtant pas qu\u2019il eut plaid\xe9 coupable ni qu\u2019il se sentit humili\xe9.",glose:"Dans un village du Qu\xe9bec, un homme paie son amende sans protester.",source:"https://fr.wikisource.org/wiki/Le_village/L%E2%80%99ARGUMENT_D%C3%89CISIF"},{auteur:"H. G. Wells",initiales:"HW",oeuvre:"L\u2019Homme invisible, chapitre 8, La Revue de Paris, 1900",epoque:"XIXe",texte:"Elle continua de [maugr\xe9er], avec cette ampleur et cette vari\xe9t\xe9 auxquelles se reconnaissent les jurons d\u2019un homme bien \xe9lev\xe9.",glose:"Sur les dunes, un promeneur entend une voix jurer tout pr\xe8s de lui, sans voir personne.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Homme_invisible/8"}],infaillible:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Les Mis\xe9rables, tome V, livre 1, titre du chapitre 9",epoque:"XIXe",texte:"Emploi de ce vieux talent de braconnier et de ce coup de fusil [infaillible] qui a influ\xe9 sur la condamnation de 1796",glose:"Sur la barricade, Jean Valjean retrouve l\u2019adresse au tir qui l\u2019avait fait condamner.",source:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_5/Livre_1/09"}],travestir:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 M. de La Noue, 1741",epoque:"XVIIIe",texte:"il n\u2019y a pas moyen de [travestir] Mlle Gautier en reine douairi\xe8re ; elle ne doit embellir que les r\xf4les des jeunes princesses.",glose:"Voltaire juge une actrice trop jeune pour jouer la reine de sa trag\xe9die M\xe9rope.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1741/Lettre_1441"}],exigu:[{auteur:"S\xe9n\xe8que",initiales:"S",oeuvre:"Lettres \xe0 Lucilius, lettre 43, traduction de Joseph Baillard",epoque:"Ier",texte:"Tel navire, grand sur un fleuve, est fort petit en mer ; le m\xeame gouvernail, trop fort pour tel navire, est [exigu] pour tel autre.",glose:"La grandeur n\u2019est jamais absolue : tout d\xe9pend de ce \xe0 quoi on se compare.",source:"https://fr.wikisource.org/wiki/Lettres_%C3%A0_Lucilius/Lettre_43"}],propice:[{auteur:"\xc9mile Verhaeren",initiales:"EV",oeuvre:"Les Heures du soir",epoque:"XXe",texte:"Sois-nous [propice] et consolante encor, lumi\xe8re",glose:"Le premier vers d\u2019un po\xe8me adress\xe9 \xe0 la lumi\xe8re.",source:"https://fr.wikisource.org/wiki/Sois-nous_propice_et_consolante_encor,_lumi%C3%A8re"}],"exp\xe9dient":[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre 1276, 1740",epoque:"XVIIIe",texte:"c\u2019est dans cette vue que je vous propose un [exp\xe9dient] qui satisfera en m\xeame temps votre d\xe9licatesse et ma crainte.",glose:"Voltaire veut cacher son nom pour prot\xe9ger sa pi\xe8ce Zulime des cabales.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1740/Lettre_1276"},{auteur:"Montesquieu",initiales:"M",oeuvre:"Lettres persanes, lettre 110, 1721",epoque:"XVIIIe",texte:"la dispute \xe9toit vive, et les \xe9tats se seroient rompus mille fois, si l\u2019on n\u2019avoit imagin\xe9 un [exp\xe9dient], qui \xe9toit que la demande seroit faite en langage catalan, et la r\xe9ponse en aragonais.",glose:"Rica se moque des querelles de forme qui passent avant l\u2019essentiel.",source:"https://fr.wikisource.org/wiki/Lettres_persanes/Lettre_110"}],"inanit\xe9":[{auteur:"\xc9mile Verhaeren",initiales:"EV",oeuvre:"Po\xe8mes, IIe s\xe9rie, \xab Pri\xe8re \xbb, 1896",epoque:"XIXe",texte:"Il ne restera rien de ce qui fut ma plainte Et tout homme travaille \xe0 son [inanit\xe9]",glose:"Seul face \xe0 une nuit d\u2019hiver, le po\xe8te m\xe9dite sur le vide de toute chose.",source:"https://fr.wikisource.org/wiki/Pri%C3%A8re_(Verhaeren_-_Les_D%C3%A9bacles)"}],gloser:[{auteur:"Jean de La Fontaine",initiales:"LF",oeuvre:"\xab Contre la m\xeame \xbb, \u0152uvres compl\xe8tes, tome 5",epoque:"XVIIe",texte:"Sans [gloser] sur le mystere Des Madrigaux qu\u2019elle a faits, Ne luy parlons d\xe9sormais Qu\u2019en la langue de sa mere.",glose:"La Fontaine se moque de la veuve du po\xe8te Colletet, qui n\u2019\xe9crit plus de vers depuis la mort de son mari.",source:"https://fr.wikisource.org/wiki/%C5%92uvres_compl%C3%A8tes_de_La_Fontaine_(Marty-Laveaux)/Tome_5/Contre_la_mesme"}],conjecturer:[{auteur:"Diderot",initiales:"D",oeuvre:"L\u2019Encyclop\xe9die, article \xab Babia \xbb, 1751",epoque:"XVIIIe",texte:"On y donnoit le nom de babia aux enfans ; ce qui a fait [conjecturer] que la babia \xe9toit d\xe9esse de l\u2019enfance.",glose:"\xc0 propos d\u2019une d\xe9esse v\xe9n\xe9r\xe9e en Syrie, surtout \xe0 Damas.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/BABIA"}],fervent:[{auteur:"Charles Gu\xe9rin",initiales:"CG",oeuvre:"Le Semeur de cendres, 1901",epoque:"XXe",texte:"\xd4 jeunesse, [fervent] et clair foyer d\u2019amour, Tu fais au ciel l\u2019aveu sonore de ta joie",glose:"Le po\xe8te s\u2019adresse \xe0 la jeunesse comme \xe0 un feu.",source:"https://fr.wikisource.org/wiki/Le_Semeur_de_cendres/%C2%AB_%C3%94_jeunesse,_fervent_et_clair_foyer_d%E2%80%99amour_%C2%BB"}],"m\xe9sestimer":[{auteur:"Pierre Corneille",initiales:"PC",oeuvre:"Imitation de J\xe9sus-Christ, livre I, chapitre 2 (traduction)",epoque:"XVIIe",texte:"Est la plus digne \xe9tude o\xf9 s\u2019occupe le sage Pour estimer tout autre, et se [m\xe9sestimer].",glose:"La le\xe7on du chapitre \xab Du peu d\u2019estime de soi-m\xeame \xbb : juger les autres avec estime, et soi-m\xeame avec humilit\xe9.",source:"https://fr.wikisource.org/wiki/Imitation_de_J%C3%A9sus-Christ/Livre_1/Chapitre_2"}],discernement:[{auteur:"Saint-\xc9vremond",initiales:"SE",oeuvre:"Observations sur le go\xfbt et le discernement des Fran\xe7ois",epoque:"XVIIe",texte:"Je ne m\u2019\xe9tonne point que le bon go\xfbt ne se trouve pas, en des lieux o\xf9 r\xe8gne la barbarie ; et qu\u2019il n\u2019y ait point de [discernement], o\xf9 les lettres, les arts et les disciplines sont perdus.",glose:"Ce qui l\u2019\xe9tonne, c\u2019est de voir le bon et le mauvais go\xfbt tour \xe0 tour \xe0 la mode \xe0 la cour.",source:"https://fr.wikisource.org/wiki/%C5%92uvres_m%C3%AAl%C3%A9es_de_Saint-%C3%89vremond/Litt%C3%A9rature/Observations_sur_le_go%C3%BBt_et_le_discernement_des_Fran%C3%A7ois"}]}},259,[]);
__d(function(e,r,i,t,a,s,n){a.exports={partial:[{auteur:"Denis Diderot",initiales:"DD",oeuvre:"L'Encyclop\xe9die, article \xab Impartial \xbb, 1766",epoque:"XVIIIe",texte:"Il ne faut pas confondre un juge ignorant avec un juge [partial]. L\u2019ignorant n\u2019a pas les connoissances n\xe9cessaires pour bien juger ; le partial s\u2019y refuse.",glose:"Diderot distingue celui qui ne sait pas juger de celui qui ne veut pas juger honn\xeatement.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/IMPARTIAL"}],cautionner:[{auteur:"Fran\xe7ois Mitterrand",initiales:"FM",oeuvre:"Conf\xe9rence de presse \xe0 La R\xe9union, 9 f\xe9vrier 1988",epoque:"1988",texte:"Je consid\xe8re que le comportement de RFO n\u2019est pas digne de la mission qui lui a \xe9t\xe9 d\xe9volue et je n\u2019ai aucune raison de le [cautionner].",glose:"Le pr\xe9sident reproche \xe0 la cha\xeene publique d'outre-mer de manquer de pluralisme.",source:"https://www.elysee.fr/francois-mitterrand/1988/02/09/conference-de-presse-de-m-francois-mitterrand-president-de-la-republique-sur-le-bilan-de-son-voyage-a-la-reunion-a-laeroport-de-gillot-mardi-9-fevrier-1988"}],"pr\xe9dilection":[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 24 avril 1854",epoque:"XIXe",texte:"Je professe avant tout ma [pr\xe9dilection] pour les ouvrages de courte haleine qui ne fatiguent pas plus le lecteur qu\u2019ils n\u2019ont fatigu\xe9 l\u2019auteur [\u2026]",glose:"Le peintre note dans son journal qu'il pr\xe9f\xe8re les \u0153uvres courtes.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/24_avril_1854"}],"r\xe9fractaire":[{auteur:"Louis-S\xe9bastien Mercier",initiales:"LM",oeuvre:"Le Nouveau Paris, 1798, \xab Pr\xeatres r\xe9fractaires \xbb",epoque:"XVIIIe",texte:"On nomme [r\xe9fractaire], le sable, ou l\u2019argile, ou le minerai, qui, non seulement ne se lie pas avec les autres mat\xe9riaux, mais qui les emp\xeache de se lier entr\u2019eux [\u2026]",glose:"Mercier explique que le mot vient des m\xe9tiers, avant de d\xe9signer les pr\xeatres qui refusaient de pr\xeater serment \xe0 la R\xe9volution.",source:"https://fr.wikisource.org/wiki/Le_nouveau_Paris/60"}],sibyllin:[{auteur:"\xc9loi Cl\xe9ri",initiales:"\xc9C",oeuvre:"Le Secret de la malle rouge, 1915",epoque:"XXe",texte:"Quel langage [sibyllin] vous employez, mon ami.",glose:"Dans ce roman policier, le narrateur ne comprend rien aux allusions de son ami d\xe9tective.",source:"https://fr.wikisource.org/wiki/Le_Secret_de_la_malle_rouge/2"}],"imp\xe9tueux":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Ernest Feydeau, novembre 1857",epoque:"XIXe",texte:"Patience, [imp\xe9tueux] jeune homme !",glose:"Flaubert annonce \xe0 son ami \xe9crivain qu'il viendra bient\xf4t \xe0 Paris.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0564"}],"d\xe9celer":[{auteur:"L\xe9on Boutroux",initiales:"LB",oeuvre:"Le Pain et la Panification, 1897, pr\xe9face",epoque:"XIXe",texte:"Puis nous indiquons la composition chimique du pain et les op\xe9rations par lesquelles le chimiste peut en appr\xe9cier la qualit\xe9 ou y [d\xe9celer] les fraudes.",glose:"L'auteur pr\xe9sente le plan de son livre sur la fabrication du pain.",source:"https://fr.wikisource.org/wiki/Le_pain_et_la_panification/Pr%C3%A9face"}],"inimiti\xe9":[{auteur:"Collectif",initiales:"EN",oeuvre:"L'Encyclop\xe9die de Diderot et d'Alembert, article \xab Inimiti\xe9 \xbb, 1766",epoque:"XVIIIe",texte:"[INIMITI\xc9], s. f. (Gramm.) c\u2019est la haine entre des personnes faites pour s\u2019aimer.",glose:"La d\xe9finition enti\xe8re de l'article tient en une phrase.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/INIMITI%C3%89"}],virulent:[{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"D\xe9placement en Gironde, 27 juillet 2026",epoque:"2026",texte:"Il a \xe9t\xe9 stabilis\xe9, comme on dit, mais il continue d\u2019\xeatre [virulent].",glose:"Le pr\xe9sident parle d'un incendie de for\xeat en Gironde, pendant une saison des feux record.",source:"https://www.elysee.fr/emmanuel-macron/2026/07/27/deplacement-en-gironde"}],subversif:[{auteur:"Boutros Boutros-Ghali",initiales:"BG",oeuvre:"Entretien sur TV5, 3 d\xe9cembre 1995",epoque:"1995",texte:"Je pense qu\u2019il faut \xeatre [subversif] pour trouver des solutions aux probl\xe8mes globaux de demain. Il faut des id\xe9es nouvelles.",glose:"Le secr\xe9taire g\xe9n\xe9ral de l'ONU r\xe9pond \xe0 une question sur le fran\xe7ais, \xab langue subversive \xbb.",source:"https://www.elysee.fr/jacques-chirac/1995/12/03/interview-de-mm-jacques-chirac-president-de-la-republique-boutros-boutros-ghali-secretaire-general-de-lonu-nicephore-soglo-president-du-benin-a-tv5-le-3-decembre-1995-sur-la-place-du-francais-dans-le-monde-et-en-europe-le-developpement-de-lafri"}],intransigeant:[{auteur:"Jacques Chirac",initiales:"JC",oeuvre:"Discours sur la la\xefcit\xe9, 17 d\xe9cembre 2003",epoque:"2003",texte:"Il faut \xeatre vigilant et [intransigeant] face aux menaces d\u2019un retour en arri\xe8re et elles existent.",glose:"Le pr\xe9sident parle de l'\xe9galit\xe9 entre les femmes et les hommes.",source:"https://www.elysee.fr/jacques-chirac/2003/12/17/discours-de-m-jacques-chirac-president-de-la-republique-sur-le-respect-du-principe-de-laicite-dans-la-republique-paris-le-17-decembre-2003"}],"p\xe9dant":[{auteur:"Alain",initiales:"A",oeuvre:"Les Propos d'Alain, 1920",epoque:"XXe",texte:"Le [p\xe9dant] apprend vite et par r\xe9sum\xe9s ; une fois qu\u2019il a appris, il sait. Vingt ans apr\xe8s, il retrouvera les m\xeames formules, et les m\xeames arguments.",glose:"Le philosophe oppose le p\xe9dant \xe0 l'homme cultiv\xe9, dont les id\xe9es restent vivantes.",source:"https://fr.wikisource.org/wiki/Les_Propos_d%E2%80%99Alain_(1920)/Tome_1/040"},{auteur:"Louis de Jaucourt",initiales:"LJ",oeuvre:"L'Encyclop\xe9die, article \xab P\xe9dant \xbb",epoque:"XVIIIe",texte:"Un [p\xe9dant] est un homme d\u2019une pr\xe9somption babillarde, qui fatigue les autres par la parade qu\u2019il fait de son savoir [\u2026]",glose:"Babillarde : bavarde. La pr\xe9somption, c'est l'exc\xe8s de confiance en soi.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/P%C3%89DANT"}],notoire:[{auteur:"Val\xe9ry Giscard d'Estaing",initiales:"VG",oeuvre:"Discours d'Ajaccio, 16 avril 1981",epoque:"1981",texte:"[\u2026] il est [notoire] que la Corse, par sa position strat\xe9gique, peut attirer sur elle les vis\xe9es, ou un jour les menaces des puissances \xe9trang\xe8res.",glose:"En campagne, le pr\xe9sident parle de la place de la Corse en M\xe9diterran\xe9e.",source:"https://www.elysee.fr/valery-giscard-d-estaing/1981/04/16/discours-de-m-valery-giscard-destaing-a-ajaccio-lors-de-la-campagne-electorale-pour-lelection-presidentielle-jeudi-16-avril-1981"}],palinodie:[{auteur:"Collectif",initiales:"EN",oeuvre:"L'Encyclop\xe9die de Diderot et d'Alembert, article \xab Palinodie \xbb, 1765",epoque:"XVIIIe",texte:"De-l\xe0 vient cette phrase, palinodiam canere, chanter la [palinodie], c\u2019est-\xe0-dire faire une r\xe9tractation.",glose:"L'article explique d'o\xf9 vient l'expression \xab chanter la palinodie \xbb.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/PALINODIE"}],annihiler:[{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"Visite d'\xc9tat en Suisse, Lausanne, 16 novembre 2023",epoque:"2023",texte:"[\u2026] s\u2019ils prennent la route de la croissance avec le charbon, c\u2019est \xe9norme parce que \xe7a vient quasiment [annihiler], en tout cas sur le court terme, les efforts que, nous, on est en train de faire.",glose:"Le pr\xe9sident parle des grands pays \xe9mergents et du climat.",source:"https://www.elysee.fr/emmanuel-macron/2023/11/16/visite-detat-en-suisse-deplacement-a-lausanne"}],"se pr\xe9munir":[{auteur:"Fran\xe7ois Mitterrand",initiales:"FM",oeuvre:"Allocution aux autorit\xe9s andorranes, 5 octobre 1981",epoque:"1981",texte:"Rester soi-m\xeame, \xe0 l\u2019heure o\xf9 les convoitises s\u2019exercent tant\xf4t brutalement et tant\xf4t insidieusement, c\u2019est aussi [se pr\xe9munir] contre les risques d\u2019assujetissement ext\xe9rieur.",glose:"Le pr\xe9sident, coprince d'Andorre, parle de l'identit\xe9 de la principaut\xe9.",source:"https://www.elysee.fr/francois-mitterrand/1981/10/05/allocution-de-m-francois-mitterrand-president-de-la-republique-a-loccasion-de-la-prestation-de-serment-et-de-la-remise-de-la-questia-par-les-autorites-andorranes-paris-palais-de-lelysee-lundi-5-octobre-1981"}],concis:[{auteur:"Sophie Adenot",initiales:"SA",oeuvre:"R\xe9ception \xe0 l'\xc9lys\xe9e avant son d\xe9part vers la Station spatiale internationale, 5 f\xe9vrier 2026",epoque:"2026",texte:"C\u2019est assez difficile d\u2019\xeatre [concis] l\xe0-dessus.",glose:"L'astronaute r\xe9pond \xe0 une question sur toutes les comp\xe9tences qu'une mission demande.",source:"https://www.elysee.fr/emmanuel-macron/2026/02/05/reception-en-amont-du-depart-de-lastronaute-francaise-sophie-adenot-vers-la-station-spatiale-internationale"}],fallacieux:[{auteur:"Fran\xe7ois Mitterrand",initiales:"FM",oeuvre:"Allocution \xe0 Luxembourg, 14 mars 1995",epoque:"1995",texte:"Mais ce peut \xeatre aussi un raisonnement [fallacieux], car il pourrait impliquer un affadissement de l\u2019Union.",glose:"Le pr\xe9sident met en garde contre un \xe9largissement trop rapide de l'Union europ\xe9enne.",source:"https://www.elysee.fr/francois-mitterrand/1995/03/14/allocution-de-m-francois-mitterrand-president-de-la-republique-sur-le-role-du-luxembourg-dans-la-construction-europeenne-sur-la-realisation-du-traite-de-maastricht-et-sur-lelargissement-et-lapprofondissement-de-lunion-europeenne-luxembourg-le-14"}],"archa\xefque":[{auteur:"Fran\xe7ois Mitterrand",initiales:"FM",oeuvre:"Discours devant l'Association des journalistes de l'information sociale, 23 novembre 1987",epoque:"1987",texte:"Car il faut sortir des anciennes divisions, notamment de la division taylorienne du travail, [archa\xefque] socialement et, finalement, par rapport aux moyens d\u2019aujourd\u2019hui, inefficace \xe9conomiquement.",glose:"Le pr\xe9sident parle de l'organisation du travail \xe0 la cha\xeene.",source:"https://www.elysee.fr/francois-mitterrand/1987/11/23/discours-de-m-francois-mitterrand-president-de-la-republique-devant-lassociation-des-journalistes-de-linformation-sociale-sur-la-justice-sociale-concernant-notamment-le-droit-du-travail-et-la-solidarite-nationale-paris-lundi-23-novembre-1987"}],"chim\xe9rique":[{auteur:"Emmanuel Macron",initiales:"EM",oeuvre:"V\u0153ux aux arm\xe9es, 19 janvier 2018",epoque:"2018",texte:"Je ne fais pas de promesses intenables. Il n\u2019est pas question d\u2019un mod\xe8le d\u2019arm\xe9e [chim\xe9rique] et insoutenable [\u2026]",glose:"Le pr\xe9sident pr\xe9sente le budget des arm\xe9es pour les 7 ann\xe9es suivantes.",source:"https://www.elysee.fr/emmanuel-macron/2018/01/19/voeux-du-president-emmanuel-macron-aux-armees"}],"animosit\xe9":[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 M. Tronchin, de Lyon, 2 mai 1759",epoque:"XVIIIe",texte:"Je vous r\xe9ponds de la plus implacable [animosit\xe9] entre le roi de France et le roi de Prusse.",glose:"Pendant la guerre de Sept Ans, Voltaire confie \xe0 un ami que la paix entre les 2 rois est impossible.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1759/Lettre_3837"}],diatribe:[{auteur:"Jean le Rond d'Alembert",initiales:"JA",oeuvre:"Lettre \xe0 Voltaire, 1776",epoque:"XVIIIe",texte:"Vous pourriez m\xeame ajouter \xe0 votre [diatribe] tout ce qui peut contribuer \xe0 la rendre piquante, quoiqu\u2019elle le soit d\xe9j\xe0 beaucoup.",glose:"D'Alembert doit lire \xe0 l'Acad\xe9mie fran\xe7aise un texte de Voltaire qui s'en prend \xe0 Shakespeare.",source:"https://fr.wikisource.org/wiki/Correspondance_(d%E2%80%99Alembert)/Correspondance_avec_Voltaire/144"}],abscons:[{auteur:"Paul Verlaine",initiales:"PV",oeuvre:"Entretien avec Jules Huret, Enqu\xeate sur l'\xe9volution litt\xe9raire, 1891",epoque:"XIXe",texte:"D\u2019ailleurs, ils le disent eux-m\xeames : \xab Nous sommes des po\xe8tes [abscons]. Mais pourquoi \xab abscons \xbb tout court ? Si, encore, ils ajoutaient : \xab comme la lune ! \xbb, en outre !",glose:"Verlaine se moque, en riant, des jeunes po\xe8tes symbolistes \xe0 qui l'on reproche d'\xeatre obscurs.",source:"https://fr.wikisource.org/wiki/Enqu%C3%AAte_sur_l%E2%80%99%C3%A9volution_litt%C3%A9raire/Symbolistes_et_D%C3%A9cadents/M._Paul_Verlaine"}],munificence:[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"L'Art moderne, cit\xe9 en note du Journal d'Eug\xe8ne Delacroix",epoque:"XIXe",texte:"Pierre de Corn\xe9lius peut \xeatre consid\xe9r\xe9 comme le chef de l\u2019\xe9cole allemande, ou, pour parler d\u2019une mani\xe8re plus exacte, du cycle des peintres attir\xe9s et fix\xe9s \xe0 Munich par la [munificence] \xe9clair\xe9e du roi Louis.",glose:"Gautier parle des peintres que les largesses du roi Louis ont fait venir \xe0 Munich.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/12_ao%C3%BBt_1854_2"}],obnubiler:[{auteur:"\xc9mile Lavoie",initiales:"\xc9L",oeuvre:"Le Grand S\xe9pulcre blanc, 1925, \xab Voyage de noce \xbb",epoque:"XXe",texte:"[Obnubil\xe9] par la marche forc\xe9e de ce jour, le corps bris\xe9 par la fatigue, les sens endoloris, courbatur\xe9s par le froid, il ne songeait qu\u2019\xe0 dormir [\u2026]",glose:"Le h\xe9ros de ce roman d'aventures avance dans le froid avec ses compagnons.",source:"https://fr.wikisource.org/wiki/Le_grand_s%C3%A9pulcre_blanc/Voyage_de_Noce"}],verbeux:[{auteur:"Marie Len\xe9ru",initiales:"ML",oeuvre:"Journal, 1913",epoque:"XXe",texte:"Il n\u2019existe d\u2019ailleurs que par \xe0-coups, l\u2019ensemble de la pi\xe8ce est toujours tra\xeenant, diffus, [verbeux], tout en conversations \xe9thiques, et \xe9thiques tr\xe8s banales.",glose:"L'autrice de th\xe9\xe2tre donne son avis, tr\xe8s s\xe9v\xe8re, sur une pi\xe8ce d'Ibsen.",source:"https://fr.wikisource.org/wiki/Journal_de_Marie_Len%C3%A9ru/Ann%C3%A9e_1913"}],"t\xe9m\xe9raire":[{auteur:"Fran\xe7ois Mitterrand",initiales:"FM",oeuvre:"V\u0153ux des corps constitu\xe9s, 4 janvier 1994",epoque:"1994",texte:"C\u2019est une question ancienne, qu\u2019il serait [t\xe9m\xe9raire] de pr\xe9tendre renouveler.",glose:"Le pr\xe9sident r\xe9pond \xe0 une question sur \xab l'esprit d\xe9mocratique \xbb et \xab l'esprit r\xe9publicain \xbb.",source:"https://www.elysee.fr/francois-mitterrand/1994/01/04/allocution-de-m-francois-mitterrand-president-de-la-republique-lors-de-la-presentation-des-voeux-des-corps-constitues-sur-la-responsabilite-de-l-etat-republicain-en-matiere-de-cohesion-sociale-de-laicite-et-de-lutte-contre-le-chomage-paris-le-4-j"}]}},260,[]);
__d(function(e,i,t,r,s,u,o){s.exports={parangon:[{auteur:"\xc9rasme",initiales:"E",oeuvre:"\xc9loge de la folie, traduction Pierre de Nolhac, chapitre XXXVII",epoque:"XVIe",texte:"Prenez un [parangon] de sagesse, celui qui a consum\xe9 dans l\u2019\xe9tude des sciences son enfance et sa jeunesse [\u2026]",glose:"La Folie, qui parle dans ce livre, invite \xe0 comparer la vie du fou \xe0 celle du sage.",source:"https://fr.wikisource.org/wiki/%C3%89loge_de_la_folie_(Nolhac)/XXXVII"}],sagace:[{auteur:"Pierre Larousse",initiales:"PL",oeuvre:"Grand dictionnaire universel du XIXe si\xe8cle, article Restaut",epoque:"XIXe",texte:"C\u2019\xe9tait un esprit [sagace], studieux, logique, un homme d\u2019un caract\xe8re honorable et qui sut se concilier l\u2019estime g\xe9n\xe9rale.",glose:"Le portrait du grammairien Pierre Restaut, n\xe9 \xe0 Beauvais en 1696.",source:"https://fr.wikisource.org/wiki/Grand_dictionnaire_universel_du_XIXe_si%C3%A8cle/Restaut_(Pierre)"}],hantise:[{auteur:"Albert Lozeau",initiales:"AL",oeuvre:"Le Miroir des jours, \xab\xa0D\xe9fiance\xa0\xbb, 1912",epoque:"XXe",texte:"Le regard du vulgaire est plein de convoitise. De cet or soup\xe7onn\xe9 l\u2019homme aura la [hantise], Et, si tu n\u2019y prends garde, il te d\xe9pouillera.",glose:"Le po\xe8te qu\xe9b\xe9cois conseille de garder ses tr\xe9sors int\xe9rieurs \xe0 l'abri des regards envieux.",source:"https://fr.wikisource.org/wiki/Le_Miroir_des_jours/D%C3%A9fiance"}],acquiescer:[{auteur:"Montesquieu",initiales:"M",oeuvre:"De l'esprit des lois, livre XI, chapitre 15",epoque:"XVIIIe",texte:"Apr\xe8s bien des r\xe9sistances, le s\xe9nat y [acquies\xe7a].",glose:"\xc0 Rome, les pl\xe9b\xe9iens r\xe9clamaient des lois fixes pour que la justice ne d\xe9pende plus du caprice des puissants.",source:"https://fr.wikisource.org/wiki/Esprit_des_lois_(1777)/L11/C15"}],encenser:[{auteur:"Louis de Wurtemberg",initiales:"LW",oeuvre:"Lettre \xe0 Voltaire, 1750",epoque:"XVIIIe",texte:"Quoi de plus cruel et de plus insultant pour la France que de voir son plus beau g\xe9nie s\u2019\xe9loigner d\u2019elle, lui \xe0 qui on devrait \xe9lever des autels, et qu\u2019on devrait [encenser] comme un dieu ?",glose:"Le prince \xe9crit \xe0 Voltaire, qui s'appr\xeate \xe0 quitter la France.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1750/Lettre_2096"}],candeur:[{auteur:"Montesquieu",initiales:"M",oeuvre:"De l'esprit des lois, livre XII, chapitre 23",epoque:"XVIIIe",texte:"Un prince doit agir avec ses sujets avec [candeur], avec franchise, avec confiance.",glose:"Montesquieu explique qu'un bon souverain n'a pas besoin d'espions.",source:"https://fr.wikisource.org/wiki/Esprit_des_lois_(1777)/L12/C23"}],fatras:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 d'Alembert, 15 janvier 1765",epoque:"XVIIIe",texte:"Gabriel et Philibert peuvent mettre au rang de leurs n\xe9gligences de n\u2019avoir pas fait pr\xe9senter \xe0 l\u2019Acad\xe9mie un exemplaire de mes [fatras] sur les fatras de Pierre Corneille.",glose:"Voltaire se moque de son propre commentaire sur Corneille, que ses imprimeurs ont oubli\xe9 d'offrir \xe0 l'Acad\xe9mie.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1765/Lettre_5882"}],engouement:[{auteur:"L\xe9on Tolsto\xef",initiales:"LT",oeuvre:"Anna Kar\xe9nine, traduction Faguet, partie VII, chapitre 23",epoque:"XIXe",texte:"J\u2019avoue que je ne comprends rien \xe0 votre [engouement] pour cette petite fille ; il me d\xe9pla\xeet, je n\u2019y vois qu\u2019une affectation.",glose:"Le comte reproche \xe0 Anna le temps qu'elle consacre \xe0 une petite fille dont elle s'occupe.",source:"https://fr.wikisource.org/wiki/Anna_Kar%C3%A9nine_(trad._Faguet)/Partie_VII/Chapitre_23"}],"mall\xe9able":[{auteur:"Cennino Cennini",initiales:"CC",oeuvre:"Trait\xe9 de la peinture, chapitre CLXVIII",epoque:"XVe",texte:"Pr\xe9pare une quantit\xe9 de p\xe2te ou de cire bien remu\xe9e et propre, p\xe9trie comme serait un onguent bien [mall\xe9able] [\u2026]",glose:"Le peintre florentin explique comment pr\xe9parer la cire pour prendre l'empreinte d'un corps.",source:"https://fr.wikisource.org/wiki/Trait%C3%A9_de_la_peinture_(Cennini)/CLXVIII"}],quidam:[{auteur:"\xc9sope",initiales:"\xc9",oeuvre:"Fables, \xab\xa0Le Devin\xa0\xbb, traduction \xc9mile Chambry",epoque:"Antiquit\xe9",texte:"Un devin, install\xe9 sur la place publique, y faisait recette. Soudain un [quidam] vint \xe0 lui et lui annon\xe7a que les portes de sa maison \xe9taient ouvertes [\u2026]",glose:"Le devin qui pr\xe9tend lire l'avenir des autres n'a rien vu venir pour sa propre maison.",source:"https://fr.wikisource.org/wiki/Fables_d%E2%80%99%C3%89sope_(trad._Chambry%2C_1927)/Le_Devin"}],"\xe9quivoque":[{auteur:"Platon",initiales:"P",oeuvre:"Gorgias, traduction Alfred Croiset",epoque:"Antiquit\xe9",texte:"mon insistance \xe0 t\u2019interroger venait de mon vif d\xe9sir de savoir sans [\xe9quivoque] ce que tu pensais.",glose:"Socrate explique \xe0 son interlocuteur pourquoi il l'a press\xe9 de questions.",source:"https://fr.wikisource.org/wiki/Gorgias_(trad._Croiset)"}],latent:[{auteur:"Th\xe9odule Ribot",initiales:"TR",oeuvre:"La Vie inconsciente et les mouvements, pr\xe9face, 1914",epoque:"XXe",texte:"[\u2026] qu\u2019ils doivent \xeatre cherch\xe9s dans l\u2019activit\xe9 motrice, actuelle ou conserv\xe9e \xe0 l\u2019\xe9tat [latent].",glose:"Le psychologue r\xe9sume son hypoth\xe8se : l'inconscient se cache dans nos mouvements.",source:"https://fr.wikisource.org/wiki/La_vie_inconsciente_et_les_mouvements/PR%C3%89FACE"}],"c\xe9nacle":[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"Histoire du romantisme, \xab\xa0Suite du petit c\xe9nacle\xa0\xbb, 1874",epoque:"XIXe",texte:"Comme les camarades du petit [c\xe9nacle], Bouchardy savait tous les vers d\u2019Hugo, et e\xfbt r\xe9cit\xe9 Hernani par c\u0153ur d\u2019un bout \xe0 l\u2019autre [\u2026]",glose:"Gautier se souvient du groupe de jeunes romantiques dont il faisait partie.",source:"https://fr.wikisource.org/wiki/Histoire_du_Romantisme/III_-_Suite_du_petit_c%C3%A9nacle"}],"n\xe9faste":[{auteur:"Henriette Dessaulles",initiales:"HD",oeuvre:"Lettres de Fadette, premi\xe8re s\xe9rie, \xab\xa0Notre influence\xa0\xbb, 1914",epoque:"XXe",texte:"Celles qui exercent une influence [n\xe9faste] ne le savent pas toujours.",glose:"La chroniqueuse qu\xe9b\xe9coise, qui signe Fadette, parle de l'influence des femmes sur la soci\xe9t\xe9.",source:"https://fr.wikisource.org/wiki/Lettres_de_Fadette/Premi%C3%A8re_s%C3%A9rie/16"}],opulence:[{auteur:"Montesquieu",initiales:"M",oeuvre:"Lettres persanes, lettre 123, 1721",epoque:"XVIIIe",texte:"Rien n\u2019attire plus les \xe9trangers que la libert\xe9, et l\u2019[opulence] qui la suit toujours [\u2026]",glose:"Le voyageur persan observe que les pays libres et prosp\xe8res attirent les \xe9trangers.",source:"https://fr.wikisource.org/wiki/Lettres_persanes/Lettre_123"}],"dol\xe9ance":[{auteur:"Hubertine Auclert",initiales:"HA",oeuvre:"\xc9galit\xe9 sociale et politique de la femme et de l'homme, 1879",epoque:"XIXe",texte:"Quand en 1789 Olympe de Gouges pr\xe9senta aux \xc9tats-g\xe9n\xe9raux au nom des femmes, son cahier de [dol\xe9ances] et de r\xe9clamations, il lui fut r\xe9pondu qu\u2019il \xe9tait inutile d\u2019examiner la condition de la femme [\u2026]",glose:"La militante rappelle comment les demandes des femmes ont \xe9t\xe9 \xe9cart\xe9es en 1789.",source:"https://fr.wikisource.org/wiki/%C3%89galit%C3%A9_sociale_et_politique_de_la_femme_et_de_l%E2%80%99homme"}],superflu:[{auteur:"Voltaire",initiales:"V",oeuvre:"Le Mondain, 1736",epoque:"XVIIIe",texte:"Le [superflu], chose tr\xe8s n\xe9cessaire [\u2026]",glose:"Voltaire fait l'\xe9loge du luxe et du commerce, qui relient les continents.",source:"https://fr.wikisource.org/wiki/Le_Mondain"}],"toll\xe9":[{auteur:"Albert Thibaudet",initiales:"AT",oeuvre:"Gustave Flaubert, chapitre sur L'\xc9ducation sentimentale",epoque:"XXe",texte:"[\u2026] si le dernier mot du livre \xe9tait fait pour soulever un [toll\xe9] g\xe9n\xe9ral, il n\u2019en demeure pas moins que le roman a \xe9t\xe9 \xe9crit pour plaire au public [\u2026]",glose:"Le critique parle de la fin de L'\xc9ducation sentimentale, le roman de Flaubert.",source:"https://fr.wikisource.org/wiki/Gustave_Flaubert_(Thibaudet)/L%E2%80%99%C3%89ducation_sentimentale"}],arbitraire:[{auteur:"Montesquieu",initiales:"M",oeuvre:"De l'esprit des lois, livre XI, chapitre 15",epoque:"XVIIIe",texte:"[\u2026] afin que les jugemens ne fussent plus l\u2019effet d\u2019une volont\xe9 capricieuse, ou d\u2019un pouvoir [arbitraire].",glose:"Les pl\xe9b\xe9iens de Rome r\xe9clament des lois \xe9crites pour \xeatre jug\xe9s selon des r\xe8gles connues.",source:"https://fr.wikisource.org/wiki/Esprit_des_lois_(1777)/L11/C15"}]}},261,[]);
__d(function(e,i,r,t,s,o,a){s.exports={immuable:[{auteur:"William Shakespeare",initiales:"WS",oeuvre:"Sonnets, 116, traduction de Fran\xe7ois-Victor Hugo",epoque:"XVIIe",texte:"[\u2026] l\u2019amour ne change pas avec les heures et les semaines \xe9ph\xe9m\xe8res, mais il reste [immuable] jusqu\u2019au jour du jugement.",glose:"Le po\xe8te d\xe9crit le v\xe9ritable amour, que le temps ne fait pas bouger.",source:"https://fr.wikisource.org/wiki/Sonnets_de_Shakespeare_(trad._Hugo)/116"}],"\xe9conduire":[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre de 1765",epoque:"XVIIIe",texte:"Je ne crois pas que vous soyez [\xe9conduit]. Les hommes ont encore un petit reste de pudeur.",glose:"Voltaire rassure un ami \xe0 qui l'on fait attendre une pension.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1765/Lettre_6048"}],"t\xe9nu":[{auteur:"Guillaume Apollinaire",initiales:"GA",oeuvre:"Calligrammes, \xab L\u2019Inscription anglaise \xbb, 1918",epoque:"XXe",texte:"C\u2019est quelque chose de si [t\xe9nu] de si lointain / Que d\u2019y penser on arrive \xe0 le trop mat\xe9rialiser",glose:"Le po\xe8te \xe9voque un souvenir si l\xe9ger qu'on l'ab\xeeme rien qu'en y pensant.",source:"https://fr.wikisource.org/wiki/Calligrammes/L%E2%80%99Inscription_anglaise"}],"d\xe9f\xe9rence":[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Les Mis\xe9rables, tome 4",epoque:"XIXe",texte:"Ah, \xe7a c\u2019est vrai, r\xe9pondit la chiffonni\xe8re avec [d\xe9f\xe9rence], moi j\u2019ai un \xe9tat.",glose:"Une chiffonni\xe8re r\xe9pond poliment \xe0 une voisine, fi\xe8re d'avoir au moins un m\xe9tier.",source:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_4/Livre_11/02"}],"apog\xe9e":[{auteur:"Johann Peter Eckermann",initiales:"JE",oeuvre:"Conversations de Goethe, ann\xe9e 1828",epoque:"XIXe",texte:"\xab Mais vous avez raison, le vrai [apog\xe9e] de sa carri\xe8re se trouve dans sa jeunesse.",glose:"Dans cette conversation, il est question de Napol\xe9on, idole d'une nation d\xe8s l'\xe2ge de 27 ans.",source:"https://fr.wikisource.org/wiki/Conversations_de_Goethe/Ann%C3%A9e_1828"}],conciliabule:[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"\xc9maux et Cam\xe9es, \xab Ce que disent les hirondelles \xbb",epoque:"XIXe",texte:"Les hirondelles sur le toit / Tiennent des [conciliabules] : / Voici l\u2019hiver, voici le froid !",glose:"\xc0 l'automne, les hirondelles se r\xe9unissent pour pr\xe9parer leur d\xe9part.",source:"https://fr.wikisource.org/wiki/%C3%89maux_et_Cam%C3%A9es/Ce_que_disent_les_hirondelles"}],atavisme:[{auteur:"Judith Gautier",initiales:"JG",oeuvre:"Le Collier des jours, chapitre XXIX",epoque:"XIXe",texte:"Peut-\xeatre, quelque [atavisme] oriental me faisait deviner la majest\xe9 symbolique du parasol [\u2026]",glose:"L'autrice se souvient de sa fiert\xe9, petite fille, le jour de sa premi\xe8re ombrelle.",source:"https://fr.wikisource.org/wiki/Le_Collier_des_jours/Chapitre_XXIX"},{auteur:"Paul Verlaine",initiales:"PV",oeuvre:"Les M\xe9moires d\u2019un veuf, \xab Apologie \xbb",epoque:"XIXe",texte:"Pure h\xe9r\xe9dit\xe9, cher monsieur ou ch\xe8re madame, [atavisme] ind\xe9fectible !",glose:"Verlaine explique ses tournures patoisantes par ses anc\xeatres paysans et notaires de campagne.",source:"https://fr.wikisource.org/wiki/Les_M%C3%A9moires_d%E2%80%99un_veuf/Apologie"}],invectiver:[{auteur:"Maxime Gorki",initiales:"MG",oeuvre:"La M\xe8re, chapitre 1",epoque:"XXe",texte:"Quand on se rencontrait, on s\u2019entretenait de la fabrique, des machines, on [invectivait] les contrema\xeetres.",glose:"Le romancier d\xe9crit les conversations des ouvriers d'une fabrique.",source:"https://fr.wikisource.org/wiki/La_M%C3%A8re_(Gorki)/1/1"}],illusoire:[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"\xab La Fuite \xbb",epoque:"XIXe",texte:"Si le mirage [illusoire] / Nous cachait le vrai chemin",glose:"Deux amants s'appr\xeatent \xe0 fuir \xe0 travers le d\xe9sert, et l'un d'eux s'inqui\xe8te.",source:"https://fr.wikisource.org/wiki/La_Fuite_(Gautier)"}],empirique:[{auteur:"Eug\xe8ne Viollet-le-Duc",initiales:"VD",oeuvre:"Dictionnaire raisonn\xe9 de l\u2019architecture fran\xe7aise, \xab Vo\xfbte \xbb",epoque:"XIXe",texte:"Des vo\xfbtes ainsi con\xe7ues ne pouvaient \xeatre trac\xe9es sur l\u2019\xe9pure avec rigueur ; on ne les obtenait que par des t\xe2tonnements et une m\xe9thode [empirique].",glose:"L'architecte explique comment les b\xe2tisseurs du Moyen \xc2ge construisaient certaines vo\xfbtes, \xe0 force d'essais.",source:"https://fr.wikisource.org/wiki/Dictionnaire_raisonn%C3%A9_de_l%E2%80%99architecture_fran%C3%A7aise_du_XIe_au_XVIe_si%C3%A8cle/Vo%C3%BBte"}],"\xe9dicter":[{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"L\u2019\xc9ducation des adolescents au XXe si\xe8cle, 1906",epoque:"XXe",texte:"On ne peut [\xe9dicter] de r\xe8gles g\xe9n\xe9rales pour la discipline. Elle variera selon le temp\xe9rament du ma\xeetre, la nature des \xe9l\xe8ves, les habitudes locales, les circonstances.",glose:"Le fondateur des Jeux olympiques modernes parle des cours de gymnastique.",source:"https://fr.wikisource.org/wiki/L%E2%80%99%C3%89ducation_des_adolescents_au_XXe_si%C3%A8cle/Volume_I/I/XI"}],parachever:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Louis Bouilhet",epoque:"XIXe",texte:"J\u2019ai \xe9crit une page, je fais du neuf et il faut avoir une grande vertu ou un bel ent\xeatement pour poursuivre et [parachever] une semblable machine [\u2026]",glose:"Flaubert confie \xe0 son ami la difficult\xe9 de mener son livre jusqu'au bout.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0489"}],"pr\xe9coniser":[{auteur:"M. Chambon",initiales:"MC",oeuvre:"Dictionnaire du savoir-vivre, \xab C\xf4telettes \xbb, 1907",epoque:"XXe",texte:"Le manche des c\xf4telettes est par\xe9 d\u2019une manchette de papier \xe0 franges. La mode [pr\xe9conise] de petits manches en m\xe9tal argent\xe9 sans en faire une obligation.",glose:"Un guide des bonnes mani\xe8res \xe0 table, au d\xe9but du XXe si\xe8cle.",source:"https://fr.wikisource.org/wiki/Dictionnaire_du_savoir-vivre/Articles/C%C3%B4telettes"}],objecter:[{auteur:"Georges Rodenbach",initiales:"GR",oeuvre:"Bruges-la-Morte, chapitre 13",epoque:"XIXe",texte:"Hugues [objecta] les voisins, les servantes qui jasent.",glose:"Jane veut venir d\xeener chez Hugues, qui craint les comm\xe9rages.",source:"https://fr.wikisource.org/wiki/Bruges-la-Morte/13"},{auteur:"Fran\xe7ois Arago",initiales:"FA",oeuvre:"Astronomie populaire",epoque:"XIXe",texte:"On lui [objecta], dit-on, que dans cette hypoth\xe8se les deux plan\xe8tes auraient des phases.",glose:"L'astronome raconte une objection faite \xe0 Copernic au sujet de Mercure et de V\xe9nus.",source:"https://fr.wikisource.org/wiki/Astronomie_populaire_(Arago)/XIX/02"}],"pr\xe9sager":[{auteur:"Alexandre Dumas",initiales:"AD",oeuvre:"Le Vicomte de Bragelonne",epoque:"XIXe",texte:"Pauvre M. Fouquet ! cela ne lui [pr\xe9sage] rien de bon.",glose:"D'Artagnan voit une vieille duchesse faire la cour \xe0 la ma\xeetresse de Colbert, le rival de Fouquet.",source:"https://fr.wikisource.org/wiki/Le_Vicomte_de_Bragelonne/Chapitre_CCXLII"}],hiatus:[{auteur:"Jean le Rond d\u2019Alembert",initiales:"DA",oeuvre:"Correspondance avec Voltaire",epoque:"XVIIIe",texte:"Les [hiatus] sont sans doute un d\xe9faut en g\xe9n\xe9ral ; mais, 1\xb0. il y a des hiatus \xe0 chaque moment au milieu des mots, et ces hiatus ne choquent point [\u2026]",glose:"Au sens premier, le hiatus est la rencontre de deux voyelles, comme dans \xab il y a \xbb.",source:"https://fr.wikisource.org/wiki/Correspondance_(d%E2%80%99Alembert)/Correspondance_avec_Voltaire/107"}],assidu:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 la princesse Mathilde",epoque:"XIXe",texte:"Donc, je redeviendrai un h\xf4te [assidu] de la rue de Berri et de Saint-Gratien.",glose:"Flaubert promet de revenir souvent dans le salon de la princesse, \xe0 Paris et \xe0 la campagne.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_8-9/1949"}],pathos:[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre de 1765",epoque:"XVIIIe",texte:"[\u2026] je voudrais bien qu\u2019avec une si belle \xe2me et si honn\xeate cet homme e\xfbt un peu plus de go\xfbt, et qu\u2019il ne mit pas dans ses m\xe9moires tant de [pathos] de coll\xe8ge.",glose:"Voltaire trouve trop emphatiques les m\xe9moires de l'avocat qui va plaider pour la famille Sirven.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1765/Lettre_5964"}],"\xe9mailler":[{auteur:"Abb\xe9 Rozier",initiales:"AR",oeuvre:"Cours complet d\u2019agriculture, \xab Couleur des plantes \xbb, 1784",epoque:"XVIIIe",texte:"Quel est l\u2019homme qui a pu se promener dans un pr\xe9 [\xe9maill\xe9] de fleurs, dans un jardin d\xe9cor\xe9 de tout ce que la nature offre de plus riant [\u2026] sans \xeatre \xe9merveill\xe9 ?",glose:"Un pr\xe9 \xe9maill\xe9 de fleurs en est parsem\xe9, comme de petites touches de couleur.",source:"https://fr.wikisource.org/wiki/Cours_d%E2%80%99agriculture_(Rozier)/COULEUR_DES_PLANTES"}],"p\xe2tir":[{auteur:"Jean de La Fontaine",initiales:"LF",oeuvre:"Fables, \xab Les deux Taureaux et une Grenouille \xbb",epoque:"XVIIe",texte:"H\xe9las ! on voit que de tout temps / Les petits ont [p\xe2ti] des sottises des grands.",glose:"La morale de la fable : quand les puissants se disputent, ce sont les faibles qui paient.",source:"https://fr.wikisource.org/wiki/Fables_de_La_Fontaine_(%C3%A9d._1874)/Les_deux_Taureaux_et_une_Grenouille"}],"ind\xe9fectible":[{auteur:"Han Ryner",initiales:"HR",oeuvre:"Les Paraboles cyniques, \xab Le Couple \xbb, 1922",epoque:"XXe",texte:"Mais toi, ton [ind\xe9fectible] sagesse et ton ind\xe9fectible joie\u2026",glose:"Un jeune disciple admire son ma\xeetre, dont la sagesse et la joie ne faiblissent jamais.",source:"https://fr.wikisource.org/wiki/Les_Paraboles_cyniques/Le_Couple"}],"fac\xe9tieux":[{auteur:"George Sand",initiales:"GS",oeuvre:"Histoire de ma vie, 1855",epoque:"XIXe",texte:"Les gens de Nohant, tous paysans, tous petits propri\xe9taires [\u2026] sont d\u2019une humeur [fac\xe9tieuse] sous un air de gravit\xe9.",glose:"La romanci\xe8re d\xe9crit les habitants de son village du Berry.",source:"https://fr.wikisource.org/wiki/Histoire_de_ma_vie_(Sand,_Calmann-Levy_1855)/1/05"}],"r\xe9genter":[{auteur:"Louis-S\xe9bastien Mercier",initiales:"LM",oeuvre:"Tableau de Paris, \xab Professeurs de l\u2019Universit\xe9 \xbb, 1782",epoque:"XVIIIe",texte:"Accoutum\xe9s \xe0 [r\xe9genter], ils croient pouvoir r\xe9genter tout le monde.",glose:"Mercier se moque des professeurs, habitu\xe9s \xe0 faire la le\xe7on et qui la font partout.",source:"https://fr.wikisource.org/wiki/Tableau_de_Paris/118"}],embrigader:[{auteur:"Ren\xe9 Doumic",initiales:"RD",oeuvre:"\xab Revue litt\xe9raire, Trois po\xe8tes \xbb, 1900",epoque:"XIXe",texte:"En fait il ne s\u2019\xe9tait [embrigad\xe9] dans aucune \xe9cole ; surtout il r\xe9pudiait les excentricit\xe9s tapageuses [\u2026]",glose:"Le critique parle du po\xe8te Albert Samain, rest\xe9 \xe0 l'\xe9cart des groupes litt\xe9raires.",source:"https://fr.wikisource.org/wiki/Revue_litt%C3%A9raire_-_Trois_po%C3%A8tes"}],chapitrer:[{auteur:"George Sand",initiales:"GS",oeuvre:"Lettre \xe0 Hippolyte Ch\xe2tiron, 1843",epoque:"XIXe",texte:"Il faut que, cette ann\xe9e, ma\xeetre Maurice \xe9pouse dame Peinture pour tout de bon ; [\u2026] Aide-moi \xe0 [chapitrer] Maurice sur ce point.",glose:"Sand demande \xe0 son demi-fr\xe8re de l'aider \xe0 convaincre son fils Maurice de se consacrer \xe0 la peinture.",source:"https://fr.wikisource.org/wiki/Correspondance_1812-1876,_2/1843/CCXXII"}],pertinent:[{auteur:"Dictionnaire de Tr\xe9voux",initiales:"DT",oeuvre:"Dictionnaire de Tr\xe9voux, 1771, \xab D\xe9faite \xbb",epoque:"XVIIIe",texte:"Cette raison n\u2019est pas [pertinente], ce n\u2019est qu\u2019une d\xe9faite.",glose:"Une d\xe9faite, au sens ancien, c'est une excuse habile pour se d\xe9rober.",source:"https://fr.wikisource.org/wiki/Dictionnaire_de_Tr%C3%A9voux/6e_%C3%A9dition,_1771/D%C3%89FAITE"}],pernicieux:[{auteur:"Denis Diderot",initiales:"DD",oeuvre:"L\u2019Encyclop\xe9die, \xab Pernicieux \xbb, 1751",epoque:"XVIIIe",texte:"[Pernicieux], adj, (Gram.) capable d\u2019entra\xeener la perte de quelque chose. Un discours est pernicieux ; un conseil est pernicieux [\u2026]",glose:"La d\xe9finition que donnait l'Encyclop\xe9die de Diderot et d'Alembert.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/PERNICIEUX"}],"d\xe9plorer":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Guy de Maupassant, 1880",epoque:"XIXe",texte:"Je [d\xe9plore] que ton volume de vers ne soit pas encore paru.",glose:"Flaubert s'impatiente de voir para\xeetre le premier recueil de po\xe8mes de son jeune prot\xe9g\xe9.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_8-9/1961"}],"r\xe9prouver":[{auteur:"L\u2019Encyclop\xe9die",initiales:"E",oeuvre:"L\u2019Encyclop\xe9die, \xab Calomnie \xbb, 1751",epoque:"XVIIIe",texte:"La calomnie est un mensonge odieux que chacun [r\xe9prouve] & d\xe9teste, ne f\xfbt-ce que par la crainte d\u2019en \xeatre quelque jour l\u2019objet.",glose:"L'article remarque que ceux qui condamnent la calomnie ne sont pas toujours innocents.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Encyclop%C3%A9die/1re_%C3%A9dition/CALOMNIE"}],proscrire:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Les Ch\xe2timents, \xab Ultima verba \xbb, 1853",epoque:"XIXe",texte:"Je resterai [proscrit], voulant rester debout.",glose:"Exil\xe9, Hugo refuse de rentrer en France tant que Napol\xe9on III sera au pouvoir.",source:"https://fr.wikisource.org/wiki/Ultima_verba_(Hugo)"}],fomenter:[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre de 1767",epoque:"XVIIIe",texte:"Je sais bien qu\u2019au th\xe9\xe2tre on ne se soucie gu\xe8re du style ; mais le th\xe9\xe2tre devient barbare, et ce n\u2019est pas \xe0 moi de [fomenter] la barbarie.",glose:"Voltaire se plaint qu'on ajoute des vers ridicules \xe0 ses pi\xe8ces.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1767/Lettre_6756"}],"p\xe9rorer":[{auteur:"Jules Verne",initiales:"JV",oeuvre:"De la Terre \xe0 la Lune, chapitre 3",epoque:"XIXe",texte:"[\u2026] chacun conversait, [p\xe9rorait], discutait, disputait, approuvait, applaudissait [\u2026]",glose:"Toute la ville de Baltimore s'enflamme pour le projet d'envoyer un boulet sur la Lune.",source:"https://fr.wikisource.org/wiki/De_la_Terre_%C3%A0_la_Lune/Chapitre_3"},{auteur:"Alain",initiales:"A",oeuvre:"Propos, tome 1, 1920",epoque:"XXe",texte:"Ainsi [p\xe9rorait] \xe0 toute vapeur un jeune marchand de philosophie. Mais un vieux sage l\u2019interrompit [\u2026]",glose:"Le philosophe met en sc\xe8ne un jeune orateur s\xfbr de lui, qu'un vieux sage remet \xe0 sa place.",source:"https://fr.wikisource.org/wiki/Les_Propos_d%E2%80%99Alain_(1920)/Tome_1/095"}],expier:[{auteur:"L\xe9on Tolsto\xef",initiales:"LT",oeuvre:"Anna Kar\xe9nine, traduction de J.-Wladimir Bienstock",epoque:"XIXe",texte:"Repentez-vous, monsieur. Que faire ? Il faut [expier] sa faute\u2026",glose:"Le vieux domestique pousse son ma\xeetre \xe0 aller demander pardon \xe0 sa femme.",source:"https://fr.wikisource.org/wiki/Anna_Kar%C3%A9nine_(trad._Bienstock)/I/02"}]}},262,[]);
__d(function(e,r,i,s,t,n,a){t.exports={injonction:[{auteur:"Aristote",initiales:"A",oeuvre:"Po\xe9tique, chapitre 20, traduction de Charles-\xc9mile Ruelle",epoque:"Antiquit\xe9",texte:"Ordonner, all\xe8gue-t-il, de faire ou de ne pas faire une chose, c\u2019est une [injonction].",glose:"Aristote rapporte une critique de Protagoras : en ouvrant l'Iliade par \xab Chante, d\xe9esse \xbb, Hom\xe8re croit prier, mais il donne un ordre.",source:"https://fr.wikisource.org/wiki/Po%C3%A9tique_(trad._Ruelle)/Chapitre_20"}],"\xe9difiant":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Correspondance, tome 5",epoque:"XIXe",texte:"Depuis deux mois que je suis \xe0 Paris, j\u2019ai vu fort peu de monde, mais ce que j\u2019en sais n\u2019est ni beau ni [\xe9difiant].",glose:"Dans une lettre, Flaubert juge s\xe9v\xe8rement le milieu parisien, o\xf9 \xab on se rue dans le m\xe9diocre \xbb.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_5/0715"}],"d\xe9nigrer":[{auteur:"Remy de Gourmont",initiales:"RG",oeuvre:"Le Puits de la v\xe9rit\xe9, \xab Pr\xe9jug\xe9s \xbb, 1922",epoque:"XXe",texte:"Reconnaissons cependant ce qu\u2019il y a de touchant dans ce petit patriotisme qui nous pousse toujours malgr\xe9 toute \xe9vidence, pour vanter notre pays natal, \xe0 [d\xe9nigrer] les autres pays.",glose:"L'\xe9crivain s'amuse de notre manie de rabaisser les autres pays pour mieux vanter le n\xf4tre.",source:"https://fr.wikisource.org/wiki/Le_Puits_de_la_v%C3%A9rit%C3%A9/Pr%C3%A9jug%C3%A9s"}],inepte:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Correspondance, tome 4",epoque:"XIXe",texte:"As-tu suffisamment rugi de tout le tapage [inepte] que l\u2019on a fait autour des deux discours acad\xe9miques.",glose:"Flaubert \xe9crit \xe0 un ami, agac\xe9 par le bruit fait autour de 2 discours prononc\xe9s \xe0 l'Acad\xe9mie fran\xe7aise.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0675"}],ostracisme:[{auteur:"Charles Bonnet",initiales:"CB",oeuvre:"La Paling\xe9n\xe9sie philosophique, 1769",epoque:"XVIIIe",texte:"On \xe9crivoit le nom du coupable sur des coquilles, & c\u2019est de l\xe0 que l\u2019[ostracisme] tiroit sa d\xe9nomination : le mot grec ostracon signifie coquille.",glose:"Le savant genevois explique, dans l'orthographe de son temps, l'origine du mot.",source:"https://fr.wikisource.org/wiki/La_paling%C3%A9n%C3%A9sie_philosophique/Du_rappel_des_id%C3%A9es_par_les_mots"}],gabegie:[{auteur:"Jean-Ren\xe9 Cazeneuve",initiales:"JC",oeuvre:"Assembl\xe9e nationale, 17 octobre 2023",epoque:"2023",texte:"[\u2026] de l\u2019autre, celles qui parlent de [gabegie], mais proposent des amendements qui engageraient plusieurs dizaines de milliards de d\xe9penses suppl\xe9mentaires.",glose:"Le rapporteur g\xe9n\xe9ral du budget r\xe9pond aux oppositions qui d\xe9noncent le gaspillage tout en proposant de nouvelles d\xe9penses.",source:"https://www.assemblee-nationale.fr/dyn/16/comptes-rendus/seance/session-ordinaire-de-2023-2024/premiere-seance-du-mardi-17-octobre-2023"}],"d\xe9liquescence":[{auteur:"Fran\xe7ois Rozier",initiales:"FR",oeuvre:"Cours complet d'agriculture, article \xab Bauche \xbb",epoque:"XVIIIe",texte:"Chacun sait encore que ce sel se cristallise si l\u2019air est parfaitement sec, mais qu\u2019il tombe en [d\xe9liquescence], c\u2019est-\xe0-dire qu\u2019il se fond \xe0 l\u2019air si l\u2019atmosph\xe8re est humide.",glose:"Le sens premier, en chimie : un sel qui absorbe l'humidit\xe9 de l'air et finit par fondre.",source:"https://fr.wikisource.org/wiki/Cours_d%E2%80%99agriculture_(Rozier)/BAUCHE"},{auteur:"Fr\xe8re Marie-Victorin",initiales:"MV",oeuvre:"Croquis laurentiens, 1920",epoque:"XXe",texte:"Cet arbre-roi se fait volontiers histrion, s\u2019appropriant tant\xf4t la carrure du ch\xeane, tant\xf4t la [d\xe9liquescence] un peu mi\xe8vre du bouleau.",glose:"Le botaniste qu\xe9b\xe9cois d\xe9crit l'orme, qui prend tour \xe0 tour l'allure solide du ch\xeane ou l'allure molle du bouleau.",source:"https://fr.wikisource.org/wiki/Croquis_laurentiens/32"}],"aust\xe8re":[{auteur:"Alphonse Allais",initiales:"AA",oeuvre:"L'Affaire Blaireau, 1899, titre du chapitre XIII",epoque:"XIXe",texte:"Dans lequel la prison de Montpaillard appara\xeetra comme un \xe9tablissement encore moins [aust\xe8re] qu\u2019on n\u2019aurait pu s\u2019y attendre.",glose:"L'humoriste annonce, dans un titre de chapitre, une prison bien plus confortable que pr\xe9vu.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Affaire_Blaireau"}],conspuer:[{auteur:"Hector Berlioz",initiales:"HB",oeuvre:"Correspondance in\xe9dite",epoque:"XIXe",texte:"J\u2019y arrivais avec l\u2019id\xe9e de tomber au milieu d\u2019une population de p\xe9dants antiquaires ne voulant rien admettre que Mozart, et pr\xeats \xe0 [conspuer] tout compositeur moderne.",glose:"Le compositeur raconte son arriv\xe9e \xe0 Prague, o\xf9 il a finalement trouv\xe9 des musiciens attentifs et d\xe9vou\xe9s.",source:"https://fr.wikisource.org/wiki/Correspondance_in%C3%A9dite_de_Hector_Berlioz/031"}],capiteux:[{auteur:"Ernest d'Hervilly",initiales:"EH",oeuvre:"\xab Fin de car\xeame \xbb, Le Parnasse contemporain, 1876",epoque:"XIXe",texte:"La main tremble ; on sourit sans motif ; la narine / Se grise des parfums [capiteux] du printemps.",glose:"Le po\xe8te d\xe9crit l'arriv\xe9e du printemps, qui rend tout le monde un peu ivre.",source:"https://fr.wikisource.org/wiki/Le_Parnasse_contemporain/1876/Fin_de_car%C3%AAme"},{auteur:"William Chapman",initiales:"WC",oeuvre:"\xab Mai \xbb, 1912",epoque:"XXe",texte:"L\u2019air est lourd du parfum [capiteux] des lilas.",glose:"Le po\xe8te qu\xe9b\xe9cois c\xe9l\xe8bre le mois de mai.",source:"https://fr.wikisource.org/wiki/Mai_(Chapman)"}],sobriquet:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Les Mis\xe9rables, tome 3, livre 6",epoque:"XIXe",texte:"Il s\u2019\xe9tait enfui comme un parthe en leur d\xe9cochant un [sobriquet].",glose:"L'\xe9tudiant Courfeyrac surnomme un vieil homme et sa fille \xab monsieur Leblanc \xbb et \xab mademoiselle Lanoire \xbb.",source:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_3/Livre_6/01"},{auteur:"\xc9mile Littr\xe9",initiales:"EL",oeuvre:"Pathologie verbale, 1880",epoque:"XIXe",texte:"Surnom est le terme g\xe9n\xe9ral ; [sobriquet] y introduit une nuance ; et les nuances sont pr\xe9cieuses dans une langue.",glose:"Le lexicographe explique ce qui distingue le sobriquet du simple surnom.",source:"https://fr.wikisource.org/wiki/Pathologie_verbale_ou_l%C3%A9sions_de_certains_mots_dans_le_cours_de_l%E2%80%99usage/S"}],"biens\xe9ance":[{auteur:"Christophe Naegelen",initiales:"CN",oeuvre:"Assembl\xe9e nationale, 12 octobre 2026",epoque:"2026",texte:"Nos d\xe9bats se sont jusqu\u2019ici plut\xf4t d\xe9roul\xe9s dans le calme, la [biens\xe9ance] et le respect des uns et des autres, ne me faites donc pas de faux proc\xe8s !",glose:"Le rapporteur d'un texte demande \xe0 ses coll\xe8gues de garder le ton courtois des d\xe9bats.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2026-2027/premiere-seance-du-lundi-12-octobre-2026"},{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre de 1758",epoque:"XVIIIe",texte:"[\u2026] la religion, l\u2019honneur, les [biens\xe9ances] les plus communes, et le savoir-vivre, ne permettent d\u2019\xe9crire de pareilles choses ni \xe0 des personnes qu\u2019on conna\xeet, ni \xe0 des personnes qu\u2019on ne conna\xeet pas.",glose:"La famille et les amis de Voltaire r\xe9pondent \xe0 un certain M. L\xe9gier, auteur d'un envoi jug\xe9 inconvenant.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1758/Lettre_3554"}],saugrenu:[{auteur:"Fran\xe7oise Gatel",initiales:"FG",oeuvre:"Assembl\xe9e nationale, 7 avril 2026",epoque:"2026",texte:"Puisque vous avez employ\xe9 le mot \xab abracadabrantesque \xbb, monsieur Cordier, je suis tent\xe9e d\u2019en ajouter un autre pour qualifier cette situation : \xab [saugrenue] \xbb.",glose:"La ministre r\xe9pond du tac au tac \xe0 un d\xe9put\xe9 qui vient de juger la situation \xab abracadabrantesque \xbb.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/troisieme-seance-du-mardi-07-avril-2026"}],"\xe9vincer":[{auteur:"Annie Genevard",initiales:"AG",oeuvre:"Assembl\xe9e nationale, 29 mai 2026",epoque:"2026",texte:"La r\xe9daction en l\u2019\xe9tat de l\u2019article 12 bis n\u2019est pas acceptable, car la Safer est compl\xe8tement [\xe9vinc\xe9e].",glose:"La ministre de l'agriculture refuse un article qui \xe9carte la Safer, l'organisme qui peut intervenir pour pr\xe9server les terres agricoles.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/deuxieme-seance-du-vendredi-29-mai-2026"}],futile:[{auteur:"Laurent Croizier",initiales:"LC",oeuvre:"Assembl\xe9e nationale, 9 juillet 2026",epoque:"2026",texte:"L\u2019augmentation du nombre de refus d\u2019obtemp\xe9rer observ\xe9e ces derni\xe8res ann\xe9es, parfois pour des motifs totalement [futiles], met en \xe9vidence la n\xe9cessit\xe9 de compl\xe9ter la r\xe9ponse p\xe9nale par des actions de pr\xe9vention.",glose:"Le d\xe9put\xe9 d\xe9fend une campagne nationale de pr\xe9vention sur les refus d'obtemp\xe9rer.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-extraordinaire-de-2025-2026/deuxieme-seance-du-jeudi-09-juillet-2026"},{auteur:"Claude Debussy",initiales:"CD",oeuvre:"Monsieur Croche, \xab Le Dr Richter \xbb",epoque:"XXe",texte:"D\xe9range-t-on un pareil brave homme sous le [futile] pr\xe9texte de lui arracher des confidences ?",glose:"Le compositeur renonce \xe0 interroger le vieux musicien Richter, pench\xe9 sur son piano.",source:"https://fr.wikisource.org/wiki/Monsieur_Croche/Le_Dr_Richter"}],lucide:[{auteur:"Agn\xe8s Firmin Le Bodo",initiales:"AF",oeuvre:"Assembl\xe9e nationale, 8 juillet 2026",epoque:"2026",texte:"Soyons [lucides] : aucun texte ne r\xe9soudra \xe0 lui seul l\u2019ensemble des difficult\xe9s de notre justice criminelle. Personne ne le pr\xe9tend.",glose:"La d\xe9put\xe9e soutient un texte sur la justice criminelle, sans en exag\xe9rer la port\xe9e.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-extraordinaire-de-2025-2026/deuxieme-seance-du-mercredi-08-juillet-2026"},{auteur:"\xc9mile Bergerat",initiales:"EB",oeuvre:"Souvenirs d\u2019un enfant de Paris, \xab Chez Victor Hugo \xbb",epoque:"XXe",texte:"Quel homme fin que ce petit homme et quel grand esprit [lucide], calme et pratique !",glose:"Le journaliste d\xe9crit l'homme politique Louis Blanc, pr\xe9sent chez Victor Hugo.",source:"https://fr.wikisource.org/wiki/Souvenirs_d%E2%80%99un_enfant_de_Paris%2C_vol._2/Chez_Victor_Hugo/II"}],liesse:[{auteur:"Corentin Le Fur",initiales:"CL",oeuvre:"Assembl\xe9e nationale, 2 juin 2026",epoque:"2026",texte:"\xc0 cette occasion, la France aurait d\xfb vivre un grand moment de joie, de rassemblements festifs et de [liesse] collective.",glose:"Le d\xe9put\xe9 parle de la 2e victoire cons\xe9cutive du PSG en Ligue des champions.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-mardi-02-juin-2026"},{auteur:"\xc9sope",initiales:"\xc9",oeuvre:"Fables, \xab Le Soleil et les Grenouilles \xbb, traduction d\u2019\xc9mile Chambry",epoque:"Antiquit\xe9",texte:"Tous les animaux se r\xe9jouissaient de l\u2019\xe9v\xe9nement, et il n\u2019\xe9tait pas jusqu\u2019aux grenouilles qui ne fussent en [liesse].",glose:"Tous les animaux f\xeatent les noces du Soleil. Une grenouille rappelle que le Soleil ass\xe8che les mar\xe9cages.",source:"https://fr.wikisource.org/wiki/Fables_d%E2%80%99%C3%89sope_(trad._Chambry%2C_1927)/Le_Soleil_et_les_Grenouilles"}],"r\xe9it\xe9rer":[{auteur:"Marianne Maximi",initiales:"MM",oeuvre:"Assembl\xe9e nationale, 17 juillet 2026",epoque:"2026",texte:"Mon avis est donc d\xe9favorable et j\u2019aurai l\u2019occasion de le [r\xe9it\xe9rer] sur d\u2019autres amendements.",glose:"La rapporteure annonce qu'elle redonnera le m\xeame avis sur les amendements suivants.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-extraordinaire-de-2025-2026/deuxieme-seance-du-vendredi-17-juillet-2026"}],vindicte:[{auteur:"Catherine P\xe9gard",initiales:"CP",oeuvre:"Assembl\xe9e nationale, 10 novembre 2026",epoque:"2026",texte:"[\u2026] nous devons soutenir la presse face aux attaques, face \xe0 la [vindicte], face aux manipulations, et cela, d\u2019o\xf9 qu\u2019elles viennent.",glose:"La ministre de la culture d\xe9fend la libert\xe9 de la presse.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2026-2027/premiere-seance-du-mardi-10-novembre-2026"}],opprobre:[{auteur:"Pauline Cestri\xe8res",initiales:"PC",oeuvre:"Assembl\xe9e nationale, 21 juillet 2026",epoque:"2026",texte:"Non pour jeter l\u2019[opprobre] sur les professionnels, essentiels \xe0 la prise en charge de nos enfants, mais bien pour am\xe9liorer les contr\xf4les [\u2026]",glose:"La d\xe9put\xe9e pr\xe9cise l'esprit d'un texte sur le contr\xf4le des personnes qui travaillent aupr\xe8s des enfants.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-extraordinaire-de-2025-2026/premiere-seance-du-mardi-21-juillet-2026"}],"\xe9radiquer":[{auteur:"Ayda Hadizadeh",initiales:"AH",oeuvre:"Assembl\xe9e nationale, 1er juillet 2026",epoque:"2026",texte:"[\u2026] que lorsque nous serons d\xe9termin\xe9s \xe0 [\xe9radiquer] [\u2026] je dis bien \xe9radiquer, non amoindrir ni att\xe9nuer [\u2026] la mis\xe8re qui s\u2019abat sur nos enfants.",glose:"La d\xe9put\xe9e cite Victor Hugo et ses \xab mis\xe9rables \xbb pendant un d\xe9bat sur la pauvret\xe9 des enfants.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-extraordinaire-de-2025-2026/premiere-seance-du-mercredi-01-juillet-2026"}],incisif:[{auteur:"Anne Bergantz",initiales:"AB",oeuvre:"Assembl\xe9e nationale, 3 juin 2026",epoque:"2026",texte:"Il faut adapter notre droit, le rendre plus [incisif], plus r\xe9actif.",glose:"La d\xe9put\xe9e soutient un texte contre le trafic de drogue.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-mercredi-03-juin-2026"}],sordide:[{auteur:"Dominique Voynet",initiales:"DV",oeuvre:"Assembl\xe9e nationale, 30 mars 2026",epoque:"2026",texte:"[\u2026] l\u2019\xe9tat [sordide] des chambres d\u2019isolement de certains centres hospitaliers sp\xe9cialis\xe9s (CHS) psychiatriques [\u2026]",glose:"La d\xe9put\xe9e \xe9num\xe8re des lieux d'enfermement en mauvais \xe9tat, des prisons aux h\xf4pitaux psychiatriques.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-lundi-30-mars-2026"}],insolite:[{auteur:"Hector Malot",initiales:"HM",oeuvre:"En famille, 1893, chapitre XV",epoque:"XIXe",texte:"Non seulement personne ne s\u2019\xe9veilla, comme elle le craignait, mais encore il ne parut pas que ce bruit [insolite] e\xfbt troubl\xe9 une seule des dormeuses.",glose:"En pleine nuit, l'h\xe9ro\xefne heurte une vitre et craint d'avoir r\xe9veill\xe9 les dormeuses.",source:"https://fr.wikisource.org/wiki/En_famille/Chapitre_XV"}],torpeur:[{auteur:"Pierre Loti",initiales:"PL",oeuvre:"Le Roman d\u2019un enfant, 1890",epoque:"XIXe",texte:"Tout le village \xe9tait alourdi et chaud, silencieux dans la [torpeur] du midi d\u2019\xe9t\xe9 [\u2026]",glose:"L'\xe9crivain se souvient d'un village endormi par la chaleur.",source:"https://fr.wikisource.org/wiki/Le_Roman_d%E2%80%99un_enfant/45"},{auteur:"Jules Verne",initiales:"JV",oeuvre:"Cinq Semaines en ballon, 1863, chapitre 26",epoque:"XIXe",texte:"En prenant terre, Dick et Joe sortirent de leur pesante [torpeur].",glose:"Les voyageurs du ballon sortent enfin de leur engourdissement au moment de se poser.",source:"https://fr.wikisource.org/wiki/Cinq_Semaines_en_ballon/Chapitre_26"}],importun:[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre de 1737",epoque:"XVIIIe",texte:"Je suis un [importun] bavard ; je vous embrasse.",glose:"Voltaire termine ainsi une longue lettre remplie de demandes \xe0 un ami.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1737/Lettre_800"},{auteur:"Jules Girardin",initiales:"JG",oeuvre:"Les Braves Gens, 1873, chapitre XVIII",epoque:"XIXe",texte:"Il se reprocha cette mauvaise pens\xe9e, et il y eut en lui comme une lutte entre son respect pour Virgile et une forte envie de le trouver [importun].",glose:"Un \xe9colier s'ennuie pendant la traduction de Virgile en classe.",source:"https://fr.wikisource.org/wiki/Les_Braves_Gens/18"}],consternation:[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 7 f\xe9vrier 1847",epoque:"XIXe",texte:"Il a [constern\xe9] l\u2019auditoire.",glose:"Le peintre rapporte qu'un confr\xe8re a d\xe9fendu, pour une future soci\xe9t\xe9, des r\xe8gles si strictes qu'elles auraient exclu presque tout le monde.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/7_f%C3%A9vrier_1847"}],subodorer:[{auteur:"Maurice Rollinat",initiales:"MR",oeuvre:"Les N\xe9vroses, \xab Les Parfums \xbb",epoque:"XIXe",texte:"Se gorger de parfums comme d\u2019une p\xe2ture, / C\u2019est bien [subodorer] l\u2019\xe2me de la Nature [\u2026]",glose:"Le po\xe8te joue sur le sens premier du mot : deviner la nature en la respirant.",source:"https://fr.wikisource.org/wiki/Les_N%C3%A9vroses_(Rollinat)/Les_Parfums"}]}},263,[]);
__d(function(e,r,i,t,s,u,o){s.exports={augurer:[{auteur:"Hector Berlioz",initiales:"HB",oeuvre:"Lettre \xe0 Auguste Morel, 13 f\xe9vrier 1859",epoque:"XIXe",texte:"On nous annonce pour la fin du mois le Faust de Gounod, dont je crois qu\u2019il faut bien [augurer].",glose:"Le compositeur attend avec confiance la cr\xe9ation du Faust de Gounod, dont on dit beaucoup de bien.",source:"https://fr.wikisource.org/wiki/Correspondance_in%C3%A9dite_de_Hector_Berlioz/095"}],anachronique:[{auteur:"Remy de Gourmont",initiales:"RG",oeuvre:"Promenades litt\xe9raires, \xab Une enqu\xeate \xbb",epoque:"XXe",texte:"D\u2019ailleurs, la statuaire de la rue Bonaparte n\u2019est pas beaucoup plus m\xe9diocre que celle des salons annuels ; elle est un peu plus [anachronique], voil\xe0 tout.",glose:"Le critique juge l'art \xe9difiant de la rue Bonaparte \xe0 peine plus d\xe9mod\xe9 que celui des salons officiels.",source:"https://fr.wikisource.org/wiki/Promenades_Litt%C3%A9raires_(Gourmont)/Une_enqu%C3%AAte"}],"r\xe9pr\xe9hensible":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 L\xe9on Cladel, 9 mai 1877",epoque:"XIXe",texte:"Rien n\u2019y est [r\xe9pr\xe9hensible] soit comme politique, soit comme morale ; ce qu\u2019il vous a dit est un pr\xe9texte.",glose:"Flaubert a lu d'une traite le livre de son ami, qu'un \xe9diteur h\xe9site \xe0 publier.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_8-9/1669"}],"sin\xe9cure":[{auteur:"Jules Verne",initiales:"JV",oeuvre:"Une fantaisie du docteur Ox, 1874",epoque:"XIXe",texte:"Plus de politique, plus de clubs, plus de proc\xe8s, plus de sergents de ville ! La place du commissaire Passauf recommen\xe7a \xe0 \xeatre une [sin\xe9cure] [\u2026]",glose:"La petite ville de Quiquendone a retrouv\xe9 son calme, et le commissaire n'a plus rien \xe0 faire.",source:"https://fr.wikisource.org/wiki/Une_fantaisie_du_docteur_Ox/16"},{auteur:"Fr\xe9d\xe9ric Bastiat",initiales:"FB",oeuvre:"Article paru dans La R\xe9publique fran\xe7aise",epoque:"XIXe",texte:"Une [sin\xe9cure] supprim\xe9e contrarie le titulaire et ne l\u2019irrite pas ; une sin\xe9cure passant de mains en mains exasp\xe8re le destitu\xe9, d\xe9sappointe dix postulants et m\xe9contente le public.",glose:"L'\xe9conomiste conseille au gouvernement de supprimer les postes inutiles plut\xf4t que de les redistribuer.",source:"https://fr.wikisource.org/wiki/Le_Libre-%C3%A9change_et_autres_%C3%A9crits/Tome_7/Texte_50"}],galimatias:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre au comte d\u2019Argental, 11 juin 1764",epoque:"XVIIIe",texte:"Si on fait parler ce h\xe9ros du fanatisme comme il parlait, ce sera un beau [galimatias], mais c\u2019est avec du galimatias qu\u2019il parvint \xe0 gouverner l\u2019Angleterre [\u2026]",glose:"Voltaire apprend qu'on va jouer une pi\xe8ce sur Cromwell, connu pour ses discours embrouill\xe9s.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1764/Lettre_5670"}],subterfuge:[{auteur:"Madame de Kr\xfcdener",initiales:"MK",oeuvre:"Val\xe9rie, 1803, lettre X",epoque:"XIXe",texte:"[\u2026] je sentois en moi-m\xeame que je pouvois tromper Val\xe9rie, et m\u2019enorgueillir m\xeame de mon [subterfuge], et qu\u2019il m\u2019\xe9toit impossible de tromper le comte volontairement.",glose:"Le narrateur cache \xe0 Val\xe9rie qu'il l'aime, mais il ne supporte pas de mentir \xe0 son mari, le comte.",source:"https://fr.wikisource.org/wiki/Valerie/Lettre_10"}],extrapoler:[{auteur:"Henri Poincar\xe9",initiales:"HP",oeuvre:"Science et m\xe9thode, 1908",epoque:"XXe",texte:"Nous sommes accoutum\xe9s \xe0 [extrapoler], ce qui est un moyen de d\xe9duire l\u2019avenir du pass\xe9 et du pr\xe9sent [\u2026]",glose:"Le math\xe9maticien explique comment pr\xe9voir l'avenir des math\xe9matiques : \xe9tudier leur histoire et leur \xe9tat pr\xe9sent.",source:"https://fr.wikisource.org/wiki/Science_et_m%C3%A9thode/Livre_premier,_%C2%A7_II"}],"pr\xe9misse":[{auteur:"Arthur Schopenhauer",initiales:"AS",oeuvre:"L\u2019Art d\u2019avoir toujours raison, stratag\xe8me IV",epoque:"XIXe",texte:"S\u2019il est douteux que l\u2019adversaire admette les [pr\xe9misses], il faut \xe9tablir des pr\xe9misses \xe0 ces pr\xe9misses, faire des pr\xe9-syllogismes et s\u2019arranger pour les faire admettre, peu importe l\u2019ordre.",glose:"Le philosophe conseille de cacher son jeu dans un d\xe9bat, pour que l'autre ne voie pas o\xf9 l'on veut en venir.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Art_d%E2%80%99avoir_toujours_raison/Stratag%C3%A8me_IV"}],ardu:[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 5 avril 1848",epoque:"XIXe",texte:"Tout est, dans ce style, [ardu], crevass\xe9 ou boursoufl\xe9. Les grandes et simples v\xe9rit\xe9s n\u2019ont pas besoin, pour s\u2019\xe9noncer et pour frapper les esprits, d\u2019emprunter le style d\u2019Hugo [\u2026]",glose:"Le peintre se moque de la rh\xe9torique de Blanqui, trop charg\xe9e d'images.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/5_avril_1848"}],"d\xe9risoire":[{auteur:"Jules Bois",initiales:"JB",oeuvre:"Les Petites Religions de Paris, 1894",epoque:"XIXe",texte:"Mais une foi a beau para\xeetre [d\xe9risoire], quand elle est sinc\xe8re il ne faut la railler qu\u2019avec m\xe9nagement.",glose:"Le journaliste pr\xe9sente les petites sectes de Paris, souvent tourn\xe9es en ridicule.",source:"https://fr.wikisource.org/wiki/Les_Petites_Religions_de_Paris"}],"superf\xe9tatoire":[{auteur:"Roland Lescure",initiales:"RL",oeuvre:"Assembl\xe9e nationale, 27 octobre 2025",epoque:"2025",texte:"Faire un cr\xe9dit d\u2019imp\xf4t sur des d\xe9penses obligatoires [\u2026] me semble contre-productif et [superf\xe9tatoire], notamment dans le contexte actuel.",glose:"Le ministre de l'\xe9conomie r\xe9pond \xe0 un amendement pendant le d\xe9bat sur le budget 2026.",source:"https://www.assemblee-nationale.fr/dyn/17/comptes-rendus/seance/session-ordinaire-de-2025-2026/premiere-seance-du-lundi-27-octobre-2025"}],"pr\xe9mices":[{auteur:"Fr\xe9d\xe9ric II de Prusse",initiales:"F",oeuvre:"Lettre \xe0 Voltaire, 20 janvier 1739",epoque:"XVIIIe",texte:"On offrait aux dieux, dans le paganisme, les [pr\xe9mices] des moissons et des r\xe9coltes [\u2026]",glose:"Le futur roi de Prusse, encore prince, offre \xe0 Voltaire ses premiers vers de l'ann\xe9e, comme on offrait autrefois les premiers fruits.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1739/Lettre_1036"}],impudent:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre aux fr\xe8res Goncourt, 30 novembre 1861",epoque:"XIXe",texte:"[\u2026] si les Mis\xe9rables se mettent \xe0 para\xeetre au mois de f\xe9vrier et qu\u2019on en publie deux volumes tous les mois, ne trouvez-vous pas [impudent] et imprudent de risquer Salammb\xf4 pendant ce temps-l\xe0 ?",glose:"Flaubert craint que son roman soit \xe9cras\xe9 par la sortie des Mis\xe9rables de Victor Hugo.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0696"}],"d\xe9suet":[{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"Discours d\u2019ouverture de la Conf\xe9rence des arts, lettres et sports, 1906",epoque:"XXe",texte:"Mais quoi ! allons-nous nous laisser arr\xeater par ce pr\xe9jug\xe9 sans fondement et d\xe9j\xe0 [d\xe9suet] de l\u2019incompatibilit\xe9 du sport avec certaines professions ?",glose:"Le fondateur des Jeux olympiques modernes veut r\xe9unir les artistes, les \xe9crivains et les sportifs.",source:"https://fr.wikisource.org/wiki/Discours_d%E2%80%99ouverture_de_la_Conf%C3%A9rence_des_arts,_lettres_et_sports"}],"p\xe9ricliter":[{auteur:"Hubert Wulfranc",initiales:"HW",oeuvre:"Assembl\xe9e nationale, 21 juillet 2020",epoque:"2020",texte:"Les emplois dans les r\xe9gions et, plus largement, l\u2019activit\xe9 des territoires, dont chacun se gargarise [\u2026] [p\xe9riclitent] en ce moment m\xeame.",glose:"Le d\xe9put\xe9 d\xe9fend le fret ferroviaire et les petites lignes de train menac\xe9es de fermeture.",source:"https://www.assemblee-nationale.fr/dyn/15/comptes-rendus/seance/session-extraordinaire-de-2019-2020/seance-du-mardi-21-juillet-2020"},{auteur:"Lao-tseu",initiales:"LT",oeuvre:"Tao Te King, chapitre 44, traduction de Stanislas Julien",epoque:"Antiquit\xe9",texte:"Celui qui sait s\u2019arr\xeater [\u2026] ne [p\xe9riclite] jamais.",glose:"Le vieux sage chinois conseille de ne pas courir apr\xe8s la gloire et les richesses.",source:"https://fr.wikisource.org/wiki/Tao_Te_King_(Stanislas_Julien)/Chapitre_44"}],"d\xe9convenue":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 sa ni\xe8ce Caroline, 11 juillet 1875",epoque:"XIXe",texte:"Laporte n\u2019est pas venu d\xe9jeuner aujourd\u2019hui ; il n\u2019avait pas promis de venir, du reste. C\u2019est \xe9gal, \xe7\u2019a \xe9t\xe9 une petite [d\xe9convenue], et mon dimanche n\u2019est pas gai.",glose:"Seul \xe0 Croisset, Flaubert esp\xe9rait la visite de son ami Laporte.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_7/1539"}],infirmer:[{auteur:"Paul d\u2019Ivoi",initiales:"PI",oeuvre:"L\u2019Homme sans visage, 1908",epoque:"XXe",texte:"Il est curieux de constater que le sort ironique semble se complaire \xe0 [infirmer] la plupart de nos appr\xe9ciations.",glose:"Le narrateur, un journaliste, remarque que les \xe9v\xe9nements d\xe9mentent souvent ce qu'on avait pr\xe9vu.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Homme_sans_visage/I/I"}],circonvenir:[{auteur:"Remy de Gourmont",initiales:"RG",oeuvre:"Lettres \xe0 Sixtine, \xab Aux heures attrist\xe9es \xbb",epoque:"XIXe",texte:"Je t\xe2cherai de [circonvenir] ma m\xe8re qui en a dans un coin, mais sous quel pr\xe9texte ?",glose:"L'\xe9crivain cherche un \xe9chantillon d'\xe9toffe pour son amie, et compte amadouer sa m\xe8re pour l'obtenir.",source:"https://fr.wikisource.org/wiki/Lettres_%C3%A0_Sixtine/Aux_heures_attrist%C3%A9es"}],mercantile:[{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"Une exp\xe9rience sportive, Revue du Touring Club de France, avril 1901",epoque:"XXe",texte:"[\u2026] il n\u2019est pas tr\xe8s d\xe9sirable qu\u2019elle prenne \xe0 ce spectacle un trop vif int\xe9r\xeat, car par l\xe0 se d\xe9veloppent l\u2019habitude du pari et cet esprit [mercantile] qui finissent par gangrener le sport et le perdre.",glose:"Le fondateur des Jeux olympiques modernes veut que la foule pratique le sport au lieu de seulement le regarder.",source:"https://fr.wikisource.org/wiki/Une_Exp%C3%A9rience_sportive"}],"d\xe9noter":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Louis Bouilhet, 15 ao\xfbt 1856",epoque:"XIXe",texte:"Tu m\u2019as \xe9crit une sacr\xe9e lettre qui ne [d\xe9note] pas un homme gai, mon pauvre vieux.",glose:"Flaubert r\xe9pond \xe0 son meilleur ami, qui lui a envoy\xe9 une lettre d\xe9courag\xe9e.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0490"}],ascendant:[{auteur:"Germaine de Sta\xebl",initiales:"GS",oeuvre:"Consid\xe9rations sur la R\xe9volution fran\xe7aise, 1818",epoque:"XIXe",texte:"Mais, bien qu\u2019il n\u2019e\xfbt pas pr\xe9cis\xe9ment un parti, il exer\xe7oit de l\u2019[ascendant] sur tous, quand il faisoit usage de la force admirable de son esprit.",glose:"Madame de Sta\xebl d\xe9crit Mirabeau, le grand orateur de l'Assembl\xe9e constituante en 1789.",source:"https://fr.wikisource.org/wiki/Consid%C3%A9rations_sur_%E2%80%A6_la_R%C3%A9volution_Fran%C3%A7aise/Seconde_partie/VI"}]}},264,[]);
__d(function(e,i,r,t,s,u,o){s.exports={stipuler:[{auteur:"Voltaire",initiales:"V",oeuvre:"Essai sur les m\u0153urs, 1756, chapitre 79",epoque:"XVIIIe",texte:"Il fut [stipul\xe9] d\xe8s lors m\xeame que Henri V serait reconnu pour roi [\u2026]",glose:"Voltaire raconte le trait\xe9 qui promettait la couronne de France au roi d'Angleterre.",source:"https://fr.wikisource.org/wiki/Essai_sur_les_m%C5%93urs/Chapitre_79"},{auteur:"Jean-Baptiste Say",initiales:"JS",oeuvre:"Trait\xe9 d'\xe9conomie politique, 1803, livre 1",epoque:"XIXe",texte:"On applique le nom de papier-monnaie \xe0 une v\xe9ritable monnaie de papier qui ne [stipule] pas son remboursement [\u2026]",glose:"L'\xe9conomiste explique ce qui distingue le papier-monnaie d'un simple billet.",source:"https://fr.wikisource.org/wiki/Trait%C3%A9_d%E2%80%99%C3%A9conomie_politique/1841/Livre_1/Chapitre_26"}],marasme:[{auteur:"Antonin Artaud",initiales:"AA",oeuvre:"Le Th\xe9\xe2tre et son double, 1938",epoque:"XXe",texte:"[\u2026] je propose quelque chose pour sortir du [marasme], au lieu de continuer \xe0 g\xe9mir sur ce marasme et sur l\u2019ennui, l\u2019inertie et la sottise de tout.",glose:"Artaud veut r\xe9inventer le th\xe9\xe2tre plut\xf4t que se plaindre de son d\xe9clin.",source:"https://fr.wikisource.org/wiki/Le_th%C3%A9%C3%A2tre_et_son_double/VI"},{auteur:"Henri Pirenne",initiales:"HP",oeuvre:"Histoire de Belgique, tome 7, 1932",epoque:"XXe",texte:"Les riches et les industriels qui menaient le mouvement cherchaient vainement \xe0 exploiter le ch\xf4mage et le [marasme] des affaires.",glose:"L'historien d\xe9crit la Belgique au lendemain de la r\xe9volution de 1830.",source:"https://fr.wikisource.org/wiki/Histoire_de_Belgique/VII/Livre_1/Chapitre_1"}],"obs\xe9quieux":[{auteur:"Hippolyte Taine",initiales:"HT",oeuvre:"Les Origines de la France contemporaine, 1875",epoque:"XIXe",texte:"D\u2019ailleurs, il faut bien que tout le monde vive, et il est agr\xe9able d\u2019avoir autour de soi des visages [obs\xe9quieux] et contents.",glose:"Taine d\xe9crit les grandes maisons nobles d'avant la R\xe9volution et leurs nombreux domestiques.",source:"https://fr.wikisource.org/wiki/Les_Origines_de_la_France_contemporaine/Tome_1/Livre_II/Chapitre_2"},{auteur:"Max Des Vignons",initiales:"MD",oeuvre:"Betty petite fille, 1922",epoque:"XXe",texte:"Un ma\xeetre d\u2019h\xf4tel, glabre et [obs\xe9quieux], conduisit les trois arrivants \xe0 une minuscule table vide.",glose:"Betty et ses compagnons entrent dans un restaurant chic.",source:"https://fr.wikisource.org/wiki/Betty_petite_fille/12"}],truchement:[{auteur:"Pierre-Georges Roy",initiales:"PR",oeuvre:"Bigot et sa bande, 1950",epoque:"XXe",texte:"On ne parvenait \xe0 l\u2019intendant Bigot que par le [truchement] de son secr\xe9taire, le sieur Deschenaux [\u2026]",glose:"L'historien qu\xe9b\xe9cois d\xe9crit l'entourage du dernier intendant de la Nouvelle-France.",source:"https://fr.wikisource.org/wiki/Bigot_et_sa_bande/24"},{auteur:"Marcelle Tinayre",initiales:"MT",oeuvre:"Notes d'une voyageuse en Turquie, 1909",epoque:"XXe",texte:"Par le [truchement] du mari, nous \xe9change\xe2mes quelques politesses, mais la conversation languissait un peu.",glose:"La romanci\xe8re rend visite \xe0 la jeune \xe9pouse d'un ami turc.",source:"https://fr.wikisource.org/wiki/Notes_d%E2%80%99une_voyageuse_en_Turquie/04"}],outrepasser:[{auteur:"Camille Germain de Montauzan",initiales:"CG",oeuvre:"Les Aqueducs antiques de Lyon, 1908",epoque:"XXe",texte:"Il semble qu\u2019ils aient eu souvent des tendances \xe0 [outrepasser] leurs pouvoirs et empi\xe9ter sur ceux du titulaire.",glose:"L'historien parle des adjoints du responsable des eaux de Rome, sous l'Empire.",source:"https://fr.wikisource.org/wiki/Germain_de_Montauzan_-_Les_Aqueducs_antiques/Chapitre_6_-_%C2%A72"}],louvoyer:[{auteur:"Jean-Charles Harvey",initiales:"JH",oeuvre:"Les Demi-civilis\xe9s, 1934",epoque:"XXe",texte:"On avance plus \xe0 [louvoyer] qu\u2019\xe0 baisser les voiles.",glose:"Un personnage conseille au h\xe9ros d'accepter un compromis. Celui-ci refuse.",source:"https://fr.wikisource.org/wiki/Les_demi-civilis%C3%A9s_(Harvey)"}],panache:[{auteur:"Edmond Rostand",initiales:"ER",oeuvre:"Discours de r\xe9ception \xe0 l'Acad\xe9mie fran\xe7aise, 1903",epoque:"XXe",texte:"Le [panache] n\u2019est pas la grandeur, mais quelque chose qui s\u2019ajoute \xe0 la grandeur, et qui bouge au-dessus d\u2019elle.",glose:"L'auteur de Cyrano de Bergerac d\xe9finit le panache devant l'Acad\xe9mie fran\xe7aise.",source:"https://fr.wikisource.org/wiki/Discours_de_r%C3%A9ception_%C3%A0_l%E2%80%99Acad%C3%A9mie_fran%C3%A7aise_(Rostand)"}],"m\xe9ticuleux":[{auteur:"Claude Debussy",initiales:"CD",oeuvre:"Monsieur Croche antidilettante, 1921",epoque:"XXe",texte:"Il a d\u2019abord dirig\xe9 la Symphonie Pastorale avec le soin d\u2019un jardinier [m\xe9ticuleux].",glose:"Le compositeur se moque d'un chef d'orchestre qui joue Beethoven de fa\xe7on trop appliqu\xe9e.",source:"https://fr.wikisource.org/wiki/Monsieur_Croche/Texte_entier"},{auteur:"Albert Thibaudet",initiales:"AT",oeuvre:"La Po\xe9sie de St\xe9phane Mallarm\xe9, 1912",epoque:"XXe",texte:"A la typographie, part essentielle du po\xe8me, Mallarm\xe9 avait mis des soins [m\xe9ticuleux].",glose:"Le critique raconte comment Mallarm\xe9 a cherch\xe9 lui-m\xeame les caract\xe8res d'imprimerie de son po\xe8me.",source:"https://fr.wikisource.org/wiki/La_Po%C3%A9sie_de_St%C3%A9phane_Mallarm%C3%A9/Texte_entier"}],convoiter:[{auteur:"Rabindranath Tagore",initiales:"RT",oeuvre:"La Jeune Lune, \xab B\xe9n\xe9diction \xbb",epoque:"XXe",texte:"Il n\u2019a pas appris \xe0 m\xe9priser la poussi\xe8re et \xe0 [convoiter] l\u2019or.",glose:"Le po\xe8te indien parle d'un tout petit enfant.",source:"https://fr.wikisource.org/wiki/La_Jeune_Lune/B%C3%A9n%C3%A9diction"}],dilapider:[{auteur:"\xc9sope",initiales:"\xc9",oeuvre:"Fables, \xab Le Demi-dieu \xbb, trad. \xc9mile Chambry",epoque:"VIe av. J.-C.",texte:"Cesse, mon ami, de [dilapider] ton bien ; car, si tu d\xe9penses tout et que tu deviennes pauvre, c\u2019est \xe0 moi que tu t\u2019en prendras.",glose:"Un homme se ruine en offrandes. Le demi-dieu qu'il honore lui appara\xeet la nuit pour l'arr\xeater.",source:"https://fr.wikisource.org/wiki/Fables_d%E2%80%99%C3%89sope_(trad._Chambry%2C_1927)/Le_Demi-dieu"},{auteur:"Romain Rolland",initiales:"RR",oeuvre:"Jean-Christophe, La Nouvelle Journ\xe9e, 1912",epoque:"XXe",texte:"[\u2026] ne sois pas assez fou pour [dilapider] en niaiseries ta vigueur impatiente [\u2026]",glose:"Un conseil donn\xe9 \xe0 un jeune homme, dans le dernier tome du roman.",source:"https://fr.wikisource.org/wiki/La_Nouvelle_Journ%C3%A9e/III%2C_2"}],anodin:[{auteur:"Edmond Lepelletier",initiales:"EL",oeuvre:"Paul Verlaine, sa vie, son \u0153uvre, 1907",epoque:"XXe",texte:"Le pr\xe9texte \xe9tait un article, qui aujourd\u2019hui para\xeetrait [anodin] et impoursuivable, sur la libert\xe9 de la presse [\u2026]",glose:"Le biographe de Verlaine raconte comment le journal o\xf9 il \xe9crivait a \xe9t\xe9 supprim\xe9.",source:"https://fr.wikisource.org/wiki/Paul_Verlaine%2C_Sa_Vie_-_Son_%C5%92uvre/Texte_entier"},{auteur:"Georges Rodenbach",initiales:"GR",oeuvre:"La Vocation, 1895",epoque:"XIXe",texte:"Ce mot qui, au premier aspect, ne semblait que gentil et [anodin], revint plusieurs fois [\u2026]",glose:"Une m\xe8re repense \xe0 une phrase de son fils qui ne l'avait d'abord pas inqui\xe9t\xe9e.",source:"https://fr.wikisource.org/wiki/La_Vocation/Premi%C3%A8re_partie/V"}],"diss\xe9quer":[{auteur:"\xc9mile Zola",initiales:"EZ",oeuvre:"\xc9douard Manet, \xe9tude biographique et critique, 1867",epoque:"XIXe",texte:"Et il y a, pour le critique, une joie p\xe9n\xe9trante \xe0 se dire qu\u2019il peut [diss\xe9quer] un \xeatre, qu\u2019il a \xe0 faire l\u2019anatomie d\u2019un organisme [\u2026]",glose:"Zola explique le plaisir du critique qui \xe9tudie un artiste dans tous ses d\xe9tails.",source:"https://fr.wikisource.org/wiki/%C3%89douard_Manet%2C_%C3%A9tude_biographique_et_critique/Texte_entier"}],prouesse:[{auteur:"Jean Bruch\xe9si",initiales:"JB",oeuvre:"Coups d'ailes, \xab Premier pas \xbb, 1922",epoque:"XXe",texte:"Il s\u2019agissait pour B\xe9b\xe9 / De traverser sa chambrette. / Et tout cela, sans tomber : / Quelle [prouesse] d\u2019athl\xe8te !",glose:"Le po\xe8me raconte les premiers pas d'un b\xe9b\xe9.",source:"https://fr.wikisource.org/wiki/Coups_d%E2%80%99ailes/Premier_pas"}],vilipender:[{auteur:"Hippocrate",initiales:"H",oeuvre:"De l'art, trad. Charles Daremberg",epoque:"Ve av. J.-C.",texte:"Il est des hommes qui se font un art de [vilipender] les arts.",glose:"Le m\xe9decin grec ouvre ainsi sa d\xe9fense de la m\xe9decine contre ceux qui la d\xe9nigrent.",source:"https://fr.wikisource.org/wiki/De_l%E2%80%99art_(Hippocrate%2C_trad._Daremberg)"}],lubie:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre au duc de La Valli\xe8re, 26 f\xe9vrier 1755",epoque:"XVIIIe",texte:"Quelle [lubie] vous a pris, monsieur le duc !",glose:"Voltaire s'amuse qu'un grand seigneur de la cour prenne la peine de lui \xe9crire dans sa retraite.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1755/Lettre_2886"},{auteur:"Mark Twain",initiales:"MT",oeuvre:"Plus fort que Sherlock Holm\xe8s, \xab L\u2019Homme au message pour le directeur g\xe9n\xe9ral \xbb",epoque:"XIXe",texte:"Voyons, Jimmy, qui t\u2019a fourr\xe9 cette [lubie] en t\xeate ?",glose:"Un ami s'\xe9tonne de l'id\xe9e fixe du petit Jimmy, qui croit au pouvoir du melon d'eau.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Homme_au_message_pour_le_directeur_g%C3%A9n%C3%A9ral"}],tancer:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Les Mis\xe9rables, 1862, tome 5",epoque:"XIXe",texte:"Les grands-p\xe8res sont faits pour [tancer] les p\xe8res.",glose:"Cosette menace en riant Jean Valjean de le faire gronder par le grand-p\xe8re de Marius.",source:"https://fr.wikisource.org/wiki/Les_Mis%C3%A9rables/Tome_5/Livre_8/01"}],"exub\xe9rant":[{auteur:"Paul Bourget",initiales:"PB",oeuvre:"Une idylle tragique, 1896",epoque:"XIXe",texte:"[Exub\xe9rant] comme je te connais, tu te racontes toujours tout entier \xe0 tout le monde\u2026",glose:"Un ami doute que Corancez garde longtemps secret son mariage.",source:"https://fr.wikisource.org/wiki/Une_idylle_tragique/III"}],"timor\xe9":[{auteur:"Henrik Ibsen",initiales:"HI",oeuvre:"Un ennemi du peuple, 1882, trad. Moritz Prozor",epoque:"XIXe",texte:"[Timor\xe9] ? Oui, quand il s\u2019agit des gros bonnets de chez nous, je suis timor\xe9, monsieur Billing.",glose:"Un imprimeur reconna\xeet qu'il n'ose pas froisser les notables de sa ville.",source:"https://fr.wikisource.org/wiki/Un_Ennemi_du_peuple/Acte_III"},{auteur:"Gustave Lanson",initiales:"GL",oeuvre:"Histoire de la litt\xe9rature fran\xe7aise, 1894",epoque:"XIXe",texte:"Admirateur enthousiaste et [timor\xe9] de Racine, il conservera scrupuleusement les formes l\xe9gu\xe9es par le [\u2026]",glose:"Lanson parle de Voltaire auteur de trag\xe9dies, qui n'ose pas s'\xe9carter du mod\xe8le de Racine.",source:"https://fr.wikisource.org/wiki/Histoire_de_la_litt%C3%A9rature_fran%C3%A7aise_(Lanson)/Cinqui%C3%A8me_partie/Livre_2/Chapitre_2"}],"d\xe9roger":[{auteur:"Constitution f\xe9d\xe9rale suisse",initiales:"CH",oeuvre:"Constitution f\xe9d\xe9rale de la Conf\xe9d\xe9ration suisse, 18 avril 1999, article 101",epoque:"1999",texte:"Elle peut, au besoin, [d\xe9roger] au principe de la libert\xe9 \xe9conomique.",glose:"L'article permet \xe0 la Suisse de prendre des mesures pour prot\xe9ger son \xe9conomie face \xe0 l'\xe9tranger.",source:"https://fr.wikisource.org/wiki/Constitution_f%C3%A9d%C3%A9rale_de_la_Conf%C3%A9d%C3%A9ration_suisse_du_18_avril_1999"}],"h\xe9g\xe9monie":[{auteur:"Theodor Mommsen",initiales:"TM",oeuvre:"Histoire romaine, tome 2",epoque:"XIXe",texte:"Toute [h\xe9g\xe9monie], par la pente naturelle des choses, se transforme t\xf4t ou tard en une domination v\xe9ritable [\u2026]",glose:"L'historien allemand explique comment Rome a fini par dominer ses alli\xe9s latins.",source:"https://fr.wikisource.org/wiki/Histoire_romaine_(Mommsen)/205"},{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"Histoire universelle, tome 2, 1926",epoque:"XXe",texte:"Barcelone exer\xe7ait alors une [h\xe9g\xe9monie] v\xe9ritable ; c\u2019\xe9tait un entrep\xf4t de grand commerce [\u2026]",glose:"Coubertin d\xe9crit la Catalogne du Moyen \xc2ge, au temps des rois d'Aragon.",source:"https://fr.wikisource.org/wiki/Histoire_universelle/Tome_II/XIV"}],"abn\xe9gation":[{auteur:"John Stuart Mill",initiales:"JM",oeuvre:"De l'assujettissement des femmes, 1869",epoque:"XIXe",texte:"Si les femmes valent mieux que les hommes en quelque chose, c\u2019est assur\xe9ment par leur [abn\xe9gation] personnelle en faveur des membres de leur famille [\u2026]",glose:"Le philosophe anglais, d\xe9fenseur de l'\xe9galit\xe9, note qu'on apprend aux femmes \xe0 s'oublier pour les leurs.",source:"https://fr.wikisource.org/wiki/De_l%E2%80%99assujettissement_des_femmes/II"}],aporie:[{auteur:"Pierre de Labriolle",initiales:"PL",oeuvre:"La R\xe9action pa\xefenne, 1934",epoque:"XXe",texte:"[\u2026] Am\xe9lius signalait \xe0 ses auditeurs une \xab [aporie] \xbb, c\u2019est-\xe0-dire une difficult\xe9 apparemment insoluble.",glose:"Un philosophe de l'Antiquit\xe9 soumet \xe0 ses \xe9l\xe8ves une difficult\xe9 tir\xe9e de Platon.",source:"https://fr.wikisource.org/wiki/La_R%C3%A9action_pa%C3%AFenne/Partie_III/Chapitre_I"}],"r\xe9sorber":[{auteur:"Andr\xe9 Gide",initiales:"AG",oeuvre:"Si le grain ne meurt, 1924",epoque:"XXe",texte:"[\u2026] je sentais mon engourdissement se [r\xe9sorber] dans le bien-\xeatre qui r\xe9gnait du haut en bas de la maison.",glose:"Gide se souvient de matins d'hiver o\xf9, enfant, il paressait au lit chez sa tante.",source:"https://fr.wikisource.org/wiki/Si_le_grain_ne_meurt/Partie_I/V"}],"morig\xe9ner":[{auteur:"Tchouang-tseu",initiales:"T",oeuvre:"\u0152uvre de Tchoang-tzeu, trad. L\xe9on Wieger, chapitre 29",epoque:"IVe av. J.-C.",texte:"Les p\xe8res doivent [morig\xe9ner] leurs fils, les fr\xe8res a\xeen\xe9s doivent morig\xe9ner leurs cadets.",glose:"Dans ce dialogue, Confucius rappelle le devoir des a\xeen\xe9s envers les plus jeunes.",source:"https://fr.wikisource.org/wiki/%C5%92uvre_de_Tchoang-tzeu/Chapitre_29._Politiciens"}],"ing\xe9nu":[{auteur:"Vivant Denon",initiales:"VD",oeuvre:"Point de lendemain, 1812",epoque:"XIXe",texte:"[\u2026] j\u2019avais vingt ans, et j\u2019\xe9tais [ing\xe9nu] ; elle me trompa, je me f\xe2chai, elle me quitta.",glose:"Le narrateur se moque du jeune homme na\xeff qu'il \xe9tait, toujours tromp\xe9.",source:"https://fr.wikisource.org/wiki/Point_de_lendemain_(version_de_1812)"}],"f\xe9d\xe9rer":[{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"P\xe9dagogie sportive, 1922",epoque:"XXe",texte:"Nous traversons en ce moment une v\xe9ritable crise de f\xe9d\xe9romanie. Tout le monde veut se [f\xe9d\xe9rer].",glose:"Le fondateur des Jeux olympiques modernes s'amuse de voir chaque club sportif vouloir entrer dans une f\xe9d\xe9ration.",source:"https://fr.wikisource.org/wiki/P%C3%A9dagogie_sportive/II/VI"}],esbroufe:[{auteur:"Edmond Rostand",initiales:"ER",oeuvre:"Chantecler, 1910, acte 1",epoque:"XXe",texte:"Le Paon fait de l\u2019[esbroufe] et le Merle des mots !",glose:"Dans la basse-cour, le vieux chien Patou se m\xe9fie du paon et du merle.",source:"https://fr.wikisource.org/wiki/Chantecler/Acte_1"},{auteur:"Machado de Assis",initiales:"MA",oeuvre:"M\xe9moires posthumes de Bras Cubas, 1881",epoque:"XIXe",texte:"J\u2019avais la passion de l\u2019[esbroufe], de l\u2019annonce et du feu d\u2019artifice.",glose:"Le narrateur avoue qu'il r\xeavait surtout de voir son nom imprim\xe9 sur toutes les affiches.",source:"https://fr.wikisource.org/wiki/M%C3%A9moires_posthumes_de_Braz_Cubas/Chapitre_002"}],flagrant:[{auteur:"L\xe9on Tolsto\xef",initiales:"LT",oeuvre:"Enfance, 1852, chapitre 17, trad. J.-Wladimir Bienstock",epoque:"XIXe",texte:"[\u2026] aux yeux d\xe9sagr\xe9ables, gris-vert, dont l\u2019expression \xe9tait en contradiction [flagrante] avec la petite bouche pliss\xe9e par un attendrissement forc\xe9.",glose:"L'enfant observe une princesse en visite chez sa grand-m\xe8re.",source:"https://fr.wikisource.org/wiki/Enfance_(trad._Bienstock)/Chapitre_17"}],caustique:[{auteur:"Alphonse Allais",initiales:"AA",oeuvre:"\xc0 se tordre, \xab Le Railleur puni \xbb, 1891",epoque:"XIXe",texte:"La boutique \xe9tait sous la garde du jeune Athanase, gar\xe7on apothicaire de beaucoup d\u2019avenir, mais, malheureusement, dou\xe9 d\u2019un esprit [caustique] et railleur.",glose:"Allais pr\xe9sente le h\xe9ros moqueur d'une de ses histoires.",source:"https://fr.wikisource.org/wiki/%C3%80_se_tordre/Le_Railleur_puni"},{auteur:"Andr\xe9 Gide",initiales:"AG",oeuvre:"Si le grain ne meurt, 1924",epoque:"XXe",texte:"[\u2026] toujours ce m\xeame esprit [caustique] envers soi-m\xeame, envers les siens, envers tout ce qu\u2019il aimait [\u2026]",glose:"Gide d\xe9crit Armand, un camarade de jeunesse qui se moquait de tout, \xe0 commencer par lui-m\xeame.",source:"https://fr.wikisource.org/wiki/Si_le_grain_ne_meurt/Partie_I/VI"}],fluctuer:[{auteur:"Journal des \xe9conomistes",initiales:"JE",oeuvre:"Journal des \xe9conomistes, juin 1844, chronique",epoque:"XIXe",texte:"Ce seraient autant de causes perturbatrices, et nous serions expos\xe9s \xe0 voir sans cesse [fluctuer] les prix de revient [\u2026]",glose:"La revue refuse de laisser l'\xc9tat fixer lui-m\xeame les tarifs des chemins de fer.",source:"https://fr.wikisource.org/wiki/Journal_des_%C3%A9conomistes/Juin_1844/Chronique"}],lucratif:[{auteur:"Jean-Jacques Rousseau",initiales:"JR",oeuvre:"Lettre \xe0 M. Vernes, 18 f\xe9vrier 1758",epoque:"XVIIIe",texte:"[\u2026] j\u2019ai bien de la peine \xe0 vivre dans ma retraite d\u2019un travail peu [lucratif] [\u2026]",glose:"Malade, Rousseau confie \xe0 un ami qu'il gagne \xe0 peine sa vie.",source:"https://fr.wikisource.org/wiki/Collection_complete_Rousseau/Piece_30_%3A_Let._%C3%A0_M._Vernes"},{auteur:"Edmond About",initiales:"EA",oeuvre:"ABC du travailleur, 1868",epoque:"XIXe",texte:"[\u2026] les fruits de votre travail, accumul\xe9s par l\u2019\xe9pargne, deviennent les instruments d\u2019un travail plus facile et plus [lucratif].",glose:"L'\xe9crivain explique aux ouvriers \xe0 quoi sert l'\xe9pargne.",source:"https://fr.wikisource.org/wiki/ABC_du_travailleur/IX"}]}},265,[]);
__d(function(e,r,i,s,t,u,a){t.exports={juguler:[{auteur:"Marcellin Pader",initiales:"MP",oeuvre:"De la m\xe9decine dosim\xe9trique, 1877",epoque:"XIXe",texte:"[\u2026] [juguler] la maladie au d\xe9but pour emp\xeacher les d\xe9sordres organiques est le seul espoir d\u2019une cure rapide [\u2026]",glose:"Le m\xe9decin d\xe9fend l'id\xe9e de stopper une maladie d\xe8s ses premiers signes.",source:"https://fr.wikisource.org/wiki/De_la_m%C3%A9decine_dosim%C3%A9trique"}],incongru:[{auteur:"Th\xe9ophile Gautier",initiales:"TG",oeuvre:"Fortunio, 1837, chapitre XIX",epoque:"XIXe",texte:"Quelle sc\xe9l\xe9rate id\xe9e a pouss\xe9 ce damn\xe9 Fortunio \xe0 prononcer [\u2026] un nom aussi [incongru] que celui de Soudja-Sari ?",glose:"Le narrateur s'amuse du nom \xe9trange que son h\xe9ros a laiss\xe9 \xe9chapper.",source:"https://fr.wikisource.org/wiki/Fortunio/19"}],pourfendre:[{auteur:"L\xe9on Hennique",initiales:"LH",oeuvre:"Lettre \xe0 Jules Huret, Enqu\xeate sur l\u2019\xe9volution litt\xe9raire, 1891",epoque:"XIXe",texte:"Je ne peux me r\xe9soudre \xe0 dauber les ma\xeetres, \xe0 \xe9gratigner les \xe9crivains de ma g\xe9n\xe9ration, \xe0 [pourfendre] mes jeunes confr\xe8res [\u2026]",glose:"Interrog\xe9 par un journaliste sur la litt\xe9rature de son temps, le romancier refuse de critiquer ses coll\xe8gues.",source:"https://fr.wikisource.org/wiki/Enqu%C3%AAte_sur_l%E2%80%99%C3%A9volution_litt%C3%A9raire/Les_Naturalistes/M._L%C3%A9on_Hennique"}],scruter:[{auteur:"Pamphile Le May",initiales:"PL",oeuvre:"Les Gouttelettes, 1904",epoque:"XXe",texte:"La mer a ses secrets ; mais le vieux capitaine / Sait la [scruter] encor\u2019 de son \u0153il vigilant.",glose:"Le po\xe8te d\xe9crit un voilier en mer, guid\xe9 par un capitaine qui a l'exp\xe9rience des flots.",source:"https://fr.wikisource.org/wiki/Les_gouttelettes/169"}],"v\xe9racit\xe9":[{auteur:"Pierre-Simon de Laplace",initiales:"PL",oeuvre:"Essai philosophique sur les probabilit\xe9s, 1814",epoque:"XIXe",texte:"La chose, il est vrai, devient souvent impossible, par la difficult\xe9 d\u2019appr\xe9cier la [v\xe9racit\xe9] des t\xe9moins [\u2026]",glose:"Le math\xe9maticien veut calculer le degr\xe9 de confiance qu'on peut accorder \xe0 un t\xe9moignage.",source:"https://fr.wikisource.org/wiki/Essai_philosophique_sur_les_probabilit%C3%A9s/2f"}],"inali\xe9nable":[{auteur:"Jean-Jacques Rousseau",initiales:"JR",oeuvre:"Du contrat social, 1762, livre II, chapitre 1",epoque:"XVIIIe",texte:"Que la souverainet\xe9 est [inali\xe9nable]",glose:"Titre d'un chapitre : le peuple ne peut pas c\xe9der \xe0 un autre son pouvoir de d\xe9cider.",source:"https://fr.wikisource.org/wiki/Du_contrat_social/%C3%89dition_1762/Livre_II/Chapitre_1"}],pusillanime:[{auteur:"Jacques-Henri Meister",initiales:"JM",oeuvre:"De la morale naturelle, 1788, chapitre XXX",epoque:"XVIIIe",texte:"Sous ce double empire, l\u2019\xeatre le plus faible a paru intr\xe9pide, l\u2019homme le plus courageux s\u2019est montr\xe9 [pusillanime].",glose:"Le moraliste observe que la n\xe9cessit\xe9 et la passion peuvent renverser les caract\xe8res.",source:"https://fr.wikisource.org/wiki/De_la_morale_naturelle/XXX"}],protagoniste:[{auteur:"Stendhal",initiales:"S",oeuvre:"Notes sur la com\xe9die, vers 1804",epoque:"XIXe",texte:"L\u2019art de la Com\xe9die [\u2026] ne consiste pas, ce me semble, \xe0 faire faire des choses extraordinaires au [protagoniste] [\u2026]",glose:"Le jeune Stendhal note ses r\xe9flexions sur l'art de faire rire au th\xe9\xe2tre.",source:"https://fr.wikisource.org/wiki/Moli%C3%A8re,_Shakspeare,_la_Com%C3%A9die_et_le_Rire/La_Com%C3%A9die/Notes_sur_la_com%C3%A9die"}],tortueux:[{auteur:"William Shakespeare",initiales:"WS",oeuvre:"Sonnet 121, traduction de Fran\xe7ois-Victor Hugo",epoque:"XVIIe",texte:"Je puis encore \xeatre droit, bien qu\u2019eux-m\xeames soient [tortueux] [\u2026]",glose:"Le po\xe8te r\xe9pond \xe0 ceux qui jugent sa conduite.",source:"https://fr.wikisource.org/wiki/Sonnets_de_Shakespeare_(trad._Hugo)/121"}],bafouer:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 sa ni\xe8ce Caroline, 18 avril 1880",epoque:"XIXe",texte:"Je n\u2019\xe9crirai pas \xe0 Bergerat, parce que je suis en froid avec lui [\u2026] et que je tiens \xe0 le [bafouer], dans son bureau, en public.",glose:"Flaubert est f\xe2ch\xe9 avec Bergerat \xe0 propos de la publication du Ch\xe2teau des C\u0153urs.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_8-9/1982"}],inculquer:[{auteur:"Biographie nationale de Belgique",initiales:"BN",oeuvre:"Notice \xab Boeckstuyns, Jean-Fran\xe7ois \xbb, tome 2",epoque:"XIXe",texte:"[\u2026] tout en enseignant gratuitement la sculpture aux jeunes gens peu fortun\xe9s, il s\u2019appliquait \xe0 leur [inculquer] les principes de la morale [\u2026]",glose:"Le sculpteur, \xe0 Malines, transmettait aussi des valeurs \xe0 ses \xe9l\xe8ves.",source:"https://fr.wikisource.org/wiki/Biographie_nationale_de_Belgique/Tome_2/BOECKSTUYNS,_Jean-Fran%C3%A7ois"}],solennel:[{auteur:"Sainte-Beuve",initiales:"SB",oeuvre:"Les Consolations, 1830, sonnet imit\xe9 de Wordsworth",epoque:"XIXe",texte:"C\u2019est un beau soir, un soir paisible et [solennel] ;",glose:"Le po\xe8te d\xe9crit le calme grave d'une fin de journ\xe9e au bord de la mer.",source:"https://fr.wikisource.org/wiki/Les_Consolations_(Sainte-Beuve)/%C2%AB_C%E2%80%99est_un_beau_soir,_un_soir_paisible_et_solennel_%C2%BB"}],"all\xe9guer":[{auteur:"\xc9sope",initiales:"\xc9",oeuvre:"Le Loup et l\u2019Agneau, traduction d\u2019\xc9mile Chambry, 1927",epoque:"Antiquit\xe9",texte:"Un loup, voyant un agneau qui buvait \xe0 une rivi\xe8re, voulut [all\xe9guer] un pr\xe9texte sp\xe9cieux [\u2026]",glose:"Le loup cherche une fausse excuse : il accuse l'agneau de troubler son eau.",source:"https://fr.wikisource.org/wiki/Fables_d%E2%80%99%C3%89sope_(trad._Chambry,_1927)/Le_Loup_et_l%E2%80%99Agneau"}],"d\xe9savouer":[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, septembre 1755",epoque:"XVIIIe",texte:"On fait courir dans Paris des ouvrages sous mon nom. Je dois saisir l\u2019occasion la plus favorable de les [d\xe9savouer].",glose:"Des textes qu'il n'a pas \xe9crits circulent sous son nom, et Voltaire veut le faire savoir.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1755/Lettre_3004"}],"prosa\xefque":[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 Fr\xe9d\xe9ric II, roi de Prusse, 29 juin 1741",epoque:"XVIIIe",texte:"Sire, le plus [prosa\xefque] de vos serviteurs ne peut rimer davantage.",glose:"Voltaire vient d'\xe9crire des vers au roi, et s'arr\xeate en plaisantant sur son manque d'inspiration.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1741/Lettre_1455"}],estomper:[{auteur:"Paul Gsell",initiales:"PG",oeuvre:"L\u2019Art, entretiens avec Auguste Rodin, 1911",epoque:"XXe",texte:"[\u2026] son pouce, qui \xe9tait revenu sur les traits pour les [estomper], avait interpr\xe9t\xe9 par un tr\xe8s l\xe9ger nuage le charme du model\xe9.",glose:"Gsell regarde les dessins de Rodin, qui adoucissait ses traits de crayon avec le pouce.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Art_(Rodin)/La_Beaut%C3%A9"}],"in\xe9luctable":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 sa ni\xe8ce Caroline, 17 ao\xfbt 1870",epoque:"XIXe",texte:"L\xe0, j\u2019ai vu Mme M***, qui venait au-devant de son [in\xe9luctable] gendre.",glose:"\xc0 la gare, Flaubert croise une dame venue chercher un gendre qu'elle n'a manifestement pas pu \xe9viter.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_6/1118"}],"obtemp\xe9rer":[{auteur:"Voltaire",initiales:"V",oeuvre:"Histoire du parlement de Paris, 1769, chapitre 66",epoque:"XVIIIe",texte:"Le parlement r\xe9pond au roi qu\u2019il ne peut [obtemp\xe9rer]. Ce mot obtemp\xe9rer fit \xe0 la cour un singulier effet. Toutes les femmes demandaient ce que ce mot voulait dire ; et quand elles surent qu\u2019il signifiait ob\xe9ir, elles firent plus de bruit que les ministres [\u2026]",glose:"Le parlement refuse d'ob\xe9ir au roi, et le mot savant fait scandale \xe0 la cour.",source:"https://fr.wikisource.org/wiki/Histoire_du_parlement/%C3%89dition_Garnier/Chapitre_66"}],escamoter:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Ernest Feydeau, 19 d\xe9cembre 1858",epoque:"XIXe",texte:"Des malins emploieraient des ficelles pour [escamoter] la difficult\xe9. Je vais lourdement m\u2019\xe9pater tout au milieu, comme un b\u0153uf.",glose:"Au milieu de l'\xe9criture d'un roman, Flaubert refuse de contourner un passage difficile.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0594"}],insuffler:[{auteur:"Yvonne Sarcey",initiales:"YS",oeuvre:"La Route du bonheur, 1909",epoque:"XXe",texte:"Elle n\u2019a d\u2019autre but que le bien de l\u2019enfant, et s\u2019arrange \xe0 former son caract\xe8re, \xe0 tremper son c\u0153ur, \xe0 lui [insuffler] les sentiments d\u2019honneur et de dignit\xe9 [\u2026]",glose:"L'autrice d\xe9crit la bont\xe9 d'une m\xe8re qui sait \xe9duquer son enfant.",source:"https://fr.wikisource.org/wiki/La_Route_du_bonheur/02/07"}],grandiloquent:[{auteur:"Claude Debussy",initiales:"CD",oeuvre:"Monsieur Croche, \xab Richard Wagner \xbb, 1921",epoque:"XXe",texte:"\xc7a n\u2019est plus cet essoufflement \xe9nerv\xe9 \xe0 poursuivre la passion maladive d\u2019un Tristan [\u2026] ni le commentaire [grandiloquent] de l\u2019inhumanit\xe9 d\u2019un Wotan.",glose:"Le compositeur trouve la derni\xe8re \u0153uvre de Wagner plus apais\xe9e que ses op\xe9ras pr\xe9c\xe9dents.",source:"https://fr.wikisource.org/wiki/Monsieur_Croche/Richard_Wagner"}],"d\xe9daigner":[{auteur:"Nicolas Machiavel",initiales:"NM",oeuvre:"Discours sur la premi\xe8re d\xe9cade de Tite-Live, livre I, titre du chapitre XXXVI, traduction de Jean-Vincent P\xe9ri\xe8s",epoque:"XVIe",texte:"Les citoyens qui ont obtenu les premi\xe8res dignit\xe9s de l\u2019\xc9tat ne doivent pas [d\xe9daigner] les derni\xe8res.",glose:"Celui qui a occup\xe9 les plus hautes fonctions ne doit pas m\xe9priser les plus modestes.",source:"https://fr.wikisource.org/wiki/Discours_sur_la_premi%C3%A8re_d%C3%A9cade_de_Tite-Live"}],cabale:[{auteur:"Hector Berlioz",initiales:"HB",oeuvre:"M\xe9moires, 1870, sommaire du chapitre LI",epoque:"XIXe",texte:"[Cabale] des amis d\u2019Habeneck d\xe9jou\xe9e.",glose:"Berlioz raconte comment des partisans du chef d'orchestre Habeneck ont tent\xe9 de troubler son festival \xe0 l'Op\xe9ra de Paris.",source:"https://fr.wikisource.org/wiki/M%C3%A9moires_de_Hector_Berlioz/51"}],"s'\xe9tioler":[{auteur:"Julien Luchaire",initiales:"JL",oeuvre:"Discours d\u2019inauguration de l\u2019Institut fran\xe7ais de Florence, 1908",epoque:"XXe",texte:"Comprim\xe9e entre des \xe9mules puissantes par leurs traditions et par leurs ressources, elle semblait condamn\xe9e \xe0 [s'\xe9tioler] et \xe0 p\xe9rir.",glose:"Il parle de l'universit\xe9 de Grenoble, longtemps petite, qui a fini par grandir et prosp\xe9rer.",source:"https://fr.wikisource.org/wiki/Inauguration_de_l%E2%80%99Institut_fran%C3%A7ais_de_Florence"}],"on\xe9reux":[{auteur:"Montesquieu",initiales:"M",oeuvre:"De l\u2019esprit des lois, 1748, livre VII, chapitre 3",epoque:"XVIIIe",texte:"Les riches employoient leur argent en f\xeates, en ch\u0153urs de musique, en chariots, en chevaux pour la course, en magistrature [on\xe9reuse].",glose:"Dans les cit\xe9s grecques, les riches finan\xe7aient les f\xeates et des charges publiques qui co\xfbtaient cher.",source:"https://fr.wikisource.org/wiki/Esprit_des_lois_(1777)/L7/C3"}],"acuit\xe9":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Ernest Feydeau, octobre 1859",epoque:"XIXe",texte:"Le seul moyen dans ces crises-l\xe0 de ne pas trop souffrir, c\u2019est de s\u2019\xe9tudier soi-m\xeame d\xe9mesur\xe9ment, et la chose est possible, car l\u2019esprit a une [acuit\xe9] extraordinaire.",glose:"Flaubert conseille un ami \xe9crivain qui traverse une \xe9preuve.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_4/0621"}]}},266,[]);
__d(function(e,r,i,t,s,u,o){s.exports={"iniquit\xe9":[{auteur:"Voltaire",initiales:"V",oeuvre:"Correspondance, lettre 1890, 1748",epoque:"XVIIIe",texte:"[\u2026] tous les honn\xeates gens, vous sauront gr\xe9 d\u2019avoir arr\xeat\xe9 cette [iniquit\xe9].",glose:"Voltaire remercie son correspondant d\u2019avoir mis fin \xe0 une injustice li\xe9e \xe0 un livre vendu chez les libraires.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1748/Lettre_1890"}],stigmatiser:[{auteur:"Fran\xe7ois Arago",initiales:"FA",oeuvre:"Astronomie populaire, 1855, livre XVII",epoque:"XIXe",texte:"C\u2019est \xe0 cette occasion que notre savant com\xe9tographe, Pingr\xe9, voulant [stigmatiser] la cr\xe9dulit\xe9 de Kepler, lui appliqua ces paroles d\u2019Horace [\u2026]",glose:"L\u2019astronome Pingr\xe9 reprochait publiquement \xe0 Kepler d\u2019avoir cru trop vite qu\u2019une com\xe8te s\u2019\xe9tait coup\xe9e en morceaux.",source:"https://fr.wikisource.org/wiki/Astronomie_populaire_(Arago)/XVII/24"},{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Guy de Maupassant, f\xe9vrier 1880",epoque:"XIXe",texte:"Il fallait prendre le ton badin, traiter cela plus d\xe9licatement, plus finement, [stigmatiser] en passant avec une pointe d\u2019\xe9l\xe9gance [\u2026]",glose:"Flaubert imite, pour s\u2019en moquer, les reproches qu\u2019un critique bien-pensant ferait \xe0 un po\xe8me de Maupassant.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_8-9/1957"}],cupide:[{auteur:"Shakespeare",initiales:"WS",oeuvre:"Sonnets, 134, traduction de Fran\xe7ois-Victor Hugo",epoque:"XVIIe",texte:"Mais tu ne veux pas, toi, le laisser libre, et il ne veut pas l\u2019\xeatre, car tu es [cupide], et il est g\xe9n\xe9reux.",glose:"Le po\xe8te reproche \xe0 la femme aim\xe9e de garder son ami pour elle, comme une usuri\xe8re garde un gage.",source:"https://fr.wikisource.org/wiki/Sonnets_de_Shakespeare_(trad._Hugo)/134"}],"d\xe9concerter":[{auteur:"Madame de S\xe9vign\xe9",initiales:"MS",oeuvre:"Lettres, lettre 492",epoque:"XVIIe",texte:"Le Coetquen demeura fort [d\xe9concert\xe9], et s\u2019en retourna enrag\xe9 se coucher [\u2026]",glose:"Le marquis de Coetquen vient d\u2019\xeatre \xe9conduit s\xe8chement.",source:"https://fr.wikisource.org/wiki/Lettre_de_S%C3%A9vign%C3%A9_492"},{auteur:"Laurence Sterne",initiales:"LS",oeuvre:"Vie et opinions de Tristram Shandy, traduction de Frenais, 1803",epoque:"XVIIIe",texte:"Mon oncle Tobie ne s\u2019attendoit pas \xe0 le voir sit\xf4t reparo\xeetre ; et il fut un peu [d\xe9concert\xe9] de sa pr\xe9sence subite.",glose:"L\u2019oncle Tobie est surpris par le retour soudain du p\xe8re du narrateur.",source:"https://fr.wikisource.org/wiki/Vie_et_opinions_de_Tristram_Shandy/2/85"}],"ob\xe9rer":[{auteur:"Anatole Leroy-Beaulieu",initiales:"AL",oeuvre:"L\u2019Empire des tsars et les Russes, 1890",epoque:"XIXe",texte:"Cela, il a d\xfb le faire avec un budget [ob\xe9r\xe9], en face d\u2019une Europe en armes.",glose:"Le tsar Alexandre III a d\xfb r\xe9former l\u2019imp\xf4t avec des finances d\xe9j\xe0 lourdement charg\xe9es.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Empire_des_tsars_et_les_Russes/Tome_1/Avant-propos_de_la_troisi%C3%A8me_%C3%A9dition"}],"sans ambages":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Georges Charpentier, octobre 1874",epoque:"XIXe",texte:"[\u2026] et lui parlerai de ce qu\u2019il m\u2019avait promis, carr\xe9ment, [sans ambages], ni circonlocutions.",glose:"Flaubert compte r\xe9clamer franchement \xe0 Renan ce qu\u2019il lui avait promis.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_7/1507"}],"d\xe9bonnaire":[{auteur:"Joseph B\xe9dier",initiales:"JB",oeuvre:"Le Roman de Tristan et Iseut, 1900, chapitre XIV",epoque:"XIXe",texte:"Le duc \xe9tait jeune, puissant, [d\xe9bonnaire] ; il l\u2019accueillit comme un h\xf4te bienvenu.",glose:"Tristan, exil\xe9, trouve refuge chez le duc Gilain, au pays de Galles.",source:"https://fr.wikisource.org/wiki/Le_Roman_de_Tristan_et_Iseut/14"}],"inv\xe9t\xe9r\xe9":[{auteur:"Robert L\xe9ger",initiales:"RL",oeuvre:"Les Id\xe9es d\u2019Antonio Fogazzaro, Revue des Deux Mondes, 1907",epoque:"XXe",texte:"[\u2026] elle a \xe9pous\xe9 un joueur [inv\xe9t\xe9r\xe9], d\u2019esprit vulgaire et d\u2019\xe2me grossi\xe8re [\u2026]",glose:"Le critique r\xe9sume un roman de l\u2019Italien Fogazzaro et pr\xe9sente le mari d\u2019H\xe9l\xe8ne.",source:"https://fr.wikisource.org/wiki/Les_Id%C3%A9es_d%E2%80%99Antonio_Fogazzaro"}],exhorter:[{auteur:"Joseph Lallier",initiales:"JL",oeuvre:"Ang\xe9line Guillou, 1930, chapitre XII",epoque:"XXe",texte:"Les femmes s\u2019\xe9taient r\xe9fugi\xe9es \xe0 l\u2019\xe9glise o\xf9 elles pass\xe8rent une partie de la nuit en pri\xe8res avec le cur\xe9, qui les [exhortait] au courage.",glose:"Une nuit de temp\xeate, au bord de la mer.",source:"https://fr.wikisource.org/wiki/Ang%C3%A9line_Guillou/12"}],scabreux:[{auteur:"Jules Gourdault",initiales:"JG",oeuvre:"Revue litt\xe9raire, Revue des Deux Mondes, 1864",epoque:"XIXe",texte:"Ne semble-t-il pas que tout romancier qui aborde un sujet [scabreux] prend l\u2019engagement de faire un chef-d\u2019\u0153uvre ?",glose:"Le critique parle d\u2019un roman d\u2019Ars\xe8ne Houssaye dont les h\xe9ros viennent du demi-monde.",source:"https://fr.wikisource.org/wiki/Revue_litt%C3%A9raire_-_14_octobre_1864"}],poncif:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Ivan Tourgueneff, 14 d\xe9cembre 1876",epoque:"XIXe",texte:"Voil\xe0 o\xf9 m\xe8nent l\u2019abus de l\u2019esprit et la peur de tomber dans les [poncifs].",glose:"Flaubert se moque de Goncourt, pour qui la litt\xe9rature fran\xe7aise commence avec Balzac.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_7/1623"},{auteur:"Paul Acker",initiales:"PA",oeuvre:"Humour et humoristes, 1899, \xab Grosclaude \xbb",epoque:"XIXe",texte:"Tous ces clich\xe9s, tous ces [poncifs], que tu empruntes \xe0 la politique, au journalisme, \xe0 la science, \xe0 l\u2019administration [\u2026]",glose:"Dans une fantaisie, un petit \xe9l\xe9phant reproche \xe0 l\u2019\xe9crivain de parler par formules toutes faites.",source:"https://fr.wikisource.org/wiki/Humour_et_humoristes/Grosclaude"}],"sp\xe9cieux":[{auteur:"Ren\xe9 Doumic",initiales:"RD",oeuvre:"Le Po\xe8te de la vie int\xe9rieure, Sully Prudhomme, Revue des Deux Mondes, 1907",epoque:"XXe",texte:"Les partisans de ce genre de confidences ont coutume d\u2019invoquer un argument [sp\xe9cieux] : \xab Et de qui donc, demandent-ils, le po\xe8te nous parlerait-il, si ce n\u2019est de lui-m\xeame ? \xbb",glose:"Le critique discute l\u2019id\xe9e qu\u2019un po\xe8te devrait raconter sa vie amoureuse dans ses vers.",source:"https://fr.wikisource.org/wiki/Revue_litt%C3%A9raire_-_Le_Po%C3%A8te_de_la_vie_int%C3%A9rieure%2C_Sully_Prudhomme"}],outrecuidance:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Mme Roger des Genettes, 6 octobre 1871",epoque:"XIXe",texte:"J\u2019ai peur que vous ne suiviez un tr\xe8s mauvais r\xe9gime. Pardonnez-moi cette [outrecuidance], mais j\u2019ai, \xe0 mes d\xe9pens, acquis beaucoup d\u2019exp\xe9rience en fait de n\xe9vroses.",glose:"Flaubert s\u2019excuse de donner des conseils de sant\xe9 \xe0 une amie.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_6/1211"}],"\xe9sot\xe9rique":[{auteur:"Charles Nordmann",initiales:"CN",oeuvre:"La Pr\xe9paration du tir de l\u2019artillerie, Revue des Deux Mondes, 1917",epoque:"XXe",texte:"Dans l\u2019expos\xe9 que je voudrais faire ici de ces solutions classiques et en \xe9vitant le langage [\xe9sot\xe9rique] des initi\xe9s, ces sp\xe9cialistes ne d\xe9couvriront rien, je pense, qui ne leur soit connu [\u2026]",glose:"Le savant promet d\u2019expliquer une question technique sans le jargon des sp\xe9cialistes.",source:"https://fr.wikisource.org/wiki/Revue_scientifique_-_La_Pr%C3%A9paration_du_tir_de_l%E2%80%99artillerie"}],astreindre:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 Chabanon, 1766",epoque:"XVIIIe",texte:"Il faut \xeatre bien ma\xeetre de son g\xe9nie pour [s\u2019astreindre] \xe0 un tel travail, et pour subjuguer ainsi le talent qui demande toujours \xe0 parler en vers.",glose:"Voltaire admire un auteur qui \xe9crit en prose le plan de sa pi\xe8ce avant de la mettre en vers.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1766/Lettre_6356"},{auteur:"Edmond de Goncourt",initiales:"EG",oeuvre:"Les Fr\xe8res Zemganno, 1879, chapitre LI",epoque:"XIXe",texte:"[\u2026] les hommes de leur \xe9tat doivent [s\u2019astreindre] \xe0 une hygi\xe8ne de pr\xeatres [\u2026]",glose:"Deux fr\xe8res acrobates suivent la vieille r\xe8gle de vie des athl\xe8tes romains.",source:"https://fr.wikisource.org/wiki/Les_Fr%C3%A8res_Zemganno/51"}],indolent:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 Damilaville, 4 octobre 1763",epoque:"XVIIIe",texte:"Je demande pardon \xe0 fr\xe8re Thieriot, c\u2019est-\xe0-dire \xe0 fr\xe8re [indolent], d\u2019\xeatre aussi indolent que lui, et de ne lui point \xe9crire [\u2026]",glose:"Voltaire s\u2019excuse, avec humour, de ne pas avoir \xe9crit \xe0 son ami Thieriot.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1763/Lettre_5425"},{auteur:"Louis Fr\xe9chette",initiales:"LF",oeuvre:"Les Fleurs bor\xe9ales, 1879, \xab La Louisianaise \xbb",epoque:"XIXe",texte:"Pays de douce nonchalance, / O\xf9 le hamac toujours balance / A l\u2019ombre des verts bananiers, / Son heureuse [indolence]",glose:"Le po\xe8te qu\xe9b\xe9cois chante la Louisiane.",source:"https://fr.wikisource.org/wiki/Les_Fleurs_bor%C3%A9ales/La_Louisianaise"}],clairvoyant:[{auteur:"Sully Prudhomme",initiales:"SP",oeuvre:"Le Bonheur, d\xe9dicace",epoque:"XIXe",texte:"[\u2026] je d\xe9die ce po\xe8me qui doit tant \xe0 la sollicitude et \xe0 la [clairvoyance] de sa critique.",glose:"Le po\xe8te remercie son ami Gaston Paris, qui a relu son po\xe8me avec un \u0153il s\xfbr.",source:"https://fr.wikisource.org/wiki/Le_Bonheur_(Sully_Prudhomme)/D%C3%A9dicace"}],sollicitude:[{auteur:"Anatole France",initiales:"AF",oeuvre:"Nos enfants, 1887, \xab Le Jour de Catherine \xbb",epoque:"XIXe",texte:"Elle les traite toutes avec [sollicitude] et, si elle peut montrer quelque pr\xe9f\xe9rence, ce n\u2019est qu\u2019aux plus modestes et aux moins heureuses.",glose:"L\u2019auteur d\xe9crit ce que fait une bonne ma\xeetresse de maison avec ses invit\xe9es.",source:"https://fr.wikisource.org/wiki/Nos_enfants/Le_Jour_de_Catherine"},{auteur:"Louisa Siefert",initiales:"LS",oeuvre:"Rayons perdus, 1869, \xab Le Banc \xbb",epoque:"XIXe",texte:"Mon petit chien me garde avec [sollicitude]",glose:"La po\xe9tesse r\xeave sur son banc favori, veill\xe9e par son chien.",source:"https://fr.wikisource.org/wiki/Rayons_perdus_(1869)/Le_Banc"}],nonchalant:[{auteur:"Edmond Haraucourt",initiales:"EH",oeuvre:"L\u2019\xc2me nue, 1885, \xab Le N\xe9nuphar \xbb",epoque:"XIXe",texte:"Seul, berc\xe9 dans sa fi\xe8re et souple [nonchalance], / Un N\xe9nuphar, splendeur nageante, se balance",glose:"Un n\xe9nuphar blanc flotte sur l\u2019eau sombre d\u2019un \xe9tang.",source:"https://fr.wikisource.org/wiki/L%E2%80%99%C3%82me_nue/Le_N%C3%A9nuphar"}],"pr\xe9judice":[{auteur:"Am\xe9d\xe9e Fraigneau",initiales:"AF",oeuvre:"Rouen bizarre, 1888, \xab Les graisseux \xbb",epoque:"XIXe",texte:"[\u2026] nous pensons qu\u2019il y a l\xe0 une exag\xe9ration capable de porter [pr\xe9judice] \xe0 d\u2019honorables commer\xe7ans [\u2026]",glose:"Le chroniqueur d\xe9fend des marchands de Rouen contre une rumeur.",source:"https://fr.wikisource.org/wiki/Rouen_Bizarre/Les_m%C3%A9tiers_bizarres/Les_graisseux"},{auteur:"\xc9pict\xe8te",initiales:"\xc9",oeuvre:"Entretiens, livre II, traduction de Victor Courdaveaux, 1862",epoque:"IIe",texte:"Regarder tout ce qu\u2019on a comme \xe9tant \xe0 son p\xe8re, lui ob\xe9ir en tout, ne jamais le bl\xe2mer devant personne, ne rien dire ou ne rien faire qui puisse lui porter [pr\xe9judice] [\u2026]",glose:"Le philosophe \xe9num\xe8re les devoirs d\u2019un fils envers son p\xe8re.",source:"https://fr.wikisource.org/wiki/Les_Entretiens_d%E2%80%99%C3%89pict%C3%A8te/II/10"}],rebuffade:[{auteur:"Marguerite Audoux",initiales:"MA",oeuvre:"Marie-Claire, 1910, chapitre 4",epoque:"XXe",texte:"Je m\u2019attendais \xe0 une [rebuffade], mais s\u0153ur Marie-Aim\xe9e me sourit, m\u2019embrassa plusieurs fois [\u2026]",glose:"La petite orpheline arrive, intimid\xe9e, dans une nouvelle classe.",source:"https://fr.wikisource.org/wiki/Marie-Claire/4"},{auteur:"Georges Courteline",initiales:"GC",oeuvre:"Messieurs les ronds-de-cuir, 1893",epoque:"XIXe",texte:"[\u2026] trop fin pour laisser le temps de se produire \xe0 une [rebuffade] possible, il prenait le premier la parole [\u2026]",glose:"Un employ\xe9 entre dans un bureau qu\u2019on lui avait ferm\xe9, en parlant le premier.",source:"https://fr.wikisource.org/wiki/Messieurs_les_ronds-de-cuir/VI/1"}],rabrouer:[{auteur:"Robert Alma",initiales:"RA",oeuvre:"L\u2019Aviateur inconnu, 1931, chapitre XIII",epoque:"XXe",texte:"Il essaya derechef de prendre l\u2019offensive. Mais alors, ce fut sa fille qui le [rabroua] [\u2026]",glose:"Un p\xe8re accuse un jeune homme sans preuve, et sa propre fille le remet \xe0 sa place.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Aviateur_inconnu/13"}],emphatique:[{auteur:"Denis Diderot",initiales:"DD",oeuvre:"Lettres \xe0 Mademoiselle Jodin, lettre III",epoque:"XVIIIe",texte:"[\u2026] c\u2019est de garder, au sortir de la sc\xe8ne, je ne sais quel ton [emphatique] qui tient du r\xf4le de princesse qu\u2019on a fait.",glose:"Diderot conseille \xe0 une jeune actrice de laisser son ton de trag\xe9dienne au th\xe9\xe2tre.",source:"https://fr.wikisource.org/wiki/Lettres_%C3%A0_Mademoiselle_Jodin/03"},{auteur:"Alain-Ren\xe9 Lesage",initiales:"AL",oeuvre:"Histoire de Gil Blas de Santillane, livre III",epoque:"XVIIIe",texte:"Il appuyait sur toutes les syllabes, et pronon\xe7ait ses paroles d\u2019un ton [emphatique], avec des gestes et des yeux accommod\xe9s au sujet.",glose:"Gil Blas observe un com\xe9dien qui joue la com\xe9die m\xeame en dehors de la sc\xe8ne.",source:"https://fr.wikisource.org/wiki/Histoire_de_Gil_Blas_de_Santillane/III/11"}],galvaniser:[{auteur:"Frantz Jourdain",initiales:"FJ",oeuvre:"Les D\xe9cor\xe9s, 1895, \xab Marcelin Desboutin \xbb",epoque:"XIXe",texte:"Avec Bracquemond, cet audacieux a r\xe9volutionn\xe9, [galvanis\xe9] la gravure fran\xe7aise qui s\u2019enlisait dans une correction impersonnelle et morne.",glose:"L\u2019auteur salue le graveur Marcelin Desboutin, qui a redonn\xe9 vie \xe0 son art.",source:"https://fr.wikisource.org/wiki/Les_D%C3%A9cor%C3%A9s/Marcelin_Desboutin"},{auteur:"George Sand",initiales:"GS",oeuvre:"Correspondance, 1858",epoque:"XIXe",texte:"Paris est comme [galvanis\xe9] aux approches d\u2019on ne sait quelles crises politiques ou financi\xe8res que les pessimistes voient en noir.",glose:"La romanci\xe8re d\xe9crit l\u2019agitation de Paris en 1858.",source:"https://fr.wikisource.org/wiki/Correspondance_1812-1876%2C_4/1858/CDXXIII"}],simulacre:[{auteur:"Andr\xe9 Gide",initiales:"AG",oeuvre:"Les Faux-monnayeurs, 1925",epoque:"XXe",texte:"[\u2026] il glisse sous les doigts anxieux de Bernard, qui vont fouillant de poche en poche, dans un [simulacre] de recherche d\xe9sesp\xe9r\xe9e, une petite pi\xe8ce de dix sous [\u2026]",glose:"Au guichet, Bernard fait semblant de chercher de l\u2019argent dans ses poches.",source:"https://fr.wikisource.org/wiki/Les_Faux-monnayeurs/1/10"}],"pan\xe9gyrique":[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre sur les pan\xe9gyriques, 1767",epoque:"XVIIIe",texte:"[\u2026] fit, en 1748, le [pan\xe9gyrique] de Louis XV. Cette pi\xe8ce a cela de singulier que l\u2019on n\u2019y voit aucune adulation [\u2026]",glose:"Sous un faux nom, Voltaire commente un \xe9loge du roi \xe9crit par un acad\xe9micien.",source:"https://fr.wikisource.org/wiki/Lettre_sur_les_pan%C3%A9gyriques/%C3%89dition_Garnier"}],compulser:[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 4 avril 1848",epoque:"XIXe",texte:"Armand Bertin m\u2019a parl\xe9 chez V\xe9ron d\u2019un livre sur la vie de Mozart, [compuls\xe9] et extrait de tout ce qui a \xe9t\xe9 fait sur lui [\u2026]",glose:"Le peintre note qu\u2019on va lui pr\xeater une biographie rare de Mozart.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/4_avril_1848"},{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre au comte d\u2019Argental, 1769",epoque:"XVIIIe",texte:"[\u2026] quoi qu\u2019en dise mon gros petit neveu, qui a [compuls\xe9] les registres de la Tournelle de cette ann\xe9e, au lieu de ceux de 1767 [\u2026]",glose:"Voltaire reproche \xe0 son neveu d\u2019avoir fouill\xe9 les registres de la mauvaise ann\xe9e.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1769/Lettre_7647"}],apologie:[{auteur:"Andr\xe9 Gide",initiales:"AG",oeuvre:"De l\u2019influence en litt\xe9rature, 1900",epoque:"XIXe",texte:"Mesdames, Messieurs, Je viens ici faire l\u2019[apologie] de l\u2019influence.",glose:"Premi\xe8re phrase d\u2019une conf\xe9rence o\xf9 Gide prend la d\xe9fense de l\u2019influence en litt\xe9rature.",source:"https://fr.wikisource.org/wiki/De_l%E2%80%99influence_en_litt%C3%A9rature"},{auteur:"Choderlos de Laclos",initiales:"CL",oeuvre:"Les Liaisons dangereuses, 1782, lettre 50",epoque:"XVIIIe",texte:"En effet, dans le moment m\xeame o\xf9 vous croyez faire l\u2019[apologie] de l\u2019amour, que faites-vous au contraire, que m\u2019en montrer les orages redoutables ?",glose:"Mme de Tourvel r\xe9pond \xe0 une lettre o\xf9 Valmont vantait l\u2019amour.",source:"https://fr.wikisource.org/wiki/Les_Liaisons_dangereuses/Lettre_50"}]}},267,[]);
__d(function(e,r,i,s,t,a,u){t.exports={patent:[{auteur:"Alexandre Dumas",initiales:"AD",oeuvre:"Joseph Balsamo, chapitre 70",epoque:"XIXe",texte:"Il n\u2019y a pas d\u2019imprudence l\xe0 o\xf9 il n\u2019y a pas de danger [patent], et il n\u2019y a pas de danger patent \xe0 aller voir un feu d\u2019artifice.",glose:"Dans le roman, Rousseau r\xe9pond aux voisines qui jugent imprudent d\u2019aller se m\xealer \xe0 la foule.",source:"https://fr.wikisource.org/wiki/Joseph_Balsamo/Chapitre_LXX"}],irascible:[{auteur:"Jules Verne",initiales:"JV",oeuvre:"Voyage au centre de la Terre, chapitre 1, 1864",epoque:"XIXe",texte:"Mais de faire entendre raison au plus [irascible] des professeurs, c\u2019est ce que mon caract\xe8re un peu ind\xe9cis ne me permettait pas.",glose:"Le jeune Axel redoute le retour de son oncle, le professeur Lidenbrock.",source:"https://fr.wikisource.org/wiki/Voyage_au_centre_de_la_Terre/Chapitre_1"}],insidieux:[{auteur:"Pierre-Michel Hennin",initiales:"PH",oeuvre:"Lettre \xe0 Voltaire, 7 janvier 1766",epoque:"XVIIIe",texte:"Ce Droit n\xe9gatif, qui n\u2019est pas d\u2019un sot, m\u2019a paru un ouvrage tr\xe8s-[insidieux], o\xf9 le point principal de la question est mis habilement de c\xf4t\xe9 [\u2026]",glose:"Le r\xe9sident de France \xe0 Gen\xe8ve donne \xe0 Voltaire son avis sur une brochure politique.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1766/Lettre_6223"},{auteur:"Christophe",initiales:"C",oeuvre:"L\u2019Id\xe9e fixe du savant Cosinus",epoque:"XIXe",texte:"Puis, habilement, le juge fait \xe0 Cosinus cette [insidieuse] question : \xab Que faisiez-vous le 23 juillet 1847, \xe0 7h 32m 27s du soir ? \xbb",glose:"Dans cette bande dessin\xe9e pionni\xe8re, le savant distrait a oubli\xe9 jusqu\u2019\xe0 son propre nom.",source:"https://fr.wikisource.org/wiki/L%E2%80%99Id%C3%A9e_fixe_du_savant_Cosinus_(large)/22"}],dissiper:[{auteur:"Alphonse Aulard",initiales:"AA",oeuvre:"Histoire politique de la R\xe9volution fran\xe7aise, chapitre 2",epoque:"XIXe",texte:"En tout cas, voici comment le malentendu entre la bourgeoisie et le peuple se [dissipa] ou s\u2019att\xe9nua, \xe0 l\u2019occasion de la convocation et des cahiers.",glose:"L\u2019historien raconte la r\xe9daction des cahiers de dol\xe9ances, en 1789.",source:"https://fr.wikisource.org/wiki/Histoire_politique_de_la_R%C3%A9volution_fran%C3%A7aise/Chapitre_2"},{auteur:"James Fenimore Cooper",initiales:"JC",oeuvre:"Pr\xe9caution, chapitre 30, traduction Defauconpret",epoque:"XIXe",texte:"Julia, rest\xe9e seule avec son oncle, s\u2019empressa de lui raconter son histoire, et ce r\xe9cit [dissipa] tous les doutes qui auraient pu lui rester encore sur sa conduite.",glose:"Dans ce roman de m\u0153urs anglais, une jeune femme retrouve son oncle et lui raconte son histoire.",source:"https://fr.wikisource.org/wiki/Pr%C3%A9caution/Chapitre_XXX"}],aphorisme:[{auteur:"Hector Berlioz",initiales:"HB",oeuvre:"Les Grotesques de la musique, 1859",epoque:"XIXe",texte:"Il faut hurler avec les loups. Quant \xe0 cet [aphorisme], une foule de chanteurs de notre temps en ont reconnu la justesse ; ils en bl\xe2ment seulement la forme ; ils le trouvent trop long de moiti\xe9.",glose:"Le compositeur se moque des chanteurs qui crient au lieu de chanter : pour eux, \xab hurler \xbb suffirait.",source:"https://fr.wikisource.org/wiki/Les_Grotesques_de_la_musique/ch47"}],"stratag\xe8me":[{auteur:"Jean de La Fontaine",initiales:"LF",oeuvre:"Fables, \xab Le Chat et le Renard \xbb",epoque:"XVIIe",texte:"Le chat dit au renard : Fouille en ton sac, ami ; Cherche en ta cervelle matoise Un [stratag\xe8me] s\xfbr : pour moi, voici le mien.",glose:"Le renard se vantait d\u2019avoir cent ruses. Le chat n\u2019en a qu\u2019une : grimper \xe0 l\u2019arbre quand les chiens arrivent.",source:"https://fr.wikisource.org/wiki/Fables_de_La_Fontaine_(%C3%A9d._1874)/Le_Chat_et_le_Renard"}],transiger:[{auteur:"Paul Verlaine",initiales:"PV",oeuvre:"Le Parnasse contemporain, \xab Vers dor\xe9s \xbb, 1866",epoque:"XIXe",texte:"L\u2019art ne veut point de pleurs et ne [transige] pas, Voil\xe0 ma po\xe9tique en deux mots [\u2026]",glose:"Le jeune po\xe8te r\xe9sume en 2 vers sa conception exigeante de l\u2019art.",source:"https://fr.wikisource.org/wiki/Le_Parnasse_contemporain/1866/Vers_dor%C3%A9s"},{auteur:"Honor\xe9 de Balzac",initiales:"HB",oeuvre:"Ursule Mirou\xebt, d\xe9dicace",epoque:"XIXe",texte:"C\u2019est un vrai plaisir, ma ch\xe8re ni\xe8ce, que de te d\xe9dier un livre dont le sujet et les d\xe9tails ont eu l\u2019approbation, si difficile \xe0 obtenir, d\u2019une jeune fille \xe0 qui le monde est encore inconnu, et qui ne [transige] avec aucun des nobles principes d\u2019une sainte \xe9ducation.",glose:"Balzac d\xe9die son roman \xe0 sa ni\xe8ce Sophie, une lectrice exigeante.",source:"https://fr.wikisource.org/wiki/Ursule_Mirou%C3%ABt/D%C3%A9dicace"}],faconde:[{auteur:"Jules Verne",initiales:"JV",oeuvre:"Claudius Bombarnac, chapitre 9, 1892",epoque:"XIXe",texte:"Cela, il me le raconte avec des gestes abondants, [faconde] intarissable, allant et venant, se d\xe9hanchant sur ses jambes \xe9cart\xe9es [\u2026]",glose:"Le narrateur fait connaissance avec un compagnon de voyage bavard et joyeux.",source:"https://fr.wikisource.org/wiki/Claudius_Bombarnac/9"}],complaisant:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Han d\u2019Islande, pr\xe9face de la 2e \xe9dition",epoque:"XIXe",texte:"Il rejeta donc l\u2019id\xe9e d\u2019entonner ses propres louanges par la bouche [complaisante] de messieurs ses \xe9diteurs.",glose:"Hugo explique, avec humour, pourquoi il ne s\u2019est pas fait vanter par ses \xe9diteurs.",source:"https://fr.wikisource.org/wiki/Han_d%E2%80%99Islande/Pr%C3%A9face_de_la_deuxi%C3%A8me_%C3%A9dition"}],abhorrer:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 Madame Calas, 1762",epoque:"XVIIIe",texte:"Vous vous \xeates conduite en digne m\xe8re, en digne \xe9pouse ; on vous doit louer autant qu\u2019on doit [abhorrer] le jugement de Toulouse.",glose:"Voltaire soutient la famille Calas, victime d\u2019un jugement injuste, et salue le courage de la m\xe8re.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1762/Lettre_5025"}],entraver:[{auteur:"Fr\xe9d\xe9ric Bastiat",initiales:"FB",oeuvre:"Essais, \xe9bauches, correspondance",epoque:"XIXe",texte:"Mais [entraver] la presse, c\u2019est entraver la v\xe9rit\xe9 aussi bien que le mensonge.",glose:"L\u2019\xe9conomiste d\xe9fend la libert\xe9 de la presse, m\xeame quand des \xe9crivains en abusent.",source:"https://fr.wikisource.org/wiki/Le_Libre-%C3%A9change_et_autres_%C3%A9crits/Tome_7/Texte_56"}],persifler:[{auteur:"Marquis d\u2019Argenson",initiales:"DA",oeuvre:"Journal et m\xe9moires, 10 d\xe9cembre 1747",epoque:"XVIIIe",texte:"Donnez-moi des avis que je doive suivre ; vous emploieriez beaucoup moins de temps \xe0 me siffler qu\u2019\xe0 me [persifler].",glose:"Le marquis raconte ce qu\u2019il r\xe9pondait \xe0 son fr\xe8re, qui lui donnait des conseils sans valeur.",source:"https://fr.wikisource.org/wiki/Journal_et_m%C3%A9moires_du_marquis_d%E2%80%99Argenson/1747_10_D%C3%A9cembre"}],ambivalent:[{auteur:"Sigmund Freud",initiales:"SF",oeuvre:"Psychopathologie de la vie quotidienne, chapitre 3",epoque:"XXe",texte:"Depuis cet accident, il se trouvait dans un \xe9tat d\u2019\xe2me quelque peu [ambivalent] \xe0 l\u2019\xe9gard de cette dame qu\u2019il aimait certes, mais dont les avances en vue du mariage se heurtaient chez lui \xe0 une r\xe9sistance h\xe9sitante.",glose:"Freud analyse le cas d\u2019un homme qui aimait une dame mais h\xe9sitait \xe0 l\u2019\xe9pouser.",source:"https://fr.wikisource.org/wiki/Psychopathologie_de_la_vie_quotidienne/3"}],effervescence:[{auteur:"Alain",initiales:"A",oeuvre:"Propos sur le bonheur, \xab Effervescence \xbb, 1913",epoque:"XXe",texte:"Mais le vrai danger, c\u2019est l\u2019[effervescence] ; et ici chacun est roi de soi-m\xeame et ma\xeetre des temp\xeates pour sa part.",glose:"Le philosophe explique que les conflits naissent moins des raisons que de l\u2019agitation qui gagne les esprits.",source:"https://fr.wikisource.org/wiki/Propos_sur_le_Bonheur/Effervescence"}],"vitup\xe9rer":[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 sa ni\xe8ce Caroline, 2 d\xe9cembre 1873",epoque:"XIXe",texte:"Nous causerons tout \xe0 l\u2019heure \xab th\xe9\xe2tres \xbb mais d\u2019abord, permets-moi, mon loulou, de te [vitup\xe9rer] sur ton \xe9tourderie [\u2026]",glose:"Flaubert gronde tendrement sa ni\xe8ce, qui ne va pas chercher ses lettres \xe0 la poste.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_7/1419"},{auteur:"Colette",initiales:"C",oeuvre:"Le Fanal bleu, 1949",epoque:"XXe",texte:"Je ne peux pas les [vitup\xe9rer] tout le temps, parce que je les contemple et que de les contempler je les fais miens.",glose:"De sa fen\xeatre, l\u2019\xe9crivaine regarde les enfants qui jouent bruyamment en bas.",source:"https://fr.wikisource.org/wiki/Le_Fanal_bleu/04"}],"infl\xe9chir":[{auteur:"Pierre Loti",initiales:"PL",oeuvre:"Un p\xe8lerin d\u2019Angkor, 1912",epoque:"XXe",texte:"[\u2026] des riens, longuement regard\xe9s au premier \xe2ge, suffisent pour [infl\xe9chir], dans un sens ou dans un autre, toute la suite de leur destin\xe9e.",glose:"Loti se souvient du petit mus\xe9e de son enfance, qui a orient\xe9 toute sa vie.",source:"https://fr.wikisource.org/wiki/Un_p%C3%A8lerin_d%E2%80%99Angkor/13"},{auteur:"Henri Bergson",initiales:"HB",oeuvre:"L\u2019\xc9nergie spirituelle, chapitre 6, 1919",epoque:"XXe",texte:"Il faut les modifier plus ou moins, [infl\xe9chir] chacun d\u2019eux dans la direction du mouvement g\xe9n\xe9ral de la valse [\u2026]",glose:"Le philosophe explique comment on apprend \xe0 valser \xe0 partir des gestes de la marche.",source:"https://fr.wikisource.org/wiki/L%E2%80%99%C3%89nergie_spirituelle/Chapitre_VI"}],"empi\xe9ter":[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre au contr\xf4leur g\xe9n\xe9ral, 1767",epoque:"XVIIIe",texte:"[\u2026] je viens seulement, monsieur, [empi\xe9ter] sur vos attributions et contr\xf4ler le chiffre de 2,000 livres dont Sa Majest\xe9 a bien voulu me gratifier.",glose:"Voltaire propose au ministre de partager sa propre pension avec l\u2019\xe9crivain La Harpe, qui n\u2019en a pas.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1767/Lettre_6709"}],"r\xe9dhibitoire":[{auteur:"Aristide Filiatreault",initiales:"AF",oeuvre:"Contes, anecdotes et r\xe9cits canadiens, 1910",epoque:"XXe",texte:"Ang\xe9lique avait beaucoup de qualit\xe9s solides, mais elle avait aussi un d\xe9faut [r\xe9dhibitoire] dont elle ne s\u2019est jamais gu\xe9rie : elle se fourrait le nez dans toutes les affaires qui ne la regardaient pas.",glose:"Le conteur canadien fait le portrait d\u2019Ang\xe9lique, une ancienne infirmi\xe8re install\xe9e \xe0 Montr\xe9al.",source:"https://fr.wikisource.org/wiki/Contes%2C_anecdotes_et_r%C3%A9cits_canadiens_dans_le_langage_du_terroir/L%E2%80%99Appendicite"},{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Lettre \xe0 Maxime Du Camp, 26 juin 1852",epoque:"XIXe",texte:"Tu me parais avoir \xe0 mon endroit un tic ou vice [r\xe9dhibitoire].",glose:"Flaubert r\xe9pond \xe0 son ami, qui le presse de se d\xe9p\xeacher et de prendre sa place \xe0 Paris.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_2/0327"}],subjuguer:[{auteur:"Voltaire",initiales:"V",oeuvre:"Lettre \xe0 Lekain, 25 f\xe9vrier 1767",epoque:"XVIIIe",texte:"Ne vous laissez point [subjuguer], mon cher ami, par un plan tout \xe0 fait antith\xe9\xe2tral qu\u2019on propose.",glose:"Voltaire met en garde son acteur contre un plan de pi\xe8ce qu\u2019on lui propose.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Voltaire/1767/Lettre_6768"},{auteur:"Augusta Coupey",initiales:"AC",oeuvre:"Fables originales, \xab Le Livre \xbb, 1881",epoque:"XIXe",texte:"Je le parcours, la phrase creuse Ne saurait longtemps [subjuguer], \xc0 la longue elle est ennuyeuse, Et finit par vous fatiguer.",glose:"La fabuliste se moque d\u2019un livre \xe0 succ\xe8s, port\xe9 par la presse et les salons.",source:"https://fr.wikisource.org/wiki/Fables_originales/Livre_III/Fable_02"}],"\xe9piloguer":[{auteur:"Alfred de Musset",initiales:"AM",oeuvre:"Lettres",epoque:"XIXe",texte:"Cependant je dois dire que nous discutons beaucoup, je trouve m\xeame qu\u2019on perd trop de temps \xe0 raisonner et [\xe9piloguer].",glose:"Le po\xe8te raconte dans une lettre ses journ\xe9es pass\xe9es \xe0 discuter entre amis.",source:"https://fr.wikisource.org/wiki/Lettres_(Musset)/03"},{auteur:"Ren\xe9 Descartes",initiales:"RD",oeuvre:"M\xe9ditations m\xe9taphysiques, pr\xe9face",epoque:"XVIIe",texte:"Mais pour ceux qui, sans se soucier beaucoup de l\u2019ordre et de la liaison de mes raisons, s\u2019amuseront \xe0 [\xe9piloguer] sur chacune des parties, comme font plusieurs, ceux-l\xe0, dis-je, ne feront pas grand profit de la lecture de ce trait\xe9 [\u2026]",glose:"Le philosophe pr\xe9vient qu\u2019il faut suivre son raisonnement en entier, sans pinailler sur chaque d\xe9tail.",source:"https://fr.wikisource.org/wiki/M%C3%A9ditations_m%C3%A9taphysiques/Pr%C3%A9face"}],"pond\xe9r\xe9":[{auteur:"Guillaume Apollinaire",initiales:"GA",oeuvre:"Lettres \xe0 sa marraine, 18 octobre 1915",epoque:"XXe",texte:"La meilleure fa\xe7on d\u2019\xeatre classique et [pond\xe9r\xe9] est d\u2019\xeatre de son temps en ne sacrifiant rien de ce que les Anciens ont pu nous apprendre.",glose:"Le po\xe8te d\xe9fend ses \xab id\xe9ogrammes \xbb face \xe0 sa marraine, qui ne les comprend pas encore.",source:"https://fr.wikisource.org/wiki/Lettres_%C3%A0_sa_marraine/18_octobre_1915"},{auteur:"Georges Courteline",initiales:"GC",oeuvre:"Messieurs les ronds-de-cuir, 1893",epoque:"XIXe",texte:"\xc0 cet homme de sens [pond\xe9r\xe9] et rassis, le d\xe9traquement c\xe9r\xe9bral de Letondu apparaissait prodigieusement farce et cocasse.",glose:"Dans ce roman comique sur les bureaux d\u2019un minist\xe8re, un employ\xe9 assiste au d\xe9lire d\u2019un coll\xe8gue.",source:"https://fr.wikisource.org/wiki/Messieurs_les_ronds-de-cuir/III/2"}],ersatz:[{auteur:"Simone Weil",initiales:"SW",oeuvre:"La Pesanteur et la Gr\xe2ce, 1947",epoque:"XXe",texte:"Le temps est une image de l\u2019\xe9ternit\xe9, mais c\u2019est aussi un [ersatz] de l\u2019\xe9ternit\xe9.",glose:"La philosophe ouvre ainsi son chapitre \xab Renoncement au temps \xbb.",source:"https://fr.wikisource.org/wiki/La_Pesanteur_et_la_Gr%C3%A2ce/06"}],"h\xe9t\xe9roclite":[{auteur:"Paul Verlaine",initiales:"PV",oeuvre:"Edmond de Goncourt",epoque:"XIXe",texte:"Un cort\xe8ge d\u2019amis et d\u2019inconnus venait ensuite, bizarre ai-je dit, j\u2019aurais d\xfb dire [h\xe9t\xe9roclite] par excellence : les sommit\xe9s de la litt\xe9rature, des arts, de la presse et du monde politique y coudoyaient la plus basse ouvriaille [\u2026]",glose:"Verlaine d\xe9crit la foule tr\xe8s m\xeal\xe9e qui suivait un cort\xe8ge \xe0 travers Paris.",source:"https://fr.wikisource.org/wiki/Edmond_de_Goncourt_(Verlaine)"}],"v\xe9h\xe9ment":[{auteur:"Eus\xe8be Girault de Saint-Fargeau",initiales:"EG",oeuvre:"Revue des romans, 1839",epoque:"XIXe",texte:"Il faut dire aussi que le fougueux Foscolo est autrement [v\xe9h\xe9ment] que le sentimental G\u0153the.",glose:"Le critique compare un roman de l\u2019Italien Foscolo au Werther de Goethe.",source:"https://fr.wikisource.org/wiki/Revue_des_Romans/Ugo_Foscolo"}],"ing\xe9rence":[{auteur:"Georges Rodenbach",initiales:"GR",oeuvre:"Bruges-la-Morte, 1892",epoque:"XIXe",texte:"Mais Hugues la fit taire, \xe9nerv\xe9, humili\xe9 de cette [ing\xe9rence], de cette audace \xe0 lui parler de Jane, et en quels termes !",glose:"Sa vieille servante a os\xe9 lui faire la morale sur la femme qu\u2019il fr\xe9quente.",source:"https://fr.wikisource.org/wiki/Bruges-la-Morte/14"},{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"Notes sur l\u2019\xe9ducation publique",epoque:"XXe",texte:"Tandis que les droits de l\u2019\xc9tat sur l\u2019\xe9cole primaire sont reconnus et proclam\xe9s partout et que son [ing\xe9rence] dans les \xe9tablissements secondaires para\xeet, de jour en jour, plus acceptable, la libert\xe9 demeure le r\xe9gime n\xe9cessaire des universit\xe9s [\u2026]",glose:"Le fondateur des Jeux olympiques modernes r\xe9fl\xe9chit au r\xf4le de l\u2019\xc9tat dans l\u2019enseignement.",source:"https://fr.wikisource.org/wiki/Notes_sur_l%E2%80%99%C3%A9ducation_publique/Chapitre_XV"}],incurie:[{auteur:"Gustave Flaubert",initiales:"GF",oeuvre:"Correspondance, tome 1",epoque:"XIXe",texte:"J\u2019ai une peur atroce que mes dr\xf4les ne lambinent ; ils mettent dans cette affaire une lenteur, une [incurie] incroyables.",glose:"Flaubert s\u2019impatiente : une affaire qui aurait pu se r\xe9gler en 6 semaines tra\xeene depuis 9 mois.",source:"https://fr.wikisource.org/wiki/Correspondance_de_Gustave_Flaubert/Tome_1/0151"},{auteur:"Jules Forni",initiales:"JF",oeuvre:"Le Parnasse contemporain, \xab Le Pauvre Savant \xbb, 1866",epoque:"XIXe",texte:"Et maint bourgeois, par moments, S\u2019indigna que la Voirie Montr\xe2t, pour ses monuments, Une pareille [incurie].",glose:"Dans ce po\xe8me, un pauvre savant reste des heures pensif devant de vieilles murailles.",source:"https://fr.wikisource.org/wiki/Le_Parnasse_contemporain/1866/Le_Pauvre_Savant"}],quolibet:[{auteur:"Victor Hugo",initiales:"VH",oeuvre:"Notre-Dame de Paris, livre 4, chapitre 6",epoque:"XIXe",texte:"[\u2026] plus d\u2019une mauvaise parole, plus d\u2019un fredon ironique, plus d\u2019un [quolibet] insultant les harcelait au passage [\u2026]",glose:"Quand Claude Frollo et Quasimodo traversent ensemble le quartier de la cath\xe9drale, les passants se moquent d\u2019eux.",source:"https://fr.wikisource.org/wiki/Notre-Dame_de_Paris%2C_1844/04/06"}],"fatuit\xe9":[{auteur:"Stendhal",initiales:"S",oeuvre:"Le Rouge et le Noir, chapitre 36, 1830",epoque:"XIXe",texte:"Si la [fatuit\xe9] est pardonnable, c\u2019est dans la premi\xe8re jeunesse, car alors elle est l\u2019exag\xe9ration d\u2019une chose aimable.",glose:"Stendhal ouvre ainsi le chapitre o\xf9 Julien Sorel d\xe9couvre un jeune chevalier tr\xe8s content de lui.",source:"https://fr.wikisource.org/wiki/Le_Rouge_et_le_Noir/Chapitre_XXXVI"}],"d\xe9l\xe9t\xe8re":[{auteur:"Pierre de Coubertin",initiales:"PC",oeuvre:"Anthologie, 1933",epoque:"XXe",texte:"Une influence non moins [d\xe9l\xe9t\xe8re] est exerc\xe9e par la tendance au bavardage qui gagne de proche en proche.",glose:"Coubertin s\u2019inqui\xe8te de l\u2019appauvrissement des langues, ab\xeem\xe9es par les jargons et la vitesse.",source:"https://fr.wikisource.org/wiki/Anthologie_(Pierre_de_Coubertin)/I/XVI"}],frugal:[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 21 juin 1855",epoque:"XIXe",texte:"Je rentrai \xe0 pied du chemin de fer, et, apr\xe8s un d\xe9jeuner plus que [frugal], j\u2019ai dormi tout accabl\xe9 [\u2026]",glose:"Le peintre, \xe9puis\xe9 par une journ\xe9e trop charg\xe9e en \xe9motions, rentre se reposer.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/21_juin_1855"}],"t\xe9nacit\xe9":[{auteur:"Eug\xe8ne Delacroix",initiales:"ED",oeuvre:"Journal, 18 octobre 1852",epoque:"XIXe",texte:"J\u2019ai travaill\xe9 tous ces jours-ci avec une [t\xe9nacit\xe9] extr\xeame, avant d\u2019envoyer mes peintures qu\u2019on colle demain [\u2026]",glose:"Le peintre est rest\xe9 jusqu\u2019\xe0 pr\xe8s de 9 heures par jour devant ses tableaux.",source:"https://fr.wikisource.org/wiki/Journal_(Eug%C3%A8ne_Delacroix)/18_octobre_1852"}],lacune:[{auteur:"Fr\xe9d\xe9ric Bastiat",initiales:"FB",oeuvre:"Sophismes \xe9conomiques, chapitre 17, 1845",epoque:"XIXe",texte:"Avec ce syst\xe8me, on arrive \xe0 un chemin de fer compos\xe9 de [lacunes] successives, \xe0 un chemin de fer n\xe9gatif.",glose:"Bastiat se moque de ceux qui voulaient couper la ligne Paris-Bayonne \xe0 Bordeaux pour forcer les voyageurs \xe0 s\u2019y arr\xeater.",source:"https://fr.wikisource.org/wiki/Sophismes_%C3%A9conomiques/S%C3%A9rie_1/Chapitre_17"}],"\xe9lucider":[{auteur:"Fr\xe9d\xe9ric Bastiat",initiales:"FB",oeuvre:"Lettre \xe0 Richard Cobden",epoque:"XIXe",texte:"Je ne chercherai ni \xe0 faire rire, ni \xe0 faire pleurer, mais \xe0 [\xe9lucider] quelque point ardu de la science.",glose:"L\u2019\xe9conomiste promet \xe0 son ami anglais des discours simples et brefs.",source:"https://fr.wikisource.org/wiki/%C5%92uvres_compl%C3%A8tes_de_Fr%C3%A9d%C3%A9ric_Bastiat/Lettres_%C3%A0_Richard_Cobden/Lettre_16"},{auteur:"Platon",initiales:"P",oeuvre:"Protagoras, traduction Alfred Croiset",epoque:"Antiquit\xe9",texte:"S\u2019il m\u2019est plus agr\xe9able de causer avec toi qu\u2019avec un autre, c\u2019est que je te crois plus capable que personne de m\u2019aider \xe0 [\xe9lucider] toutes les questions auxquelles s\u2019int\xe9ressent les honn\xeates gens [\u2026]",glose:"Socrate explique au sophiste Protagoras pourquoi il tient \xe0 discuter avec lui.",source:"https://fr.wikisource.org/wiki/Protagoras_(trad._Croiset)"}]}},268,[]);
